/* POPSMART content packs (inlined for file:// compatibility) */
window.POPSMART_PACKS = [{"id": "arthist", "title": "Art History", "icon": "palette", "color": "#CD6155", "levels": [{"id": "arthist-1", "title": "Renaissance", "cards": [{"type": "text", "title": "Rebirth of the individual", "body": "The Renaissance (roughly 1400-1600) was Europe's great reboot. After centuries of flat, symbolic medieval art, painters rediscovered the human body, real space, and the individual. Art stopped being only about heaven and started being about people — their muscles, their faces, their world."}, {"type": "text", "title": "Perspective changed everything", "body": "The Renaissance's superpower was linear perspective: parallel lines converging at a vanishing point to create believable depth. Brunelleschi worked out the math, and painters like Masaccio turned flat walls into windows. For the first time, you could feel like you were standing inside the painting."}, {"type": "example", "body": "Look at Leonardo's Last Supper: the architecture's lines all converge behind Christ's head, pulling your eye exactly where Leonardo wants it. The vanishing point isn't just geometry — it's a spotlight. Every Renaissance master used this trick to direct your attention."}, {"type": "tip", "body": "Spot a Renaissance painting fast: realistic bodies with weight and shadow, deep architectural space, and classical references (columns, togas, myths). If the figures look like they could step off the wall, you're in the right century."}, {"type": "check", "q": "What did linear perspective give Renaissance painters?", "choices": ["Believable depth — flat surfaces that look like real space", "Brighter colors than ever before", "A way to paint faster"], "answer": 0, "explain": "Perspective's converging lines create the illusion of three-dimensional space on a flat surface — the defining technical leap of the era."}], "flashcards": [{"type": "flash", "front": "When was the Renaissance, roughly?", "back": "About 1400 to 1600."}, {"type": "flash", "front": "What is linear perspective?", "back": "A technique where parallel lines converge at a vanishing point to create believable depth."}, {"type": "flash", "front": "Name the painter of the Last Supper.", "back": "Leonardo da Vinci."}, {"type": "flash", "front": "How do you spot a Renaissance painting?", "back": "Realistic bodies with weight and shadow, deep space, classical references — figures that feel alive."}], "checkpoint": {"pass": 70, "questions": [{"q": "The Renaissance marked a shift from:", "choices": ["Symbolic medieval art toward realistic, human-centered art", "Realism toward pure abstraction", "Sculpture toward photography"], "answer": 0, "explain": "Medieval art was flat and symbolic, serving theology. The Renaissance revived classical realism and put humans — bodies, faces, minds — at the center."}, {"q": "Who is credited with working out the mathematics of perspective?", "choices": ["Brunelleschi", "Mozart", "Shakespeare"], "answer": 0, "explain": "Filippo Brunelleschi, an architect, demonstrated linear perspective around 1415. Painters ran with it immediately."}, {"q": "In the Last Supper, the perspective lines converge:", "choices": ["Behind Christ's head", "At the table's edge", "Randomly across the wall"], "answer": 0, "explain": "Leonardo aimed every architectural line at Christ's head — geometry as a spotlight, the most famous vanishing point in art."}, {"q": "Which is NOT a Renaissance hallmark?", "choices": ["Flat gold backgrounds with no depth", "Anatomically realistic figures", "Classical columns and myths"], "answer": 0, "explain": "Flat gold backgrounds are medieval. Renaissance painters replaced them with deep space, real bodies, and classical references."}, {"q": "Besides painting, the Renaissance is famous for reviving:", "choices": ["Classical learning — science, anatomy, philosophy", "Feudal warfare", "Monastic isolation"], "answer": 0, "explain": "'Renaissance' means rebirth — of classical antiquity's art, science, and human-centered thinking, all feeding each other."}]}}, {"id": "arthist-2", "title": "Impressionism", "cards": [{"type": "text", "title": "Painting the light, not the thing", "body": "Impressionism (1860s-1880s, mostly France) broke the biggest rule in art: finish your painting carefully in a studio. Instead, Monet, Renoir, and friends dragged easels outdoors and painted fast, capturing how light looked at one exact moment — a sunrise, a ripple, a shadow at 5pm."}, {"type": "text", "title": "Broken color", "body": "Up close, an Impressionist canvas is a mess of separate dabs — blue next to orange, purple beside yellow. Step back and your eye mixes them into shimmering light. They stopped blending paint on the palette and started blending it in the viewer's eye. The name came from a critic's insult: 'just an impression.'"}, {"type": "example", "body": "Monet painted Rouen Cathedral more than 30 times — same building, different hours, different weather. Morning fog turns it blue-grey; sunset sets it ablaze in orange. The subject barely matters; the series is really 30 studies of light itself."}, {"type": "tip", "body": "Spot Impressionism fast: visible brushstrokes, unblended dabs of pure color, everyday scenes (cafes, rivers, gardens), and light that feels like a specific time of day. If it looks blurry up close and glowing from across the room, that's it."}, {"type": "check", "q": "What were the Impressionists mainly trying to capture?", "choices": ["Light at a specific moment", "Perfect anatomical accuracy", "Religious stories"], "answer": 0, "explain": "They painted en plein air (outdoors), racing to catch fleeting light. Accuracy and narrative took a back seat to the sensation of the moment."}], "flashcards": [{"type": "flash", "front": "When and where was Impressionism?", "back": "1860s-1880s, mostly France."}, {"type": "flash", "front": "What is 'broken color'?", "back": "Placing separate dabs of unblended color side by side so the viewer's eye mixes them."}, {"type": "flash", "front": "Why did Monet paint Rouen Cathedral 30+ times?", "back": "To study how the same subject changes under different light, hours, and weather."}, {"type": "flash", "front": "Where did the name 'Impressionism' come from?", "back": "A critic's insult — dismissing the works as 'just an impression' rather than finished paintings."}], "checkpoint": {"pass": 70, "questions": [{"q": "What made Impressionist technique radical for its time?", "choices": ["Painting quickly outdoors with visible, unblended strokes", "Using only black and white", "Painting entirely from memory"], "answer": 0, "explain": "The academy demanded invisible brushwork and studio polish. Painting fast, outside, with raw dabs of color broke every rule at once."}, {"q": "Broken color works because:", "choices": ["The viewer's eye optically mixes adjacent dabs", "The paint chemically blends on the canvas", "Viewers imagine the missing colors"], "answer": 0, "explain": "It's optical mixing — blue and orange dabs side by side read as vibrating light. The blending happens in perception, not on the palette."}, {"q": "Which subject would an Impressionist most likely paint?", "choices": ["A sunlit riverside cafe at dusk", "A formal royal portrait in a studio", "A precise architectural blueprint"], "answer": 0, "explain": "Everyday modern life in fleeting light — cafes, rivers, gardens, stations. Formal portraiture was the establishment style they rejected."}, {"q": "The 1874 first Impressionist exhibition was:", "choices": ["An independent show outside the official Salon", "Commissioned by the French king", "Held inside the Louvre"], "answer": 0, "explain": "Rejected by the official Salon, they staged their own exhibition — the birth certificate of modern art's independent spirit."}, {"q": "Post-Impressionists like Van Gogh and Seurat differed by:", "choices": ["Pushing color and structure further, more deliberately", "Returning to medieval styles", "Abandoning paint for sculpture"], "answer": 0, "explain": "They kept the Impressionists' freedom with color but added structure and emotion — pointillist dots, swirling expression — pointing toward modern art."}]}}, {"id": "arthist-3", "title": "Modern art", "cards": [{"type": "text", "title": "Art stops copying reality", "body": "Modern art (roughly 1900-1970) asked a dangerous question: what if art doesn't have to look like anything? Photography could capture reality perfectly, so painters went the other way — into emotion, ideas, dreams, and pure shape. Cubism, Surrealism, Abstract Expressionism: each broke reality a little more."}, {"type": "text", "title": "Cubism: every angle at once", "body": "Picasso and Braque's Cubism shattered objects into geometric fragments and showed multiple viewpoints simultaneously — a face in profile and front view at the same time. It looks strange because it is: it's a rebellion against the single fixed viewpoint that perspective had enforced for 500 years."}, {"type": "example", "body": "Stand before Picasso's Guernica: screaming figures, a bull, a fallen horse, all in black, white, and grey, fractured across a 25-foot canvas. It depicts the bombing of a Spanish town — not photographically, but as pure anguish made visible. You don't need to 'get' the shapes to feel it."}, {"type": "tip", "body": "When modern art confuses you, ask three questions: what was the artist reacting against, what feeling does it give you before you think, and what would be lost if it looked 'normal'? Confusion is often the intended first step, not a failure."}, {"type": "check", "q": "Why did modern artists move away from realistic depiction?", "choices": ["Photography handled realism, freeing art to explore emotion and ideas", "They forgot how to paint realistically", "Realistic paint became too expensive"], "answer": 0, "explain": "Once cameras captured reality effortlessly, realistic painting lost its monopoly. Artists pivoted to what cameras couldn't do: inner experience, concepts, pure form."}], "flashcards": [{"type": "flash", "front": "Roughly when was modern art?", "back": "About 1900 to 1970."}, {"type": "flash", "front": "What is Cubism?", "back": "Breaking objects into geometric fragments showing multiple viewpoints at once (Picasso, Braque)."}, {"type": "flash", "front": "What does Picasso's Guernica depict?", "back": "The bombing of the Spanish town of Guernica — anguish made visible in fractured black, white, and grey."}, {"type": "flash", "front": "Three questions to ask when modern art confuses you?", "back": "What was the artist reacting against? What do I feel first? What would be lost if it looked 'normal'?"}], "checkpoint": {"pass": 70, "questions": [{"q": "Cubism broke with 500 years of tradition by:", "choices": ["Showing multiple viewpoints simultaneously", "Using only primary colors", "Painting exclusively outdoors"], "answer": 0, "explain": "Since the Renaissance, paintings used one fixed viewpoint. Cubism smashed that — profile and frontal views coexist in a single fractured image."}, {"q": "Surrealism (Dalí, Magritte) drew its imagery mainly from:", "choices": ["Dreams and the unconscious mind", "Newspaper photographs", "Medieval tapestries"], "answer": 0, "explain": "Surrealists mined dreams, free association, and Freud's unconscious — melting clocks and bowler-hatted men are dream logic on canvas."}, {"q": "Abstract Expressionism (Pollock, Rothko) is best described as:", "choices": ["Non-representational painting focused on gesture, color, and emotion", "Highly detailed realistic portraits", "Architectural drafting"], "answer": 0, "explain": "Drip paintings and floating color fields depict nothing recognizable — the painting is the record of an act, or a field of pure feeling."}, {"q": "Pop Art (Warhol) differed from Abstract Expressionism by:", "choices": ["Embracing mass culture and commercial imagery", "Returning to religious subjects", "Banning color entirely"], "answer": 0, "explain": "Warhol's soup cans and Marilyns dragged advertising and celebrity into galleries — high art made from low culture, deliberately."}, {"q": "A good first response to confusing modern art is:", "choices": ["Notice what you feel before analyzing what it means", "Assume it's a fraud and walk away", "Memorize the artist's biography first"], "answer": 0, "explain": "Modern art often targets feeling before intellect. Your raw reaction is data, not ignorance — start there, then investigate."}]}}]}, {"id": "astro", "title": "Astronomy", "icon": "star", "color": "#6C3483", "levels": [{"id": "astro-1", "title": "The solar system", "cards": [{"type": "text", "title": "Eight planets, one star", "body": "Our solar system has one star (the Sun) and eight planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. The four inner ones are small and rocky; the four outer ones are gas and ice giants. Pluto was reclassified as a dwarf planet in 2006."}, {"type": "text", "title": "Order matters", "body": "From the Sun outward: Mercury (scorched), Venus (crushing greenhouse heat), Earth (just right), Mars (cold desert), then the giants — Jupiter (biggest), Saturn (rings), Uranus (tipped sideways), Neptune (windiest). Distance from the Sun sets the thermostat."}, {"type": "tip", "body": "Memorize the order with: 'My Very Educated Mother Just Served Us Nachos' — Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune."}, {"type": "example", "body": "Light from the Sun takes 8 minutes to reach Earth — so you're always seeing the Sun as it was 8 minutes ago. From Neptune, it's over 4 hours. The solar system is so big that 'now' depends on where you stand."}, {"type": "check", "q": "Why is Pluto not a planet?", "choices": ["It hasn't cleared its orbit of other objects", "It's too small to see", "It's made of ice, not rock"], "answer": 0, "explain": "The 2006 definition demands a planet clear its orbital neighborhood. Pluto shares its zone with Kuiper Belt objects, so it's a dwarf planet."}], "flashcards": [{"type": "flash", "front": "How many planets are in our solar system?", "back": "Eight: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune."}, {"type": "flash", "front": "Which planet is biggest?", "back": "Jupiter — more massive than all other planets combined."}, {"type": "flash", "front": "Which planet has the famous rings?", "back": "Saturn (though Jupiter, Uranus, and Neptune have faint rings too)."}, {"type": "flash", "front": "How long does sunlight take to reach Earth?", "back": "About 8 minutes."}], "checkpoint": {"pass": 70, "questions": [{"type": "check", "q": "Put in order from the Sun: Mars, Venus, Mercury", "choices": ["Mercury, Venus, Mars", "Venus, Mercury, Mars", "Mars, Venus, Mercury"], "answer": 0, "explain": "Mercury is closest, then Venus, then Earth, then Mars. The inner rocky lineup never changes."}, {"type": "check", "q": "The four outer planets are mostly...?", "choices": ["Gas and ice", "Rock and metal", "Liquid water"], "answer": 0, "explain": "Jupiter and Saturn are gas giants; Uranus and Neptune are ice giants. The rocky ones are all inner."}, {"type": "check", "q": "Venus is hotter than Mercury because...?", "choices": ["A runaway greenhouse effect traps heat", "It's closer to the Sun", "It spins faster"], "answer": 0, "explain": "Mercury is closer, but Venus's thick CO₂ atmosphere traps heat so completely it's the hottest planet — about 465°C."}, {"type": "check", "q": "What is the Kuiper Belt?", "choices": ["A ring of icy objects beyond Neptune", "Saturn's outer ring", "A galaxy near ours"], "answer": 0, "explain": "It's the donut of dwarf planets and comets past Neptune — Pluto's neighborhood, and the reason Pluto got demoted."}, {"type": "check", "q": "Uranus is unusual because...?", "choices": ["It spins on its side", "It has no moons", "It's the smallest planet"], "answer": 0, "explain": "Uranus rolls around the Sun tilted 98 degrees — likely from an ancient collision. It has 28 known moons, so it's not lonely."}]}}, {"id": "astro-2", "title": "Stars & galaxies", "cards": [{"type": "text", "title": "The Sun is just a star", "body": "Every star you see at night is a sun — some bigger, some smaller than ours. Stars shine because their cores fuse hydrogen into helium, releasing enormous energy. Our Sun is aggressively average: a middle-aged, middle-sized star in a quiet neighborhood."}, {"type": "text", "title": "Galaxies are star cities", "body": "A galaxy is a vast collection of stars, gas, and dust held together by gravity. Ours is the Milky Way — about 100 billion stars in a spiral. The nearest big neighbor, Andromeda, is 2.5 million light-years away and drifting toward us."}, {"type": "tip", "body": "A light-year is a distance, not a time: how far light travels in one year — about 9.5 trillion kilometers. When astronomers say a star is 100 light-years away, they mean its light left 100 years ago."}, {"type": "example", "body": "Look at the Andromeda galaxy tonight (it's visible as a faint smudge). The light hitting your eyes left 2.5 million years ago — before humans existed. Stargazing is time travel."}, {"type": "check", "q": "What makes a star shine?", "choices": ["Nuclear fusion in its core", "Burning gas like a fire", "Reflected sunlight"], "answer": 0, "explain": "Stars fuse hydrogen into helium, converting mass to energy. It's not burning and not reflected — it's nuclear physics, the same process as a hydrogen bomb, sustained for billions of years."}], "flashcards": [{"type": "flash", "front": "What is the Sun?", "back": "A star — a middle-aged, average-sized one."}, {"type": "flash", "front": "What is a galaxy?", "back": "A huge collection of stars, gas, and dust bound by gravity."}, {"type": "flash", "front": "What is a light-year?", "back": "The distance light travels in one year (~9.5 trillion km)."}, {"type": "flash", "front": "Which galaxy do we live in?", "back": "The Milky Way — a spiral with ~100 billion stars."}], "checkpoint": {"pass": 70, "questions": [{"type": "check", "q": "Stars produce energy by...?", "choices": ["Fusing hydrogen into helium", "Burning oxygen", "Splitting atoms apart"], "answer": 0, "explain": "Fusion in the core: hydrogen nuclei merge into helium, and the missing mass becomes light and heat. Fission (splitting) is power plants, not stars."}, {"type": "check", "q": "Andromeda is 2.5 million light-years away. Its light...?", "choices": ["Left 2.5 million years ago", "Arrives instantly", "Left last Tuesday"], "answer": 0, "explain": "Light speed is fast but finite. Every star you see is a message from the past — Andromeda's is just a very old one."}, {"type": "check", "q": "Our galaxy's shape is...?", "choices": ["A spiral", "A perfect sphere", "A straight line"], "answer": 0, "explain": "The Milky Way is a barred spiral — a flat disk with arms winding out from the center. We sit about two-thirds of the way out."}, {"type": "check", "q": "The Sun is best described as...?", "choices": ["An average middle-aged star", "The biggest star known", "A dying red giant"], "answer": 0, "explain": "It's a G-type main-sequence star, about 4.6 billion years old with 5 billion to go. Spectacularly ordinary — which is great for us."}, {"type": "check", "q": "What happens when a massive star dies?", "choices": ["It can collapse into a black hole", "It quietly fades to nothing", "It becomes a planet"], "answer": 0, "explain": "Stars over ~20 solar masses go supernova and their cores can collapse past neutron stars into black holes — gravity winning completely."}]}}, {"id": "astro-3", "title": "Space exploration", "cards": [{"type": "text", "title": "We walked on the Moon in 1969", "body": "On July 20, 1969, Apollo 11 landed Neil Armstrong and Buzz Aldrin on the Moon while Michael Collins orbited above. Armstrong's first step was watched by 600 million people. Twelve humans have walked on the Moon — all American, all between 1969 and 1972."}, {"type": "text", "title": "Robots go where we can't", "body": "No human has been to Mars, but rovers like Perseverance are there now, drilling rocks and flying a helicopter. Voyager 1, launched in 1977, is the farthest human-made object — it crossed into interstellar space carrying a golden record of Earth sounds."}, {"type": "tip", "body": "Remember the firsts: first satellite (Sputnik, 1957), first human in space (Yuri Gagarin, 1961), first Moon landing (Apollo 11, 1969), first space station crew (ISS, 2000 — continuously occupied since)."}, {"type": "example", "body": "The ISS orbits Earth every 90 minutes at 28,000 km/h. Astronauts up there see 16 sunrises a day. It's been continuously occupied since November 2000 — the longest human presence off Earth."}, {"type": "check", "q": "How many people have walked on the Moon?", "choices": ["12", "3", "100+"], "answer": 0, "explain": "Twelve, all from NASA's Apollo program (1969–1972). Nobody has been back since Apollo 17 — though Artemis aims to change that."}], "flashcards": [{"type": "flash", "front": "When did humans first land on the Moon?", "back": "July 20, 1969 — Apollo 11."}, {"type": "flash", "front": "Who was the first human in space?", "back": "Yuri Gagarin, in 1961."}, {"type": "flash", "front": "What was the first artificial satellite?", "back": "Sputnik 1, launched by the USSR in 1957."}, {"type": "flash", "front": "What is the ISS?", "back": "The International Space Station — continuously occupied since 2000."}], "checkpoint": {"pass": 70, "questions": [{"type": "check", "q": "Apollo 11's crew was...?", "choices": ["Armstrong, Aldrin, and Collins", "Armstrong alone", "Armstrong and Gagarin"], "answer": 0, "explain": "Armstrong and Aldrin walked; Collins stayed in the command module orbiting above. Gagarin was Soviet and never went to the Moon."}, {"type": "check", "q": "Voyager 1 is famous because...?", "choices": ["It's the farthest human-made object from Earth", "It landed on Mars", "It carries astronauts"], "answer": 0, "explain": "Launched 1977, it passed the heliopause into interstellar space in 2012. No crew — just instruments and the Golden Record."}, {"type": "check", "q": "The ISS has been continuously occupied since...?", "choices": ["2000", "1969", "1990"], "answer": 0, "explain": "Expedition 1 arrived November 2000. Every day since, at least one human has been in orbit — over two decades straight."}, {"type": "check", "q": "What does Perseverance do on Mars?", "choices": ["Studies rocks and searches for signs of ancient life", "Builds habitats for astronauts", "Mines fuel for return trips"], "answer": 0, "explain": "It's a rolling science lab: drilling core samples, testing oxygen production, and flying the Ingenuity helicopter."}, {"type": "check", "q": "Why haven't humans been to Mars yet?", "choices": ["Distance, radiation, and life-support challenges", "Nobody is interested", "Mars has no gravity"], "answer": 0, "explain": "It's a 7-month trip each way through radiation, with no resupply and a thin unbreathable atmosphere. Mars does have gravity — about 38% of Earth's."}]}}]}, {"id": "bio", "title": "Biology", "icon": "leaf", "color": "#27AE60", "levels": [{"id": "bio-1", "title": "Cells", "cards": [{"type": "text", "title": "The building blocks of life", "body": "Every living thing — you, a mushroom, a redwood tree — is made of cells. Cell theory says three things: all living things are made of cells, the cell is the smallest unit of life, and all cells come from other cells. Nothing living is simpler than a cell."}, {"type": "text", "title": "Tiny factories with departments", "body": "A cell isn't an empty blob; it's packed with organelles, each with a job. The nucleus holds the DNA instructions, mitochondria turn food into energy, and ribosomes build proteins. Think of it as a factory where every department runs on a tight schedule."}, {"type": "tip", "body": "Remember the mitochondria with one line: it's the powerhouse of the cell. Yes, it's a meme — and yes, it's still the easiest way to never forget it."}, {"type": "example", "body": "Muscle cells are stuffed with mitochondria because muscles burn huge amounts of energy. Skin cells barely have any. The cell's equipment matches its job — form follows function, all the way down."}, {"type": "check", "q": "Which organelle holds a cell's DNA instructions?", "choices": ["The nucleus", "The ribosome", "The cell membrane"], "answer": 0, "explain": "The nucleus is the control center — it stores DNA and decides what the cell does. Ribosomes build proteins, and the membrane is just the border."}], "flashcards": [{"type": "flash", "front": "What are the three parts of cell theory?", "back": "All living things are made of cells; the cell is the smallest unit of life; all cells come from pre-existing cells."}, {"type": "flash", "front": "What do mitochondria do?", "back": "Convert food molecules into usable energy (ATP) for the cell."}, {"type": "flash", "front": "What is the job of ribosomes?", "back": "Build proteins by reading genetic instructions."}, {"type": "flash", "front": "What does the cell membrane do?", "back": "Controls what enters and exits the cell — the border checkpoint."}], "checkpoint": {"pass": 70, "questions": [{"q": "You look at pond water under a microscope and see tiny creatures moving. What does cell theory tell you?", "choices": ["They must be plants", "They appeared out of nowhere", "Each creature is made of at least one cell"], "answer": 2, "explain": "Cell theory says all living things are made of cells. Those moving specks are alive, so they're cellular — no exceptions."}, {"q": "A cell needs to release a burst of energy to divide. Which organelle does the heavy lifting?", "choices": ["The cell wall", "The nucleus", "The mitochondria"], "answer": 2, "explain": "Mitochondria convert food into energy. The nucleus stores instructions, and animal cells don't even have cell walls."}, {"q": "Proteins are being built inside a cell. Where is this happening?", "choices": ["Inside the nucleus", "In the mitochondria", "On ribosomes"], "answer": 2, "explain": "Ribosomes read genetic instructions and assemble proteins. The nucleus stores the instructions; the mitochondria supply energy."}, {"q": "Why do muscle cells contain far more mitochondria than skin cells?", "choices": ["Muscles burn much more energy", "Skin cells don't need DNA", "Muscles are larger cells"], "answer": 0, "explain": "A cell's equipment matches its job. Muscles contract constantly and need huge energy output, so they pack extra mitochondria."}, {"q": "A poison blocks everything from passing through cell membranes. What fails first?", "choices": ["Nothing — cells don't need the membrane", "Energy production, then everything", "Only cell division"], "answer": 1, "explain": "The membrane controls what enters and exits. Block it and nutrients stop coming in, waste stops going out, and the cell dies quickly."}]}}, {"id": "bio-2", "title": "Genetics basics", "cards": [{"type": "text", "title": "DNA: the instruction manual", "body": "DNA is a long molecule shaped like a twisted ladder, and it carries the instructions for building and running you. It's organized into genes — each gene is a recipe for one protein, like eye color or blood type."}, {"type": "text", "title": "Chromosomes: the filing system", "body": "Your DNA is packed into 46 chromosomes (23 pairs), one set from each parent. Genes sit at specific spots on chromosomes, which is why siblings share traits but aren't identical — each child gets a shuffled mix."}, {"type": "tip", "body": "Dominant vs recessive: a dominant gene shows up even with one copy (like brown eyes). A recessive gene needs two copies to show (like blue eyes). One dominant beats one recessive, every time."}, {"type": "example", "body": "Two brown-eyed parents can have a blue-eyed child if both carry a hidden recessive blue-eye gene. Each parent passes one copy at random — get blue from both, and the recessive trait appears."}, {"type": "check", "q": "A gene needs two copies to show up in a person. What kind of gene is it?", "choices": ["Mutated", "Recessive", "Dominant"], "answer": 1, "explain": "Recessive genes need two copies to be expressed. One dominant copy would override it."}], "flashcards": [{"type": "flash", "front": "What is a gene?", "back": "A section of DNA that carries instructions for one protein or trait."}, {"type": "flash", "front": "How many chromosomes do humans have?", "back": "46 — 23 pairs, one set inherited from each parent."}, {"type": "flash", "front": "What does dominant mean in genetics?", "back": "A gene that shows its trait even when only one copy is present."}, {"type": "flash", "front": "What is DNA's shape?", "back": "A double helix — a twisted ladder of paired chemical bases."}], "checkpoint": {"pass": 70, "questions": [{"q": "DNA, genes, and chromosomes — how do they relate?", "choices": ["They are three names for the same thing", "Genes are DNA sections; chromosomes are DNA bundles", "Chromosomes are made of protein only"], "answer": 1, "explain": "Genes are stretches of DNA, and chromosomes are tightly packed bundles of DNA. They're nested, not synonyms."}, {"q": "A child inherits one chromosome set from each parent. Why aren't siblings identical?", "choices": ["Each parent passes a randomly shuffled mix", "Siblings share no DNA", "Only the mother contributes genes"], "answer": 0, "explain": "The mix each parent passes is random, so siblings get different combinations — same ingredients, different recipe."}, {"q": "A dominant brown-eye gene (B) and recessive blue-eye gene (b). A person is Bb. What color eyes?", "choices": ["Brown", "Green", "Blue"], "answer": 0, "explain": "One dominant B is enough — it overrides the recessive b. Only bb shows blue."}, {"q": "Two Bb parents have a child. What's the chance the child is bb?", "choices": ["50%", "0%", "25%"], "answer": 2, "explain": "Each parent has a 50% chance of passing b. Both must pass b: 0.5 × 0.5 = 25%."}, {"q": "Where is DNA actually stored inside a cell?", "choices": ["Floating loose in the cytoplasm", "Inside mitochondria only", "In the nucleus, packed into chromosomes"], "answer": 2, "explain": "Nearly all DNA sits in the nucleus, organized into chromosomes. Mitochondria hold a tiny separate scrap."}]}}, {"id": "bio-3", "title": "Ecosystems", "cards": [{"type": "text", "title": "Who eats whom", "body": "An ecosystem is a community of living things plus their environment, linked by who eats whom. Producers (plants) capture sunlight, consumers (animals) eat producers or each other, and decomposers (fungi, bacteria) recycle everything dead back into nutrients."}, {"type": "text", "title": "Energy flows one way", "body": "Energy enters as sunlight and flows up the food chain — but only about 10% transfers at each step. The rest is lost as heat. That's why there are always more plants than herbivores, and more herbivores than top predators."}, {"type": "tip", "body": "Follow the 10% rule to read any ecosystem: a forest can support thousands of rabbits but only a handful of hawks. Each level up needs roughly ten times the level below."}, {"type": "example", "body": "Grass → rabbit → fox: an acre of grass feeds many rabbits, those rabbits feed a few foxes. Remove the grass and everything above collapses — energy can't be created, only passed along."}, {"type": "check", "q": "A fungus breaks down a fallen log into nutrients. What role is it playing?", "choices": ["Decomposer", "Producer", "Consumer"], "answer": 0, "explain": "Decomposers recycle dead matter into nutrients plants can reuse. Without them, ecosystems would drown in dead stuff."}], "flashcards": [{"type": "flash", "front": "What is a producer?", "back": "An organism (usually a plant) that captures energy from sunlight to make food."}, {"type": "flash", "front": "What do decomposers do?", "back": "Break down dead organisms and recycle their nutrients back into the ecosystem."}, {"type": "flash", "front": "What is the 10% rule?", "back": "Only about 10% of energy transfers between food-chain levels; the rest is lost as heat."}, {"type": "flash", "front": "Give an example of a food chain.", "back": "Grass → rabbit → fox: producer → herbivore → carnivore."}], "checkpoint": {"pass": 70, "questions": [{"q": "In a forest, which group is always the largest by mass?", "choices": ["Herbivores", "Producers", "Top predators"], "answer": 1, "explain": "Producers sit at the base and hold the most energy. The 10% rule means each level up is roughly ten times smaller."}, {"q": "All the decomposers in a forest suddenly vanish. What happens?", "choices": ["Plants grow faster", "Nutrients stop recycling and the forest starves", "Nothing changes"], "answer": 1, "explain": "Decomposers return nutrients to the soil. Without them, dead matter piles up and producers run out of raw materials."}, {"q": "A lake's algae (producers) double. What likely happens to the small fish that eat zooplankton?", "choices": ["Their population grows", "They go extinct immediately", "Nothing — fish don't need algae"], "answer": 0, "explain": "More producers support more zooplankton, which support more fish. Energy flows upward, so the base lifts everything."}, {"q": "Why can't an ecosystem support as many wolves as rabbits?", "choices": ["Rabbits reproduce slower", "Wolves are producers", "Wolves need far more rabbits than exist per wolf"], "answer": 2, "explain": "Each wolf needs many rabbits' worth of energy, and only 10% transfers per level. Top predators are always few."}, {"q": "A farmer removes all the wildflowers from a field's edges. Which group suffers first?", "choices": ["Decomposers only", "Top predators directly", "Pollinators, then everything they support"], "answer": 2, "explain": "Flowers feed pollinators; lose the base and the effects ripple upward through the food web."}]}}]}, {"id": "chem", "title": "Chemistry", "icon": "flask", "color": "#E67E22", "levels": [{"id": "chem-1", "title": "Atoms & elements", "cards": [{"type": "text", "title": "Everything is built from atoms", "body": "An atom is the smallest piece of an element that still acts like that element. Every atom has protons and neutrons packed in its center (the nucleus) with electrons zipping around them. Change the number of protons and you change the element itself."}, {"type": "text", "title": "Protons decide identity", "body": "Hydrogen has 1 proton. Helium has 2. Carbon has 6, oxygen has 8, gold has 79. The proton count — called the atomic number — is the element's ID card. Electrons decide how it behaves; neutrons mostly just add weight."}, {"type": "tip", "body": "Remember the big three: protons = identity (who it is), electrons = personality (how it bonds), neutrons = luggage (adds mass, doesn't change the element)."}, {"type": "example", "body": "Water is H₂O: two hydrogen atoms (1 proton each) plus one oxygen atom (8 protons). Same atoms, rearranged, give you hydrogen peroxide — H₂O₂ — which bleaches hair. Arrangement is everything."}, {"type": "check", "q": "What decides which element an atom is?", "choices": ["Its number of protons", "Its number of neutrons", "Its size"], "answer": 0, "explain": "Protons are the ID card. Change the proton count and you literally change the element — that's why it's called the atomic number."}], "flashcards": [{"type": "flash", "front": "What are the three parts of an atom?", "back": "Protons and neutrons in the nucleus, electrons orbiting around them."}, {"type": "flash", "front": "What does the atomic number tell you?", "back": "The number of protons — which decides the element's identity."}, {"type": "flash", "front": "How many protons does carbon have?", "back": "6. That's what makes it carbon and not something else."}, {"type": "flash", "front": "What is H₂O made of?", "back": "Two hydrogen atoms and one oxygen atom."}], "checkpoint": {"pass": 70, "questions": [{"type": "check", "q": "Where are protons and neutrons found?", "choices": ["In the nucleus", "Orbiting the atom", "In the electron cloud"], "answer": 0, "explain": "The nucleus is the dense center. Electrons are the ones flying around outside it."}, {"type": "check", "q": "Hydrogen's atomic number is 1. That means...?", "choices": ["It has 1 proton", "It has 1 neutron", "It weighs 1 gram"], "answer": 0, "explain": "Atomic number = proton count, always. Hydrogen: 1 proton. Helium: 2. It's that direct."}, {"type": "check", "q": "Electrons mainly decide...?", "choices": ["How an atom bonds with others", "The atom's weight", "Which element it is"], "answer": 0, "explain": "Electrons are the socialites — they form the bonds. Protons decide identity; neutrons add mass."}, {"type": "check", "q": "Gold has 79 protons. An atom with 80 protons is...?", "choices": ["A different element (mercury)", "Still gold, but heavier", "Gold with extra charge"], "answer": 0, "explain": "80 protons = mercury, full stop. Proton count is identity; there's no negotiating with it."}, {"type": "check", "q": "What does the ₂ in H₂O mean?", "choices": ["Two hydrogen atoms", "Hydrogen weighs 2 units", "Water has 2 oxygens"], "answer": 0, "explain": "The subscript counts atoms of the element before it: H₂ means two hydrogens, O (no subscript) means one oxygen."}]}}, {"id": "chem-2", "title": "The periodic table", "cards": [{"type": "text", "title": "Elements, organized by personality", "body": "The periodic table lines up every known element by atomic number — but the magic is the columns. Elements in the same column (called groups) behave alike because they have the same number of outer electrons. It's a seating chart where neighbors share habits."}, {"type": "text", "title": "Rows tell a story too", "body": "Each row (called a period) adds a new electron shell. Sodium and magnesium sit side by side in row 3 — close in number, but sodium explodes in water while magnesium just fizzes. Position predicts personality."}, {"type": "tip", "body": "Learn the famous neighborhoods: Group 1 (alkali metals) — violently reactive; Group 17 (halogens) — reactive the other way; Group 18 (noble gases) — refuse to react at all. Three groups cover most of chemistry's drama."}, {"type": "example", "body": "Table salt is NaCl — sodium (a metal that explodes in water) plus chlorine (a poisonous gas). Together? Harmless seasoning. The periodic table predicted they'd pair up: Group 1 loves Group 17."}, {"type": "check", "q": "Why do elements in the same column behave alike?", "choices": ["They have the same number of outer electrons", "They weigh the same", "They were discovered together"], "answer": 0, "explain": "Outer electrons run the bonding show. Same count in the outer shell = same chemical habits, which is why the columns group them."}], "flashcards": [{"type": "flash", "front": "What are the columns of the periodic table called?", "back": "Groups — elements in a group behave alike."}, {"type": "flash", "front": "What are the rows called?", "back": "Periods — each new row adds an electron shell."}, {"type": "flash", "front": "Which group refuses to react?", "back": "Group 18, the noble gases (like helium and neon)."}, {"type": "flash", "front": "What is table salt, chemically?", "back": "NaCl — sodium plus chlorine."}], "checkpoint": {"pass": 70, "questions": [{"type": "check", "q": "Elements are ordered on the table by...?", "choices": ["Atomic number", "Alphabetical name", "Date discovered"], "answer": 0, "explain": "It's strictly by proton count, left to right, top to bottom. Mendeleev's original had gaps where undiscovered elements belonged."}, {"type": "check", "q": "Sodium (Na) and potassium (K) both fizz in water because...?", "choices": ["They're in the same group", "They're in the same row", "They have the same weight"], "answer": 0, "explain": "Both are Group 1 alkali metals with one outer electron to give away — same column, same explosive generosity."}, {"type": "check", "q": "Noble gases don't react because...?", "choices": ["Their outer electron shell is full", "They're too heavy", "They're all gases"], "answer": 0, "explain": "A full outer shell means no reason to bond. Helium, neon, argon — content exactly as they are."}, {"type": "check", "q": "What does the 'Cl' in NaCl stand for?", "choices": ["Chlorine", "Carbon", "Calcium"], "answer": 0, "explain": "Cl is chlorine (Group 17). C is carbon, Ca is calcium — symbols aren't always obvious, which is why the table matters."}, {"type": "check", "q": "Moving left to right across a period, atomic number...?", "choices": ["Increases by one each step", "Stays the same", "Jumps randomly"], "answer": 0, "explain": "Each step right adds exactly one proton. That's the whole ordering principle of the table."}]}}, {"id": "chem-3", "title": "Chemical reactions", "cards": [{"type": "text", "title": "Reactions are atom reshuffles", "body": "In a chemical reaction, atoms break old bonds and form new ones — but no atom is created or destroyed. Burn wood and the carbon doesn't vanish; it joins oxygen and floats off as CO₂. Chemistry is rearrangement, not magic."}, {"type": "text", "title": "Three classic moves", "body": "Synthesis: two things join (hydrogen + oxygen → water). Decomposition: one thing splits (water → hydrogen + oxygen, with electricity). Combustion: something burns in oxygen, releasing heat and light. Most reactions you'll meet are one of these three."}, {"type": "tip", "body": "Follow the energy: reactions that release heat (like burning) are exothermic — 'exo' means out. Reactions that absorb heat (like baking) are endothermic — 'endo' means in. The prefix tells you the direction."}, {"type": "example", "body": "Strike a match: wood + oxygen → CO₂ + water + heat + light. That's combustion — fast, hot, and bright. Your body does the same thing slowly with food: that's why eating keeps you warm."}, {"type": "check", "q": "In a chemical reaction, atoms are...?", "choices": ["Rearranged — none created or destroyed", "Destroyed to release energy", "Created from nothing"], "answer": 0, "explain": "Conservation of mass: every atom you start with is still there at the end, just holding different hands."}], "flashcards": [{"type": "flash", "front": "What happens to atoms in a reaction?", "back": "They're rearranged into new substances — never created or destroyed."}, {"type": "flash", "front": "What is synthesis?", "back": "Two or more substances joining into one (hydrogen + oxygen → water)."}, {"type": "flash", "front": "What is combustion?", "back": "Burning in oxygen — releases heat and light."}, {"type": "flash", "front": "Exothermic vs endothermic?", "back": "Exothermic releases heat (burning); endothermic absorbs it (baking)."}], "checkpoint": {"pass": 70, "questions": [{"type": "check", "q": "Burning wood produces CO₂ and water. The carbon...?", "choices": ["Joined oxygen and floated off as CO₂", "Was destroyed by the fire", "Turned into heat"], "answer": 0, "explain": "Atoms don't vanish — the wood's carbon bonded with oxygen. Heat and light are energy released, not matter destroyed."}, {"type": "check", "q": "Hydrogen + oxygen → water is an example of...?", "choices": ["Synthesis", "Decomposition", "Neutralization"], "answer": 0, "explain": "Two substances joining into one is synthesis. Splitting apart would be decomposition."}, {"type": "check", "q": "Using electricity to split water into hydrogen and oxygen is...?", "choices": ["Decomposition", "Synthesis", "Combustion"], "answer": 0, "explain": "One compound breaking into simpler pieces is decomposition — the reverse of synthesis."}, {"type": "check", "q": "Why does eating keep you warm?", "choices": ["Your body slowly 'burns' food with oxygen", "Food contains tiny heaters", "Digestion creates friction"], "answer": 0, "explain": "Cellular respiration is slow combustion: food + oxygen → CO₂ + water + energy. Same chemistry as fire, just controlled."}, {"type": "check", "q": "An endothermic reaction...?", "choices": ["Absorbs heat from its surroundings", "Releases heat", "Needs no energy at all"], "answer": 0, "explain": "Endo = in. Baking, melting ice, photosynthesis — all pull heat in. Exothermic pushes it out."}]}}]}, {"id": "chess", "title": "Chess", "icon": "crown", "color": "#34495E", "levels": [{"id": "chess-1", "title": "The pieces & how they move", "cards": [{"type": "text", "title": "Six pieces, six personalities", "body": "King: one square any direction — lose him and the game ends. Queen: any distance, any direction — the strongest piece. Rook: straight lines. Bishop: diagonals. Knight: the L-jump. Pawn: forward one (two on its first move), captures diagonally."}, {"type": "text", "title": "The knight is the weirdo — learn it first", "body": "Every other piece slides. The knight jumps in an L: two squares one way, one square sideways. It leaps over pieces, which makes it the only piece that can open a game with a jump. New players lose to knights more than any other piece."}, {"type": "example", "body": "Starting back rank: rook, knight, bishop, queen, king, bishop, knight, rook.\nMemory trick: 'queen loves her color' — the white queen starts on a light square, black queen on a dark one. King goes on the remaining center square."}, {"type": "tip", "body": "Play your first ten games focusing on one rule: never leave a piece where the opponent can take it for free. That single habit beats most beginners."}, {"type": "check", "q": "Which piece can jump over others?", "choices": ["The knight", "The bishop", "The queen"], "answer": 0, "explain": "The knight's L-jump ignores everything in between. Every other piece is blocked by the first thing in its path."}], "flashcards": [{"type": "flash", "front": "Check", "back": "Your king is under attack — you must get out of it on this move."}, {"type": "flash", "front": "Checkmate", "back": "Check with no escape. The game ends immediately."}, {"type": "flash", "front": "The queen", "back": "Moves any distance horizontally, vertically, or diagonally — the most powerful piece."}, {"type": "flash", "front": "En passant (in passing)", "back": "A special pawn capture: if an enemy pawn jumps two squares past yours, you may capture it as if it moved one. It only works on the very next move."}], "checkpoint": {"pass": 70, "questions": [{"q": "How does a bishop move?", "choices": ["Diagonally, any distance", "In an L-shape", "One square only"], "answer": 0, "explain": "Bishops own the diagonals and never leave their starting color. The L-jump belongs to the knight."}, {"q": "A pawn captures…", "choices": ["one square diagonally forward", "straight ahead", "two squares sideways"], "answer": 0, "explain": "Pawns march straight but eat diagonally — the cause of half of all beginner blunders."}, {"q": "What must you do when in check?", "choices": ["Get your king out of attack this move", "Move any piece anywhere", "Resign immediately"], "answer": 0, "explain": "Check forces a response: move the king, block the attack, or capture the attacker. Ignoring it isn't legal."}, {"q": "Where does the white queen start?", "choices": ["On a light square", "On a dark square", "It doesn't matter"], "answer": 0, "explain": "'Queen loves her color': white queen on light, black queen on dark. It's the fastest way to set up correctly."}, {"q": "Which piece is worth the most (after the king, who's priceless)?", "choices": ["Queen", "Rook", "Knight"], "answer": 0, "explain": "Standard values: queen 9, rook 5, bishop/knight 3, pawn 1. The queen's range makes her the heavyweight."}]}}, {"id": "chess-2", "title": "Tactics: fork, pin, skewer", "cards": [{"type": "text", "title": "A fork hits two birds at once", "body": "A fork attacks two enemy pieces at the same time. The knight is the fork artist — from one square it can stab a king and a rook at once, and your opponent can only save one. Look for enemy pieces sitting a knight's jump apart."}, {"type": "text", "title": "A pin freezes a piece in place", "body": "When a piece can't move without exposing something more valuable behind it, it's pinned. A bishop pinning a knight to the queen is the classic: the knight is stuck, and you can pile attackers onto it for free."}, {"type": "example", "body": "The skewer is a pin in reverse: you attack the valuable piece first, and it must run — abandoning the weaker piece behind it. Rooks and bishops skewer down open lines. Remember: pin the weak to freeze it, skewer the strong to rob it."}, {"type": "tip", "body": "Before every move, scan for loose pieces — yours and theirs. A piece with no defenders is a fork or pin waiting to happen. Tactics flow from looseness."}, {"type": "check", "q": "Your knight attacks the enemy king and rook at once. That's a…", "choices": ["fork", "pin", "skewer"], "answer": 0, "explain": "One piece, two targets, opponent saves only one — the textbook fork. The knight is its natural home."}], "flashcards": [{"type": "flash", "front": "Fork", "back": "One piece attacks two enemy pieces simultaneously."}, {"type": "flash", "front": "Pin", "back": "A piece can't move without exposing a more valuable piece behind it."}, {"type": "flash", "front": "Skewer", "back": "Attack the valuable piece so it must move, abandoning the weaker piece behind it."}, {"type": "flash", "front": "Discovered attack", "back": "Moving one piece unveils an attack from another piece hiding behind it."}], "checkpoint": {"pass": 70, "questions": [{"q": "A bishop attacks a knight, and the queen stands behind the knight. The knight is…", "choices": ["pinned", "forked", "checkmated"], "answer": 0, "explain": "The knight can't move without losing the queen — it's pinned to the more valuable piece."}, {"q": "Why is the knight the best forking piece?", "choices": ["Its jump hits squares other pieces can't reach together", "It moves the fastest", "It's worth the most"], "answer": 0, "explain": "The knight's L-jump attacks up to eight squares in a pattern nothing else matches, landing forks from nowhere."}, {"q": "In a skewer, which piece do you attack first?", "choices": ["The more valuable one, so it must flee", "The weaker one", "Both at once"], "answer": 0, "explain": "Attack the king or queen; it has to run, and the piece cowering behind it gets left behind."}, {"q": "What makes a discovered attack scary?", "choices": ["The unveiled attacker was hidden until the last moment", "It always checkmates", "It uses two knights"], "answer": 0, "explain": "Your opponent was watching the moving piece, not the bishop lurking behind it. Surprise is the weapon."}, {"q": "Your opponent's rook sits undefended. Best mindset?", "choices": ["It's loose — look for a tactic against it", "Ignore it, rooks defend themselves", "Trade queens immediately"], "answer": 0, "explain": "Loose pieces are tactical targets. Scan for forks, pins, and skewers against anything undefended."}]}}, {"id": "chess-3", "title": "Opening principles", "cards": [{"type": "text", "title": "Openings have three jobs", "body": "Control the center, develop your pieces, get your king safe. Every good first ten moves does all three. The center (e4, d4, e5, d5) is the high ground — pieces posted there reach everywhere."}, {"type": "text", "title": "Develop with threats", "body": "Don't shuffle the same piece twice while others sleep. Bring knights and bishops out toward the center, castle early (king safety + rook connection in one move), and only then start your plan. Moves that develop and attack at once are golden."}, {"type": "example", "body": "The Italian Game: 1. e4 e5 2. Nf3 Nc6 3. Bc4. White stakes the center, develops two pieces, and eyes f7 — the weakest square near Black's king. Simple, principled, and played at every level for 400 years."}, {"type": "tip", "body": "Learn ideas, not move lists. 'Control the center, develop, castle' will outscore memorizing twenty moves of theory you don't understand."}, {"type": "check", "q": "Why castle early?", "choices": ["King safety plus connecting the rooks", "It wins a pawn", "It attacks the queen"], "answer": 0, "explain": "Castling tucks the king behind pawns and brings a rook toward the center — two opening jobs in a single move."}], "flashcards": [{"type": "flash", "front": "Control the center", "back": "Own e4/d4/e5/d5 — pieces there reach the whole board."}, {"type": "flash", "front": "Development", "back": "Moving pieces from their starting squares into active play."}, {"type": "flash", "front": "Castling", "back": "King slides two squares toward a rook; the rook hops over. Only if neither moved and the path is clear."}, {"type": "flash", "front": "Scholar's mate", "back": "The 4-move trap (Qh5/Qxf7#). It only works if Black ignores development — principled play refutes it."}], "checkpoint": {"pass": 70, "questions": [{"q": "What's the most important opening goal?", "choices": ["Control the center", "Checkmate on move 3", "Trade all the pawns"], "answer": 0, "explain": "Central control gives your pieces maximum reach. Everything else in the opening serves that."}, {"q": "Which square does the Italian Game's bishop eye?", "choices": ["f7 — the weakest square near Black's king", "a1 — its own corner", "h8 — Black's rook"], "answer": 0, "explain": "f7 is defended only by the king at the start, making it the classic early target."}, {"q": "You moved the same knight three times while your bishops sleep. Problem?", "choices": ["Yes — develop new pieces instead", "No — knights love moving", "Only in the endgame"], "answer": 0, "explain": "One developed piece three times is worse than three pieces developed once. Bring the army out."}, {"q": "Best defense against Scholar's mate?", "choices": ["Develop normally — Nc6 blocks it cold", "Push all your pawns", "Move your king out early"], "answer": 0, "explain": "Scholar's mate punishes greed and neglect. Simple developing moves like …Nc6 refute it effortlessly."}, {"q": "After 1. e4 e5, a principled second move is…", "choices": ["2. Nf3 — develops and attacks e5", "2. Qh5 — going for mate", "2. a4 — rook pawn adventure"], "answer": 0, "explain": "Nf3 develops a piece toward the center with a threat on e5. Qh5 is premature; a4 develops nothing."}]}}]}, {"id": "cooking", "title": "Cooking Basics", "icon": "chef", "color": "#FF8C42", "levels": [{"id": "cooking-1", "title": "Knife skills & safety", "cards": [{"type": "text", "title": "A sharp knife is a safe knife", "body": "A dull blade slips, and slips cause cuts. A sharp knife goes exactly where you push it, so you stay in control. If your knife crushes a tomato instead of slicing it, it is time to sharpen."}, {"type": "text", "title": "The claw grip saves fingertips", "body": "Curl your fingertips under like a claw and rest your knuckles against the flat side of the blade. The knife rides along your knuckles, and your fingertips stay tucked safely behind them. It feels weird for a week, then it is automatic."}, {"type": "tip", "body": "Put a damp paper towel under your cutting board. A board that slides is an accident waiting to happen — the towel locks it in place for free."}, {"type": "example", "body": "Dicing an onion, the safe way: cut it in half through the root, peel, and lay each half flat-side down. Make horizontal cuts, then vertical cuts, keeping the root end intact as a handle. Finally slice across. The claw grip guides every cut."}, {"type": "check", "q": "Why is a sharp knife safer than a dull one?", "choices": ["It looks more professional", "Sharp knives are heavier", "It cuts exactly where you push it instead of slipping"], "answer": 2, "explain": "A sharp edge bites into food and tracks straight. A dull edge skates across the surface — and your hand is usually in the way."}], "flashcards": [{"type": "flash", "front": "What is the claw grip?", "back": "Curling your fingertips under and guiding the knife along your knuckles, so the blade never meets your fingertips."}, {"type": "flash", "front": "How do you stop a cutting board sliding?", "back": "Put a damp paper towel or cloth underneath it."}, {"type": "flash", "front": "Honing vs sharpening?", "back": "Honing straightens the blade's edge (do it often); sharpening grinds a new edge (do it rarely)."}, {"type": "flash", "front": "Which knife does most kitchen work?", "back": "The chef's knife — 8 inches of all-rounder for chopping, slicing, and dicing."}], "checkpoint": {"pass": 70, "questions": [{"q": "Your tomato squishes instead of slicing. What is wrong?", "choices": ["You need a bigger board", "The knife is dull", "The tomato is too cold"], "answer": 1, "explain": "A sharp knife slices cleanly. Crushing means the edge is dull — sharpen it, don't press harder."}, {"q": "Where do your fingertips go in the claw grip?", "choices": ["Spread flat on top of the food", "Holding the knife handle", "Curled under, knuckles against the blade"], "answer": 2, "explain": "Fingertips tuck under like a claw; the flat of the blade rides your knuckles. Nothing sharp ever touches a fingertip."}, {"q": "The board keeps sliding on the counter. Fix it?", "choices": ["Hold it with your other hand", "Cut more slowly", "Damp towel underneath"], "answer": 2, "explain": "A damp towel grips both surfaces and locks the board down. Holding it puts your hand next to the blade."}, {"q": "How often should you hone a knife you use daily?", "choices": ["Only when it chips", "Every time you cook, a few strokes", "Once a year"], "answer": 1, "explain": "A few honing strokes before each session keep the edge straight. Sharpening (grinding) is the rare, heavy job."}, {"q": "You are carrying a knife across the kitchen. Safe way?", "choices": ["Toss it in the sink when done", "Blade down, at your side, saying 'behind'", "Blade up so people see it"], "answer": 1, "explain": "Blade points down at your side, and you call out so nobody steps into you. A knife in a sink full of water is a hidden trap."}]}}, {"id": "cooking-2", "title": "Heat & seasoning", "cards": [{"type": "text", "title": "Heat is a dial, not a switch", "body": "High heat sears and browns; medium heat cooks through; low heat simmers gently. Most home mistakes come from the dial being too high — smoking oil and burnt outsides with raw insides."}, {"type": "text", "title": "Salt in layers, not at the end", "body": "Salt each component as you cook it: the pasta water, the vegetables, the protein. Food salted at every stage tastes seasoned all the way through; food salted once at the end tastes salty on the outside and bland inside."}, {"type": "tip", "body": "Taste as you go. Your tongue is the only timer that never lies — a quick taste after each addition tells you exactly what the dish still needs."}, {"type": "example", "body": "Searing chicken thighs: pat them dry (moisture is the enemy of browning), heat the pan until the oil shimmers, lay thighs skin-side down, and do not touch them for 6 minutes. The crust forms while you wait. Flip once, finish in the oven."}, {"type": "check", "q": "When should minced garlic go into a hot pan?", "choices": ["In the last 30-60 seconds of cooking", "First, before anything else", "Only after the dish is plated"], "answer": 0, "explain": "Garlic burns in under a minute over high heat and turns bitter. Add it late, when the pan has cooled slightly or other ingredients cushion it."}], "flashcards": [{"type": "flash", "front": "What does searing do?", "back": "Browning the surface of meat over high heat for flavor and crust — it does not 'seal in juices.'"}, {"type": "flash", "front": "What is carryover cooking?", "back": "Food keeps cooking from residual heat after leaving the pan — pull meat a few degrees before target."}, {"type": "flash", "front": "What is mise en place?", "back": "'Everything in its place' — prepping and measuring all ingredients before the heat goes on."}, {"type": "flash", "front": "Why pat meat dry before searing?", "back": "Surface moisture steams instead of browning. Dry surface = real crust."}], "checkpoint": {"pass": 70, "questions": [{"q": "Your chicken is burnt outside and raw inside. What happened?", "choices": ["Heat was too high", "You used the wrong oil", "The pan was too big"], "answer": 0, "explain": "Blasting heat chars the outside before the inside cooks through. Medium heat gives the center time to catch up."}, {"q": "Why salt the pasta water instead of just the sauce?", "choices": ["It keeps noodles from sticking", "The pasta itself absorbs seasoning as it cooks", "Salt makes water boil faster"], "answer": 1, "explain": "Pasta cooked in bland water stays bland inside no matter how good the sauce is. Salty water seasons every bite."}, {"q": "The pan is smoking before the food goes in. What now?", "choices": ["Add food anyway, fast", "Pour in more oil", "Pull it off the heat and let it cool down"], "answer": 2, "explain": "Smoking oil is past its limit and will taste bitter. Cool the pan, wipe it, and start over at a lower setting."}, {"q": "You added garlic first and now it tastes bitter. Why?", "choices": ["The pan was too small", "Garlic burns in under a minute over high heat", "Garlic needs salt to work"], "answer": 1, "explain": "Minced garlic goes from golden to burnt fast. It belongs in the pan late, not first."}, {"q": "The dish tastes flat but not under-salted. What is missing?", "choices": ["Longer cooking", "Acid — a squeeze of lemon or splash of vinegar", "More oil"], "answer": 1, "explain": "When salt alone does not fix it, acid is usually the answer. A little brightness wakes up every other flavor."}]}}, {"id": "cooking-3", "title": "Building a meal", "cards": [{"type": "text", "title": "Start from the plate, not the recipe", "body": "A complete plate needs three things: a protein (chicken, beans, eggs), a vegetable, and a starch (rice, potatoes, bread). Pick one from each column and you already have dinner — the recipe just fills in details."}, {"type": "text", "title": "Work backwards from serving time", "body": "Decide when you eat, then schedule everything in reverse. Rice takes 20 minutes, chicken 25, salad 5 — so rice goes on first, chicken next, salad last. The meal lands hot all at once instead of in sad, cold waves."}, {"type": "tip", "body": "Rest meat 5-10 minutes after cooking. Juices that were driven to the center settle back through the meat. Cut too early and they flood the board instead of staying in your dinner."}, {"type": "example", "body": "A 25-minute chicken dinner: 0:00 — oven on, rice in the pot. 0:05 — chicken thighs in the oven. 0:20 — chop a quick salad while everything finishes. 0:25 — rest the chicken 5 minutes, plate it all together. One timeline, zero panic."}, {"type": "check", "q": "Why let meat rest after cooking?", "choices": ["Juices redistribute instead of spilling out", "It cools to a safe temperature", "Resting adds more flavor"], "answer": 0, "explain": "Heat drives juices to the center. Resting lets them settle back through the meat — slice early and they pour onto the board."}], "flashcards": [{"type": "flash", "front": "What three things make a complete plate?", "back": "A protein, a vegetable, and a starch."}, {"type": "flash", "front": "Why rest meat after cooking?", "back": "So the juices redistribute through the meat instead of flooding the cutting board."}, {"type": "flash", "front": "How do you time a multi-part meal?", "back": "Work backwards from serving time, starting the longest-cooking item first."}, {"type": "flash", "front": "Salt, acid, fat, heat — what are these?", "back": "The four levers for balancing flavor. If a dish is dull, one of them is missing."}], "checkpoint": {"pass": 70, "questions": [{"q": "You have chicken, broccoli, and rice. What is missing for a complete plate?", "choices": ["Nothing — protein, vegetable, starch", "A sauce", "Dessert"], "answer": 0, "explain": "Chicken is the protein, broccoli the vegetable, rice the starch. That is a full plate already."}, {"q": "Rice takes 20 min, fish takes 10, salad takes 5. Dinner at 7:00. When does the rice start?", "choices": ["6:50", "6:55", "6:40"], "answer": 2, "explain": "Longest item first: rice at 6:40, fish at 6:50, salad at 6:55 — everything lands at 7:00."}, {"q": "You slice the steak immediately and juice floods the board. Lesson?", "choices": ["Cook it longer next time", "Use a bigger board", "Rest meat 5-10 minutes before cutting"], "answer": 2, "explain": "The juices needed time to settle back in. Patience keeps them in the meat where they belong."}, {"q": "The soup tastes rich but dull. Salt did not fix it. Next move?", "choices": ["Add acid — lemon juice or vinegar", "Add more salt", "Cook it another hour"], "answer": 0, "explain": "Salt, acid, fat, heat: when a rich dish tastes flat, brightness from acid is almost always the missing lever."}, {"q": "Why chop everything before turning on the heat?", "choices": ["Once cooking starts there is no time to prep", "Vegetables cook faster chopped", "It looks professional"], "answer": 0, "explain": "That is mise en place. Stir-fry waits for no one — if you are still chopping, the garlic is already burning."}]}}]}, {"id": "econ", "title": "Economics", "icon": "chart", "color": "#D4AC0D", "levels": [{"id": "econ-1", "title": "Supply & demand", "cards": [{"type": "text", "title": "The price seesaw", "body": "Supply is how much sellers want to sell; demand is how much buyers want to buy. When demand rises and supply stays put, prices climb. When supply floods in and demand stays flat, prices fall. Almost every price you see is this seesaw finding its balance."}, {"type": "text", "title": "Equilibrium: where they meet", "body": "The equilibrium price is where the amount sellers want to sell exactly matches what buyers want to buy. Below it, shortages — shelves empty. Above it, surpluses — goods pile up. Markets are constantly nudging toward this point, even if they rarely sit still on it."}, {"type": "example", "body": "A heatwave hits and everyone wants ice cream (demand jumps). Shops sell out at the old price, so they raise it. Higher prices tempt more suppliers to stock ice cream, and some buyers drop out — until supply and demand meet again, at a higher price than before."}, {"type": "tip", "body": "When you see a price change, ask: did supply move, or did demand move? New iPhone launch with the same factories — demand moved. A drought hits coffee farms — supply moved. One question, and most price mysteries solve themselves."}, {"type": "check", "q": "A drought destroys half the coffee crop. What happens to coffee prices?", "choices": ["They rise — less supply at the same demand", "They fall — sellers panic", "Nothing — prices are fixed"], "answer": 0, "explain": "Supply fell while demand stayed the same, so buyers compete for less coffee and bid the price up. Classic supply shift."}], "flashcards": [{"type": "flash", "front": "What is supply? What is demand?", "back": "Supply: how much sellers want to sell. Demand: how much buyers want to buy."}, {"type": "flash", "front": "What is the equilibrium price?", "back": "The price where quantity supplied equals quantity demanded."}, {"type": "flash", "front": "What happens below the equilibrium price?", "back": "A shortage — buyers want more than sellers offer, so shelves empty."}, {"type": "flash", "front": "Demand for ice cream spikes in a heatwave. What happens to price?", "back": "It rises until higher supply and lower demand meet the new balance."}], "checkpoint": {"pass": 70, "questions": [{"q": "If supply increases while demand stays the same, prices tend to:", "choices": ["Fall", "Rise", "Stay exactly the same"], "answer": 0, "explain": "More supply chasing the same demand means sellers compete by cutting prices — a surplus pushes prices down."}, {"q": "A shortage means:", "choices": ["Quantity demanded exceeds quantity supplied", "Nobody wants the product", "Prices are too high"], "answer": 0, "explain": "Shortage = buyers want more than sellers provide at that price. It usually means the price is below equilibrium."}, {"q": "Concert tickets sell out in minutes and resell for triple. The original price was:", "choices": ["Below equilibrium", "Above equilibrium", "Exactly at equilibrium"], "answer": 0, "explain": "Instant sellouts plus a thriving resale market scream shortage — the face price was set below what the market would bear."}, {"q": "A new factory doubles the supply of sneakers. In the short run:", "choices": ["Prices fall as sellers compete", "Prices rise from excitement", "Demand doubles too"], "answer": 0, "explain": "Supply shifted right with demand unchanged — the new equilibrium sits at a lower price and higher quantity."}, {"q": "Why do economists say 'there's no such thing as a free lunch'?", "choices": ["Every choice has an opportunity cost", "Lunch is always overpriced", "Restaurants never give discounts"], "answer": 0, "explain": "Resources are scarce, so getting something means giving up the next-best alternative. That forgone value is the opportunity cost."}]}}, {"id": "econ-2", "title": "Inflation & interest", "cards": [{"type": "text", "title": "Inflation: money gets thinner", "body": "Inflation is a general rise in prices over time — your dollar buys a little less each year. A 3% inflation rate means something costing $100 today costs about $103 next year. A little inflation is normal; a lot of it quietly taxes everyone's savings."}, {"type": "text", "title": "Interest: the price of money", "body": "Interest is what you pay to borrow money — or what you're paid to lend it. When central banks raise interest rates, borrowing gets expensive: mortgages, car loans, and credit cards all cost more, which cools spending and slows inflation. Lower rates do the opposite."}, {"type": "example", "body": "You stash $1,000 under your mattress for 10 years at 3% annual inflation. When you dig it up, it buys what about $744 bought back then — you lost a quarter of your purchasing power doing nothing. Money sitting still is money shrinking."}, {"type": "tip", "body": "Always compare interest rates to inflation. A savings account paying 1% while inflation runs 3% means your money is shrinking 2% a year in real terms. The real return is what matters: nominal rate minus inflation."}, {"type": "check", "q": "Inflation is 4% and your savings pay 2%. What happens to your purchasing power?", "choices": ["It shrinks about 2% per year", "It grows 2% per year", "Nothing — the money is safe"], "answer": 0, "explain": "Real return = nominal minus inflation: 2% − 4% = −2%. Your balance grows in dollars but buys less each year."}], "flashcards": [{"type": "flash", "front": "What is inflation?", "back": "A general rise in prices over time, so each dollar buys less."}, {"type": "flash", "front": "What does raising interest rates do?", "back": "Makes borrowing expensive, cools spending, and slows inflation."}, {"type": "flash", "front": "How do you find the real return on savings?", "back": "Nominal interest rate minus the inflation rate."}, {"type": "flash", "front": "$1,000 sits for 10 years at 3% inflation. What happens?", "back": "It loses about a quarter of its purchasing power — buys what ~$744 bought before."}], "checkpoint": {"pass": 70, "questions": [{"q": "If inflation is 5%, a $100 grocery basket next year costs about:", "choices": ["$105", "$95", "$100"], "answer": 0, "explain": "5% of $100 is $5, so the same basket costs roughly $105. That's inflation eating your dollar."}, {"q": "Why do central banks raise rates to fight inflation?", "choices": ["Expensive borrowing slows spending, cooling price rises", "High rates print more money", "It makes imports cheaper instantly"], "answer": 0, "explain": "Higher rates make loans and credit costly, so people and businesses spend less. Less spending pressure = slower price growth."}, {"q": "Your bond pays 6% and inflation is 2%. Your real return is:", "choices": ["About 4%", "6%", "8%"], "answer": 0, "explain": "Real return ≈ nominal − inflation = 6% − 2% = 4%. That's the actual gain in purchasing power."}, {"q": "Deflation (falling prices) sounds nice. Why do economists fear it?", "choices": ["People delay buying, which can stall the whole economy", "It makes savings worthless", "It only affects luxury goods"], "answer": 0, "explain": "If prices will be lower tomorrow, everyone waits — spending collapses, businesses cut jobs, and the spiral feeds itself."}, {"q": "Who is hurt most by unexpected high inflation?", "choices": ["Lenders and people holding cash savings", "Borrowers with fixed-rate debt", "Owners of real estate"], "answer": 0, "explain": "Inflation shrinks what money is worth, so cash-holders and fixed-rate lenders lose. Borrowers actually benefit — they repay with cheaper dollars."}]}}, {"id": "econ-3", "title": "Markets", "cards": [{"type": "text", "title": "Stocks are slices of companies", "body": "A stock is a tiny ownership slice of a company. Buy a share and you own a fraction of its future profits — which is why prices rise when the company does well and fall when it stumbles. You're not betting on a number; you're buying a piece of a business."}, {"type": "text", "title": "Risk and return hold hands", "body": "In markets, higher potential returns always come with higher risk — there are no exceptions, only sales pitches. A savings account is safe and pays little; a startup stock might 10x or go to zero. Anyone promising high returns with no risk is selling you something."}, {"type": "example", "body": "You buy 10 shares at $50 each ($500 total). The company thrives and shares hit $70 — your stake is now $700. But if bad news drops them to $30, you hold $300. Same shares, different story. The price is just what the crowd currently believes."}, {"type": "tip", "body": "Diversification is the only free lunch in investing: spreading money across many assets means one failure can't sink you. Index funds do this automatically — one purchase buys tiny slices of hundreds of companies."}, {"type": "check", "q": "What does owning a stock actually mean?", "choices": ["You own a small slice of the company", "You've lent the company money", "You work for the company"], "answer": 0, "explain": "Stock = equity = ownership. Lending the company money is a bond; working there is a job. Shareholders own a piece and share the profits (and losses)."}], "flashcards": [{"type": "flash", "front": "What is a stock?", "back": "A small ownership slice of a company — a claim on a fraction of its profits."}, {"type": "flash", "front": "What is the risk-return tradeoff?", "back": "Higher potential returns always come with higher risk. No exceptions."}, {"type": "flash", "front": "What is diversification?", "back": "Spreading money across many assets so one failure can't sink you."}, {"type": "flash", "front": "What does an index fund buy you?", "back": "Tiny slices of hundreds of companies in one purchase — instant diversification."}], "checkpoint": {"pass": 70, "questions": [{"q": "A company's profits double but its share price falls. Why might that happen?", "choices": ["Investors expected even better results", "Profits don't affect prices", "The shares multiplied"], "answer": 0, "explain": "Prices reflect expectations, not just results. Great news that falls short of great expectations still disappoints the crowd."}, {"q": "'Guaranteed 20% returns with zero risk' is:", "choices": ["A scam or a lie — risk and return always pair up", "A rare but real opportunity", "How savings accounts work"], "answer": 0, "explain": "The risk-return tradeoff has no exceptions. High promised returns with 'no risk' is the oldest pitch in fraud."}, {"q": "Why do index funds beat most professional stock-pickers over time?", "choices": ["Tiny fees plus diversification across the whole market", "They use secret algorithms", "They only buy tech stocks"], "answer": 0, "explain": "Most active managers can't beat the market after fees. Index funds win by charging almost nothing and owning everything."}, {"q": "What's the difference between a stock and a bond?", "choices": ["Stock is ownership; a bond is a loan to the company", "They're the same thing", "Bonds are riskier than stocks"], "answer": 0, "explain": "Buy a stock, you own a slice. Buy a bond, the company owes you money plus interest. Bonds are generally steadier — and capped."}, {"q": "The market drops 20% in a month. The disciplined long-term move is:", "choices": ["Stick to the plan — panic selling locks in losses", "Sell everything immediately", "Borrow money to buy more"], "answer": 0, "explain": "Market drops are the price of long-term returns. Selling in a panic turns a temporary dip into a permanent loss."}]}}]}, {"id": "finance", "title": "Personal Finance", "icon": "coin", "color": "#2ECC71", "levels": [{"id": "finance-1", "title": "Budgeting", "cards": [{"type": "text", "title": "A budget is a plan, not a punishment", "body": "A budget just means deciding where your money goes before it disappears. Every dollar gets a job: spend, save, or invest. Dollars with no job vanish on impulse buys."}, {"type": "text", "title": "The 50/30/20 rule", "body": "Split take-home pay into 50% needs (rent, groceries, transport), 30% wants (eating out, hobbies), and 20% savings plus debt payoff. It's a starting template, not a law — adjust the dials to your life."}, {"type": "example", "body": "Maya takes home $2,400 a month. Needs: $1,200 (rent $900, groceries $200, bus pass $100). Wants: $720. Future: $480 straight to savings. Every dollar has an address."}, {"type": "tip", "body": "Track every dollar for 30 days before judging yourself. Most people find 10–15% leaking to forgotten subscriptions and snacks. You can't fix what you can't see."}, {"type": "check", "q": "You take home $3,000/month. Under 50/30/20, how much goes to savings?", "choices": ["$600", "$900", "$1,500"], "answer": 0, "explain": "20% of $3,000 = $600. That's the pay-yourself-first slice — needs get $1,500, wants get $900."}], "flashcards": [{"type": "flash", "front": "What is the 50/30/20 rule?", "back": "50% needs, 30% wants, 20% savings and debt payoff — a starter template for splitting take-home pay."}, {"type": "flash", "front": "Need vs. want?", "back": "Needs keep life running: rent, food, transport. Wants make it fun: dining out, games. The line moves per person — be honest with yourself."}, {"type": "flash", "front": "What does 'pay yourself first' mean?", "back": "Move savings out the moment you're paid, before spending. What you don't see, you won't miss."}, {"type": "flash", "front": "Why track spending for 30 days?", "back": "To find the leaks — forgotten subscriptions and impulse buys most people underestimate by 10–15%."}], "checkpoint": {"pass": 70, "questions": [{"q": "Needs now eat 60% of your pay after a rent hike. What do you do?", "choices": ["Trim wants and rebalance", "Put rent on a credit card", "Stop saving forever"], "answer": 0, "explain": "Ratios are guides, not cages. When needs swell, shrink wants first and protect at least some savings."}, {"q": "Which of these is a need?", "choices": ["Bus pass to get to work", "Concert tickets", "New sneakers when the old ones are fine"], "answer": 0, "explain": "If skipping it breaks your ability to live or work, it's a need. Everything else is a want — even fun, legitimate ones."}, {"q": "You find $200/month in forgotten subscriptions. Best move?", "choices": ["Cancel them and redirect it to savings", "Find new subscriptions to replace them", "Ignore it — it's only $200"], "answer": 0, "explain": "$200 a month is $2,400 a year. Redirecting found money to savings is the highest-return 'raise' you'll ever give yourself."}, {"q": "Budgets most often fail because…", "choices": ["They're unrealistic and abandoned by week two", "Math is too hard", "Banks forbid budgets"], "answer": 0, "explain": "Brutal, joyless budgets die fast. Build in guilt-free fun money and the plan survives."}, {"q": "Take-home $1,800. Under 50/30/20, wants = ?", "choices": ["$540", "$360", "$900"], "answer": 0, "explain": "30% of $1,800 = $540. Needs get $900, savings gets $360."}]}}, {"id": "finance-2", "title": "Saving & debt", "cards": [{"type": "text", "title": "Pay yourself first, automatically", "body": "Willpower is unreliable; automation isn't. Set a transfer that moves money to savings the day you're paid. You adapt to what's left, and saving happens whether you feel like it or not."}, {"type": "text", "title": "Kill high-interest debt first", "body": "Credit card debt at 20%+ grows faster than any safe investment earns. The avalanche method: pay minimums everywhere, then throw every extra dollar at the highest-rate balance first."}, {"type": "example", "body": "$3,000 on a card at 22% with $60 minimum payments takes 7+ years and costs about $2,800 in interest. Paying $200/month clears it in 18 months for about $550 in interest. Same debt, $2,250 difference — from the payment size alone."}, {"type": "tip", "body": "Build a $500–$1,000 mini emergency fund before attacking debt aggressively. Without it, every car repair lands right back on the card and you're running in circles."}, {"type": "check", "q": "Two debts: $800 at 24% and $2,000 at 8%. Avalanche says attack which first?", "choices": ["The $800 at 24%", "The $2,000 at 8%", "Both equally"], "answer": 0, "explain": "Avalanche targets the highest rate first — 24% costs far more per dollar than 8%, regardless of balance size."}], "flashcards": [{"type": "flash", "front": "What is the avalanche method?", "back": "Pay minimums on all debts, send every extra dollar to the highest-interest balance first. The mathematically cheapest way out."}, {"type": "flash", "front": "Why automate savings?", "back": "Willpower fades; automatic transfers happen regardless. You spend what's left instead of saving what's left."}, {"type": "flash", "front": "What is an emergency fund for?", "back": "Surprise expenses — repairs, job loss — so they don't land on high-interest credit cards."}, {"type": "flash", "front": "Why are minimum payments a trap?", "back": "They're calibrated to stretch repayment for years, maximizing the interest you pay."}], "checkpoint": {"pass": 70, "questions": [{"q": "$500 extra this month. Card A: $1,200 at 21%. Card B: $900 at 12%. Avalanche says?", "choices": ["Extra $500 to Card A", "Split it evenly", "Extra $500 to Card B"], "answer": 0, "explain": "Highest rate first, always, under avalanche. Card A's 21% bleeds faster per dollar than Card B's 12%."}, {"q": "What's a reasonable starter emergency fund?", "choices": ["$500–$1,000", "$50,000", "$0 — the credit card IS the fund"], "answer": 0, "explain": "A small buffer breaks the borrow-for-emergencies cycle. Grow it to 3–6 months of expenses later."}, {"q": "Savings earn 4%, your card charges 22%. Extra $1,000 goes…", "choices": ["Toward the card debt", "Into savings", "Under the mattress"], "answer": 0, "explain": "A 22% guaranteed 'return' from killing debt crushes 4% savings interest. Pay the expensive debt first."}, {"q": "What happens if you only ever pay minimums?", "choices": ["You pay far more interest over far more years", "The debt vanishes at the same speed", "Your credit score instantly maxes out"], "answer": 0, "explain": "Minimums are calibrated to keep you paying mostly interest. Bigger payments attack principal."}, {"q": "Best day for the automatic savings transfer?", "choices": ["Payday — before you can spend it", "End of month, if anything's left", "Never — do it manually when inspired"], "answer": 0, "explain": "Pay yourself first means first. End-of-month leftovers are a myth, and inspiration is unreliable."}]}}, {"id": "finance-3", "title": "Investing basics", "cards": [{"type": "text", "title": "Compound interest is a snowball", "body": "Returns earn returns. $200 a month at roughly 7% average annual growth means $24,000 contributed over 10 years becomes about $34,000 in value — the extra $10,000 is growth earning its own growth."}, {"type": "text", "title": "Stocks vs. bonds in one breath", "body": "Stocks are tiny ownership slices of companies — higher growth, bumpier ride. Bonds are IOUs that pay steady interest — calmer, slower. Young investors usually lean toward stocks; the mix gets calmer with age."}, {"type": "example", "body": "Two friends invest $5,000 once at 7% average. Ana starts at 25, Ben at 35. At 65: Ana has about $74,000, Ben about $38,000. Same money, same return — ten extra years nearly doubled the outcome. Time is the real asset."}, {"type": "tip", "body": "Index funds bundle hundreds of stocks into one cheap package — instant diversification without picking winners. Low fees matter more than clever picks: a 1% fee can eat a third of your returns over decades."}, {"type": "check", "q": "Why do low fees matter so much?", "choices": ["They compound against you for decades", "They're illegal", "They only apply to rich investors"], "answer": 0, "explain": "A 1% annual fee sounds small, but over 30+ years it can devour roughly a third of your total gains. Fees compound too — against you."}], "flashcards": [{"type": "flash", "front": "What is compound interest?", "back": "Earning returns on your returns — growth that snowballs because each year's gains start earning too."}, {"type": "flash", "front": "What is an index fund?", "back": "One fund holding hundreds of stocks: instant diversification at very low fees."}, {"type": "flash", "front": "Stocks vs. bonds?", "back": "Stocks = company ownership, higher growth, more volatility. Bonds = loans paying steady interest, calmer and slower."}, {"type": "flash", "front": "Why start investing early?", "back": "Time amplifies compounding. Small amounts invested young can outgrow larger amounts started late."}], "checkpoint": {"pass": 70, "questions": [{"q": "What does diversification protect you from?", "choices": ["One bad company tanking everything", "All market risk disappearing", "Paying any taxes"], "answer": 0, "explain": "Spreading across many holdings means one flop can't sink you. It can't remove market-wide risk — just single-company risk."}, {"q": "$1,000 at 10% for a year, then the $1,100 compounds another year at 10%. Total?", "choices": ["$1,210", "$1,200", "$1,100"], "answer": 0, "explain": "Year 1: $1,100. Year 2: 10% of $1,100 = $110, total $1,210. That extra $10 is interest earning interest."}, {"q": "Which typically has the highest long-term returns?", "choices": ["Stocks", "Savings accounts", "Cash under the mattress"], "answer": 0, "explain": "Stocks have historically returned around 7–10% annually over long periods — with plenty of scary dips along the way."}, {"q": "A fund charges 1.5% yearly vs. a similar one at 0.1%. Over 30 years…", "choices": ["The expensive one can cost roughly a third of your gains", "The difference is negligible", "The expensive one must perform better"], "answer": 0, "explain": "Fees compound relentlessly. Higher fees don't buy higher returns — they just guarantee a bigger cut for the fund."}, {"q": "Best first investing move for a beginner?", "choices": ["A low-fee diversified index fund, held long-term", "Betting everything on one hot stock tip", "Timing the market perfectly"], "answer": 0, "explain": "Boring wins: diversify cheaply, keep buying, don't panic-sell. Stock tips and market timing are how beginners donate money."}]}}]}, {"id": "firstaid", "title": "First Aid", "icon": "cross", "color": "#C0392B", "levels": [{"id": "firstaid-1", "title": "CPR basics", "cards": [{"type": "text", "title": "When CPR matters", "body": "CPR is for someone in cardiac arrest: collapsed, unresponsive, and not breathing normally. Gasping or agonal breaths don't count as breathing. If they're awake and talking, they don't need CPR."}, {"type": "text", "title": "Call first, then act", "body": "Before touching the chest, shout for help and call 911 (or your local emergency number). Send someone to fetch an AED, the portable defibrillator found in malls, gyms, and airports. An AED talks you through every step."}, {"type": "tip", "body": "This pack builds awareness, not certification. It supplements real training — it never replaces it. Take a certified first aid/CPR course from the Red Cross or Heart & Stroke when you can. Skills fade; refreshers matter."}, {"type": "text", "title": "Hands, depth, rhythm", "body": "Place the heel of one hand on the center of the chest, other hand on top, fingers interlaced. Push hard and fast: 5 to 6 cm deep (about 2 inches), at 100 to 120 compressions per minute. Let the chest fully recoil between pushes."}, {"type": "example", "body": "The Bee Gees trick: hum 'Stayin' Alive' in your head while you push. Its beat sits around 103 per minute — right in the target zone. Compressions to that rhythm keep your pace steady when adrenaline is screaming at you to go faster."}, {"type": "check", "q": "Where do your hands go for adult CPR?", "choices": ["Center of the chest", "Over the stomach", "On the left side of the ribs"], "answer": 0, "explain": "Compressions work by squeezing the heart between the breastbone and spine, so the heel of your hand belongs on the center of the chest. The stomach and side ribs don't move blood."}], "flashcards": [{"type": "flash", "front": "What rate for chest compressions?", "back": "100 to 120 per minute — 'Stayin' Alive' tempo."}, {"type": "flash", "front": "How deep for adult compressions?", "back": "5 to 6 cm (about 2 inches), letting the chest fully recoil."}, {"type": "flash", "front": "What do you do before starting CPR?", "back": "Call 911 and send someone for an AED."}, {"type": "flash", "front": "What is an AED?", "back": "An automated external defibrillator — a portable device that analyzes the heart rhythm and talks you through delivering a shock if needed."}], "checkpoint": {"pass": 70, "questions": [{"q": "Someone collapses and isn't breathing normally. What's your first move?", "choices": ["Call 911 and get an AED", "Start compressions immediately", "Check their wallet for ID"], "answer": 0, "explain": "Calling for help and an AED comes first — you need backup and the defibrillator on the way before you start compressions."}, {"q": "How deep should adult chest compressions be?", "choices": ["5 to 6 cm", "1 to 2 cm", "As deep as you possibly can"], "answer": 0, "explain": "5 to 6 cm moves blood effectively. Shallower compressions don't circulate; deeper risks injury without added benefit."}, {"q": "What compression rate should you aim for?", "choices": ["100 to 120 per minute", "60 per minute", "As fast as humanly possible"], "answer": 0, "explain": "100-120 per minute is the evidence-based range. Slower doesn't circulate blood; uncontrolled speed sacrifices depth and recoil."}, {"q": "Between compressions, the chest must...", "choices": ["Fully recoil", "Stay pressed down", "Be checked for a pulse"], "answer": 0, "explain": "Full recoil lets the heart refill with blood. Leaning on the chest between pushes chokes off circulation."}, {"q": "The AED arrives. What do you do?", "choices": ["Turn it on and follow its voice prompts", "Wait for paramedics to use it", "Keep doing CPR and ignore it"], "answer": 0, "explain": "AEDs are designed for untrained bystanders — power it on and it literally talks you through pad placement and shocks."}]}}, {"id": "firstaid-2", "title": "Wounds & bleeding", "cards": [{"type": "text", "title": "Pressure stops most bleeding", "body": "For a bleeding wound, press down firmly with a clean cloth or bandage and don't lift it to peek — peeking breaks the clot that's forming. Hold steady pressure for several minutes. Most everyday bleeding stops this way."}, {"type": "text", "title": "What NOT to do", "body": "Don't remove an embedded object (a knife, glass shard) — it may be plugging the wound. Don't apply a tourniquet for minor cuts. Don't pour alcohol or peroxide into the wound; it damages tissue. Clean around it, not inside it."}, {"type": "tip", "body": "Barrier first: if you have gloves, put them on. No gloves? A plastic bag over your hand works. Protecting yourself from someone else's blood is part of good first aid, not selfishness."}, {"type": "example", "body": "Kitchen knife slips and your finger is bleeding steadily. Grab a clean towel, fold it into a pad, press it hard over the cut, and keep pressing. Elevate the hand above heart level while you hold. After 10 minutes of steady pressure, ease off and check — if it's still flowing, keep pressure and get medical help."}, {"type": "text", "title": "When to get help", "body": "Call emergency services or head to urgent care for: bleeding that won't stop after 10 minutes of pressure, deep or gaping cuts, wounds on the face, or any cut from a rusty/dirty object if tetanus shots aren't current."}, {"type": "check", "q": "A wound is bleeding. What's the first thing you do?", "choices": ["Press firmly with a clean cloth", "Rinse it under hot water", "Wrap it loosely and wait"], "answer": 0, "explain": "Direct, firm pressure is the first and most effective step. Rinsing a actively bleeding wound washes away forming clots; loose wrapping does nothing."}], "flashcards": [{"type": "flash", "front": "What's the first step for a bleeding wound?", "back": "Firm, direct pressure with a clean cloth — and don't peek."}, {"type": "flash", "front": "An object is stuck in the wound. Remove it?", "back": "No — leave it in place. It may be plugging the bleed. Stabilize it and get help."}, {"type": "flash", "front": "How long before seeking help for unstoppable bleeding?", "back": "If it won't stop after about 10 minutes of steady pressure, get medical help."}, {"type": "flash", "front": "Should you pour alcohol into a wound?", "back": "No — it damages tissue. Clean around the wound, not inside it."}], "checkpoint": {"pass": 70, "questions": [{"q": "Why shouldn't you lift the cloth to check the wound?", "choices": ["It breaks the clot that's forming", "It lets air infect the blood", "It makes the person panic"], "answer": 0, "explain": "Clotting takes uninterrupted minutes. Every peek restarts the clock."}, {"q": "A piece of glass is embedded in someone's arm. You should...", "choices": ["Leave it and stabilize the area", "Pull it out quickly", "Push it deeper to stop bleeding"], "answer": 1, "explain": "Removing it can release the plug it formed and cause worse bleeding. Stabilize and let professionals handle it."}, {"q": "Which wounds need professional care?", "choices": ["Bleeding that won't stop after 10 minutes of pressure", "A small paper cut", "A scraped knee that stopped bleeding"], "answer": 0, "explain": "Persistent bleeding, deep/gaping cuts, and face wounds need medical attention. Minor scrapes just need cleaning and a bandage."}, {"q": "Elevating a bleeding limb helps because...", "choices": ["It slows blood flow to the area", "It numbs the pain", "It keeps the person calm"], "answer": 0, "explain": "Raising the wound above heart level reduces blood pressure at the site, helping clots form."}, {"q": "No gloves available and someone's bleeding. You can...", "choices": ["Use a plastic bag as a barrier", "Work bare-handed without worry", "Wait for someone else"], "answer": 0, "explain": "Any clean barrier between you and blood is better than none. Bloodborne safety applies to everyone."}]}}, {"id": "firstaid-3", "title": "Choking & burns", "cards": [{"type": "text", "title": "Spotting choking", "body": "Real choking is silent. The universal sign is hands clutching the throat. If they can't speak, cough, or breathe, act fast. If they're coughing forcefully, encourage it — a strong cough is the body's own fix, don't interfere."}, {"type": "text", "title": "Abdominal thrusts", "body": "Stand behind them, wrap your arms around the waist, make a fist just above the navel, grab it with your other hand, and pull sharply inward and upward. Repeat until the object pops out or they go limp — then start CPR and call 911."}, {"type": "text", "title": "Burns: cool, don't smear", "body": "For a burn, cool it under cool running water for at least 10 minutes, as soon as possible. Don't use ice, butter, toothpaste, or oils — they trap heat or introduce infection. Remove jewelry near the burn before swelling starts."}, {"type": "tip", "body": "Call 911 for burns that: cover a large area, are on the face/hands/feet/joints, look white or charred, or were caused by chemicals or electricity. When in doubt, call — dispatchers would rather hear from you."}, {"type": "example", "body": "Someone grabs a hot pan handle. Get the hand under cool (not ice-cold) tap water immediately and keep it there a full 10 minutes — set a timer, because 10 minutes feels endless. Then loosely cover with cling film or a clean non-fluffy cloth. If blisters form, don't pop them; they're nature's bandage."}, {"type": "check", "q": "Someone is choking silently and can't breathe. You should...", "choices": ["Give abdominal thrusts", "Offer them water", "Tell them to lie down"], "answer": 0, "explain": "Silent choking with no air movement needs abdominal thrusts immediately. Water can't pass a blocked airway, and lying down doesn't help."}], "flashcards": [{"type": "flash", "front": "What's the universal sign of choking?", "back": "Hands clutching the throat, unable to speak or cough."}, {"type": "flash", "front": "Someone is coughing hard while choking. Intervene?", "back": "No — encourage the cough. A forceful cough can clear it on its own."}, {"type": "flash", "front": "First step for a burn?", "back": "Cool under running water for at least 10 minutes, ASAP."}, {"type": "flash", "front": "Should you put ice or butter on a burn?", "back": "No — both trap heat or risk infection. Cool running water only."}], "checkpoint": {"pass": 70, "questions": [{"q": "How do you tell real choking from just coughing on food?", "choices": ["They can't speak, cough, or breathe", "They're making loud noises", "They're drinking water"], "answer": 0, "explain": "A strong cough means air is moving — encourage it. Silence plus the throat-clutch means the airway is blocked."}, {"q": "Where does your fist go for abdominal thrusts?", "choices": ["Just above the navel", "On the chest", "On the lower back"], "answer": 0, "explain": "Above the navel and below the ribs — the inward-upward thrust pushes air up to expel the object."}, {"q": "A burn should be cooled for at least...", "choices": ["10 minutes", "30 seconds", "Until it stops hurting"], "answer": 0, "explain": "Ten full minutes of cool running water limits tissue damage. Brief cooling barely helps."}, {"q": "Which burn needs emergency care?", "choices": ["A burn covering the whole hand", "A small red mark from a spark", "A mild sunburn"], "answer": 0, "explain": "Burns on hands, face, feet, or joints — or large/deep/white ones — need professionals."}, {"q": "Blisters form on a burn. You should...", "choices": ["Leave them intact", "Pop them to drain fluid", "Peel the skin off"], "answer": 0, "explain": "Intact blisters protect against infection. Cover loosely and let the body handle it."}]}}]}, {"id": "french", "title": "French", "icon": "chat", "color": "#B565D8", "levels": [{"id": "french-1", "title": "Greetings & pronunciation", "cards": [{"type": "text", "title": "Bonjour opens every door", "body": "In France, bonjour is not just hello, it is good manners. You say it entering a shop, greeting a neighbor, starting any conversation. Skip it and people notice. Salut is the casual version, strictly for friends and people your age."}, {"type": "text", "title": "The sounds that trip everyone up", "body": "French has nasal vowels: in bon, the n is not really pronounced, the vowel just hums through your nose. Final consonants usually go silent, so parlent sounds like parl. And the French r comes from the throat, like a soft gargle, not the English tongue-tip roll."}, {"type": "tip", "body": "Bonsoir after dark, bonne nuit only at bedtime. Bonsoir means good evening and you use it from around 6pm. Bonne nuit is strictly good night, said when someone is actually going to sleep. Mixing them up marks you as a beginner instantly."}, {"type": "example", "body": "Marie: Salut! Ça va? (Hi! How's it going?)\nLuc: Ça va bien, merci. Et toi? (Good, thanks. And you?)\nMarie: Très bien! Au revoir! (Great! Goodbye!)\n\nÇa va is the workhorse phrase of French small talk. It means how's it going, and the expected answer is just ça va, fine."}, {"type": "check", "q": "It's 8pm and you walk into a bakery. What do you say?", "choices": ["Bonsoir!", "Bonne nuit!", "Salut mec!"], "answer": 0, "explain": "Bonsoir is good evening, correct after dark. Bonne nuit is only for bedtime. Salut is too casual for a shopkeeper you don't know."}], "flashcards": [{"type": "flash", "front": "What does 'bonjour' literally break down to?", "back": "'Good day' — bon (good) + jour (day). It's a wish, not just a word."}, {"type": "flash", "front": "How do you say 'good evening' in French?", "back": "Bonsoir. Used from evening until bedtime."}, {"type": "flash", "front": "What does 'merci beaucoup' mean?", "back": "'Thanks a lot' — merci (thanks) + beaucoup (a lot)."}, {"type": "flash", "front": "How do you say 'goodbye' in French?", "back": "Au revoir — literally 'until seeing again.'"}], "checkpoint": {"pass": 70, "questions": [{"q": "Which greeting fits a shopkeeper you have never met?", "choices": ["Salut!", "Bonjour!", "Coucou!"], "answer": 1, "explain": "Bonjour is the polite default for strangers. Salut and coucou are for friends."}, {"q": "In the word 'parlent' (they speak), what happens to the final -ent?", "choices": ["It goes silent", "It rhymes with 'went'", "It becomes a z sound"], "answer": 0, "explain": "Final consonants in French usually go silent. Parlent is pronounced 'parl.'"}, {"q": "What makes the French r different from the English r?", "choices": ["It's made in the throat", "It's rolled with the tongue tip", "It's silent"], "answer": 0, "explain": "The French r is guttural, from the back of the throat. The rolled tongue-tip r is Spanish or Italian."}, {"q": "When do you say 'bonne nuit'?", "choices": ["Any time after 6pm", "Only when someone is going to sleep", "As a morning greeting"], "answer": 1, "explain": "Bonne nuit is strictly bedtime. For the evening, it's bonsoir."}, {"q": "What does 's'il vous plaît' mean?", "choices": ["Please (formal)", "Thank you very much", "Excuse me"], "answer": 0, "explain": "It literally means 'if it pleases you' — the formal way to say please. The casual version is s'il te plaît."}]}}, {"id": "french-2", "title": "Essential verbs", "cards": [{"type": "text", "title": "Être: the verb that is everything", "body": "Être means to be, and you cannot say almost anything without it. Je suis (I am), tu es (you are), il/elle est (he/she is), nous sommes (we are), vous êtes (you are, formal/plural), ils/elles sont (they are). Drill these six until they are automatic."}, {"type": "text", "title": "Avoir: to have, and to be hungry", "body": "Avoir means to have: j'ai, tu as, il/elle a, nous avons, vous avez, ils/elles ont. But French uses avoir where English uses be: j'ai faim is literally 'I have hunger' — I am hungry. Same for j'ai soif (I am thirsty) and j'ai 20 ans (I am 20 years old)."}, {"type": "tip", "body": "Aller gives you the future for free. Aller means to go: je vais, tu vas, il va. Put it before any infinitive and you get the near future: je vais manger = I am going to eat. Learn one verb, unlock talking about tomorrow."}, {"type": "example", "body": "Je m'appelle Zoe. J'ai 25 ans. Je suis canadienne.\n(My name is Zoe. I am 25. I am Canadian.)\n\nThree verbs, one introduction: s'appeler (to be called), avoir for age, être for nationality. This exact pattern opens every first conversation."}, {"type": "check", "q": "How do you say 'I am hungry' in French?", "choices": ["J'ai faim", "Je suis faim", "Je faim"], "answer": 0, "explain": "French uses avoir for hunger: j'ai faim, literally 'I have hunger.' Je suis faim applies English logic to French and it doesn't work."}], "flashcards": [{"type": "flash", "front": "Conjugate être (to be) in the present tense.", "back": "je suis, tu es, il/elle est, nous sommes, vous êtes, ils/elles sont"}, {"type": "flash", "front": "Conjugate avoir (to have) in the present tense.", "back": "j'ai, tu as, il/elle a, nous avons, vous avez, ils/elles ont"}, {"type": "flash", "front": "How do you say 'I am 20 years old' in French?", "back": "J'ai 20 ans — French uses 'have' for age, not 'be.'"}, {"type": "flash", "front": "What does 'je vais manger' mean?", "back": "'I am going to eat' — aller + infinitive makes the near future."}], "checkpoint": {"pass": 70, "questions": [{"q": "Which verb means 'to be'?", "choices": ["Avoir", "Être", "Aller"], "answer": 1, "explain": "Être = to be. Avoir = to have. Aller = to go."}, {"q": "'Nous ___ contents.' (We are happy.) Which form fits?", "choices": ["sommes", "êtes", "sont"], "answer": 0, "explain": "Nous takes sommes. Êtes pairs with vous, sont with ils/elles."}, {"q": "Why does French say 'j'ai faim' instead of 'je suis faim'?", "choices": ["French uses avoir for hunger, thirst, and age", "It's a regional slang version", "Both are equally correct"], "answer": 0, "explain": "Hunger, thirst, and age all use avoir in French: j'ai faim, j'ai soif, j'ai 30 ans."}, {"q": "What does 'ils vont' mean?", "choices": ["They go / they are going", "They have", "They are"], "answer": 0, "explain": "Vont is the ils/elles form of aller (to go)."}, {"q": "How do you say 'we have' in French?", "choices": ["Nous avons", "Nous sommes", "Nous allons"], "answer": 0, "explain": "Avons is the nous form of avoir. Sommes = are, allons = go."}]}}, {"id": "french-3", "title": "Food & travel phrases", "cards": [{"type": "text", "title": "Ordering like you mean it", "body": "Je voudrais... means I would like — the magic phrase for restaurants. Je voudrais un café, s'il vous plaît. Le menu, s'il vous plaît gets you the menu. And when you're done, l'addition, s'il vous plaît brings the bill. Never click your fingers or shout; a calm s'il vous plaît works everywhere."}, {"type": "text", "title": "Finding your way", "body": "Où est...? (Where is...?) plus a noun solves most navigation: Où est la gare? (the train station), Où est l'aéroport? (the airport), Où sont les toilettes? (the toilets). Add à gauche (left), à droite (right), tout droit (straight ahead) and you can follow any local's directions."}, {"type": "tip", "body": "Parlez-vous anglais? buys you goodwill. Asking 'do you speak English?' in French before switching to English shows respect, and locals help far more willingly. Follow it with lentement, s'il vous plaît (slowly, please) if they're racing ahead."}, {"type": "example", "body": "Serveur: Bonsoir! Vous avez choisi? (Did you decide?)\nVous: Oui. Je voudrais le poulet, s'il vous plaît. (Yes. I'd like the chicken, please.)\nServeur: Et comme boisson? (And to drink?)\nVous: Un verre d'eau, merci. (A glass of water, thanks.)\n\nPolite, complete, no panic. This script handles 90% of restaurant visits."}, {"type": "check", "q": "You want the bill at a Paris café. What do you say?", "choices": ["L'addition, s'il vous plaît", "Le menu, s'il vous plaît", "Ça va?"], "answer": 0, "explain": "L'addition is the bill. Le menu would bring you another menu, and ça va asks how things are."}], "flashcards": [{"type": "flash", "front": "How do you say 'I would like...' in French?", "back": "Je voudrais... — the key phrase for ordering."}, {"type": "flash", "front": "What does 'où est la gare?' mean?", "back": "'Where is the train station?' — où est = where is."}, {"type": "flash", "front": "How do you ask 'how much does it cost?'", "back": "Combien ça coûte?"}, {"type": "flash", "front": "What does 'l'addition, s'il vous plaît' get you?", "back": "The bill, politely — l'addition is the check."}], "checkpoint": {"pass": 70, "questions": [{"q": "What does 'je voudrais un café' mean?", "choices": ["I would like a coffee", "I made a coffee", "Coffee is ready"], "answer": 0, "explain": "Je voudrais = I would like. It's the polite conditional form of vouloir."}, {"q": "Someone says 'à droite'. Which way do you go?", "choices": ["Right", "Left", "Straight"], "answer": 0, "explain": "À droite = right, à gauche = left, tout droit = straight ahead."}, {"q": "Why start with 'parlez-vous anglais?' instead of just speaking English?", "choices": ["It shows respect and gets better help", "It's legally required", "English is banned in shops"], "answer": 0, "explain": "Asking in French first signals respect. People are far more willing to help."}, {"q": "What is 'le fromage'?", "choices": ["Cheese", "Bread", "Wine"], "answer": 0, "explain": "Fromage = cheese. Pain = bread, vin = wine — the holy trinity of French food."}, {"q": "How do you say 'where are the toilets?'", "choices": ["Où sont les toilettes?", "Où est le menu?", "Combien ça coûte?"], "answer": 0, "explain": "Où sont = where are (plural). Les toilettes = the toilets."}]}}]}, {"id": "garden", "title": "Gardening", "icon": "sprout", "color": "#82CD47", "levels": [{"id": "garden-1", "title": "Soil & seeds", "cards": [{"type": "text", "title": "Soil is not just dirt", "body": "Good soil is roughly 45% minerals, 25% water, 25% air, and 5% organic matter. Roots need all four: minerals feed the plant, water carries nutrients, air lets roots breathe, and organic matter (compost) holds it all together."}, {"type": "text", "title": "Know your soil type", "body": "Squeeze a handful of damp soil: sandy soil crumbles instantly and drains fast, clay forms a tight ball and holds water, loam holds a loose shape and crumbles when poked — that's the jackpot. Most vegetables want loam."}, {"type": "tip", "body": "The finger test beats any gadget: push your finger 2 inches into the soil. Dry? Water. Moist? Wait. Soggy? Your plant is drowning — improve drainage before it rots."}, {"type": "example", "body": "Starting tomatoes: sow seeds ¼ inch deep in seed mix (not garden soil), keep at 70-75°F, and they'll sprout in 5-10 days. A seed planted twice as deep as it is wide is the rule of thumb."}, {"type": "check", "q": "Your damp soil forms a tight sticky ball. What type is it?", "choices": ["Sandy", "Clay", "Loam"], "answer": 1, "explain": "Clay particles are tiny and pack tightly, holding water and forming balls. Sandy soil crumbles; loam holds a loose shape."}], "flashcards": [{"type": "flash", "front": "What are the four parts of healthy soil?", "back": "Minerals (~45%), water (~25%), air (~25%), organic matter (~5%)."}, {"type": "flash", "front": "Which soil type do most vegetables prefer?", "back": "Loam — holds shape loosely, drains well, rich in nutrients."}, {"type": "flash", "front": "How deep should you plant a seed?", "back": "About twice as deep as the seed is wide."}, {"type": "flash", "front": "What does the finger test tell you?", "back": "Whether soil 2 inches down is dry (water), moist (wait), or soggy (drainage problem)."}], "checkpoint": {"pass": 70, "questions": [{"q": "Why do roots need air in the soil?", "choices": ["Air makes soil warmer", "Worms need air to dig", "Roots breathe and can suffocate in waterlogged soil"], "answer": 2, "explain": "Roots respire like the rest of the plant. Waterlogged soil squeezes out air pockets and roots rot."}, {"q": "What does compost (organic matter) do for soil?", "choices": ["Holds nutrients and moisture, feeds soil life", "Makes soil purely sand", "Replaces the need for sunlight"], "answer": 0, "explain": "Compost is the glue: it holds water and nutrients, feeds microbes, and improves both sandy and clay soils."}, {"q": "You plant bean seeds 3 inches deep and few sprout. What went wrong?", "choices": ["Beans don't grow from seeds", "Planted too deep — seedlings ran out of energy", "The soil was too warm"], "answer": 1, "explain": "Seeds carry limited stored energy. Buried too deep, the sprout exhausts itself before reaching light."}, {"q": "Sandy soil drains in minutes and plants wilt fast. What's the fix?", "choices": ["Water less often", "Mix in compost to hold moisture", "Add more sand"], "answer": 1, "explain": "Compost acts like a sponge in sandy soil, holding water where roots can reach it."}, {"q": "A seed packet says 'sow after last frost.' Why does timing matter?", "choices": ["Cold soil slows germination and frost kills seedlings", "Frost makes seeds grow faster", "Seeds only sprout in summer heat"], "answer": 0, "explain": "Most seeds need warm soil to germinate, and tender seedlings die in frost. Timing matches the seed's biology."}]}}, {"id": "garden-2", "title": "Water & light", "cards": [{"type": "text", "title": "Water deeply, not daily", "body": "Shallow daily sprinkles train roots to stay near the surface, where they dry out fast. One deep watering per week pushes roots downward into cool, moist soil — building drought-proof plants. Most vegetables want about 1 inch of water per week."}, {"type": "text", "title": "Read the plant, not the calendar", "body": "Wilting in the morning means thirsty; wilting only in afternoon heat is normal. Yellow lower leaves often mean overwatering, while crispy brown edges mean underwatering. The plant is always telling you something — learn its language."}, {"type": "tip", "body": "Water the soil, not the leaves. Wet foliage invites fungal disease; a soaker hose or watering can at the base keeps leaves dry and delivers water where roots actually are."}, {"type": "example", "body": "Tomatoes in July: water deeply 2-3 times per week (about 1-1.5 inches total), mulch 3 inches around the base, and water in the morning so leaves dry by evening. Blossom-end rot? That's inconsistent watering, not a disease."}, {"type": "check", "q": "Your plant's lower leaves are yellow and the soil is soggy. What's wrong?", "choices": ["Not enough sun", "Underwatering", "Overwatering"], "answer": 2, "explain": "Yellow lower leaves plus soggy soil is classic overwatering — roots are suffocating. Let it dry out."}], "flashcards": [{"type": "flash", "front": "How much water do most vegetables need weekly?", "back": "About 1 inch, delivered in deep waterings rather than daily sprinkles."}, {"type": "flash", "front": "Why water deeply instead of daily?", "back": "Deep watering drives roots downward into reliably moist soil; shallow watering keeps roots weak near the surface."}, {"type": "flash", "front": "What is 'full sun'?", "back": "At least 6 hours of direct sunlight per day."}, {"type": "flash", "front": "Why water in the morning?", "back": "Leaves dry by evening, which prevents fungal disease; less water evaporates than at midday."}], "checkpoint": {"pass": 70, "questions": [{"q": "Two gardeners: one sprinkles 10 minutes daily, one soaks deeply twice a week. Whose plants survive a heatwave?", "choices": ["The deep waterer's", "Neither — heat kills everything", "The daily sprinkler's"], "answer": 0, "explain": "Deep roots reach cool, moist soil. Shallow roots sit in the layer that dries first."}, {"q": "What does 'partial shade' mean for a plant label?", "choices": ["Full sun all day", "3-6 hours of direct sun daily", "No direct sun at all"], "answer": 1, "explain": "Partial shade plants want some direct sun but shelter from harsh afternoon rays."}, {"q": "Your lettuce bolts (flowers) in July heat. What happened?", "choices": ["Heat triggered it to finish its life cycle early", "It needs more water only", "Lettuce always flowers in July"], "answer": 0, "explain": "Lettuce is a cool-season crop; heat signals it to bolt and turn bitter. Plant it for spring or fall."}, {"q": "Why mulch around plants?", "choices": ["Makes soil drain instantly", "Holds moisture, cools soil, blocks weeds", "Feeds leaves directly"], "answer": 1, "explain": "A 2-3 inch mulch layer is a blanket: it slows evaporation, steadies soil temperature, and smothers weeds."}, {"q": "Seedlings stretch tall and floppy on a windowsill. What's missing?", "choices": ["Water", "Fertilizer", "Enough light"], "answer": 2, "explain": "Leggy seedlings are reaching for more light. Move them closer to the window or add a grow light."}]}}, {"id": "garden-3", "title": "Pest control", "cards": [{"type": "text", "title": "Know your enemy", "body": "The usual suspects: aphids (tiny sap-suckers clustering on new growth), slugs (night slime trails and chewed holes), cabbage worms (green caterpillars on brassicas), and spider mites (fine webbing, stippled leaves). Identify before you act — the fix depends on the pest."}, {"type": "text", "title": "Start with the gentlest fix", "body": "Integrated pest management means escalating slowly: handpick first, then blast aphids off with a hose, then insecticidal soap or neem oil, and only then stronger measures. Most infestations never need chemicals — they need attention."}, {"type": "tip", "body": "Invite the predators: ladybugs devour aphids, lacewings eat mites, and birds patrol for caterpillars. A garden with flowers for beneficial insects has its own security team working for free."}, {"type": "example", "body": "Aphids on your roses: blast them off with a strong jet of water, repeat every 2-3 days. Still there? Spray insecticidal soap in the evening (never in hot sun). Gone in a week, pollinators unharmed."}, {"type": "check", "q": "You find clusters of tiny green insects on new rose shoots. What are they, and what's the first move?", "choices": ["Aphids — blast off with water", "Spider mites — remove the plant", "Caterpillars — spray pesticide"], "answer": 0, "explain": "Classic aphids. A water jet knocks most off; escalate only if they return."}], "flashcards": [{"type": "flash", "front": "What are aphids?", "back": "Tiny sap-sucking insects that cluster on new growth and buds."}, {"type": "flash", "front": "What is neem oil?", "back": "A plant-derived oil that disrupts insect feeding and reproduction — organic-approved."}, {"type": "flash", "front": "Name a beneficial garden insect.", "back": "Ladybug (eats aphids), lacewing (eats mites), or parasitic wasp."}, {"type": "flash", "front": "What is companion planting?", "back": "Growing plants together so one repels pests or helps the other — e.g. marigolds near tomatoes."}], "checkpoint": {"pass": 70, "questions": [{"q": "Why handpick pests before reaching for sprays?", "choices": ["Sprays never work", "Handpicking is faster for large gardens", "It's targeted, free, and harms nothing else"], "answer": 2, "explain": "Handpicking removes only the pest. Sprays can kill beneficial insects and pollinators too."}, {"q": "Slugs shred your lettuce every night. What's an organic fix?", "choices": ["Spray the leaves with fertilizer", "Water more at night", "Beer traps or copper barriers"], "answer": 2, "explain": "Slugs drown in sunken beer traps and won't cross copper. Night watering just invites more slugs."}, {"q": "Marigolds planted around tomatoes reduce which problem?", "choices": ["Fungal wilt only", "Root-knot nematodes and some insects", "Bird damage"], "answer": 1, "explain": "Marigold roots release compounds that suppress nematodes, and their scent confuses some pests."}, {"q": "You spray insecticide at noon in full sun. What goes wrong?", "choices": ["Leaves burn and pollinators get hit", "It only affects the soil", "Nothing — noon is ideal"], "answer": 0, "explain": "Sprays + hot sun = leaf burn. Midday is also peak pollinator activity. Spray in the evening."}, {"q": "After wiping out every insect with broad spray, aphids return worse than before. Why?", "choices": ["Aphids are immune to spray", "You also killed their predators", "The plants attracted more"], "answer": 1, "explain": "Broad sprays kill ladybugs and lacewings too. Without predators, the fastest breeders — aphids — explode."}]}}]}, {"id": "geo", "title": "Geography", "icon": "globe", "color": "#5DADE2", "levels": [{"id": "geo-1", "title": "Maps & continents", "cards": [{"type": "text", "title": "The world in seven pieces", "body": "Earth's land is split into seven continents: Asia, Africa, North America, South America, Antarctica, Europe, and Australia. Asia is the biggest by far — it holds about 60 percent of all humans. Antarctica is the odd one out: a frozen continent with no permanent residents."}, {"type": "text", "title": "Oceans glue it together", "body": "Five oceans fill the gaps between continents: Pacific, Atlantic, Indian, Southern, and Arctic. The Pacific alone covers more area than all the land on Earth combined. Every coastline you know touches one of these five."}, {"type": "tip", "body": "Remember the seven with a silly sentence: All Ants Are Eating Apples Near Australia — Africa, Antarctica, Asia, Europe, Australia, North America... wait, that skips South America. Try: 'Aunt Annie Ate Eggs And Sausages' for Africa, Antarctica, Asia, Europe, Australia, North America, South America."}, {"type": "example", "body": "Find yourself on the map: pick any city you know, then name its continent, then the ocean nearest to it. Toronto? North America, Atlantic side. Sydney? Australia, Pacific side. Three facts per city, and the map starts feeling like home."}, {"type": "check", "q": "Which is the largest continent?", "choices": ["Asia", "Africa", "North America"], "answer": 0, "explain": "Asia dwarfs the rest — about 44 million square kilometers, roughly a third of Earth's land. Africa is second, North America third."}], "flashcards": [{"type": "flash", "front": "How many continents are there?", "back": "Seven: Asia, Africa, North America, South America, Antarctica, Europe, Australia."}, {"type": "flash", "front": "Which ocean is the largest?", "back": "The Pacific — bigger than all of Earth's land put together."}, {"type": "flash", "front": "Which continent has no permanent residents?", "back": "Antarctica. Only researchers stay there, and only temporarily."}, {"type": "flash", "front": "Name the five oceans.", "back": "Pacific, Atlantic, Indian, Southern, and Arctic."}], "checkpoint": {"pass": 70, "questions": [{"type": "check", "q": "How many continents does Earth have?", "choices": ["7", "5", "6"], "answer": 0, "explain": "Seven: Asia, Africa, North America, South America, Antarctica, Europe, Australia. Five is the number of oceans."}, {"type": "check", "q": "The Pacific Ocean is...?", "choices": ["Larger than all Earth's land combined", "About the size of Asia", "Smaller than the Atlantic"], "answer": 0, "explain": "The Pacific covers about 165 million square kilometers — more than every continent added together."}, {"type": "check", "q": "Which continent is the odd one out for population?", "choices": ["Antarctica", "Australia", "Europe"], "answer": 0, "explain": "Antarctica has zero permanent residents. Australia has about 26 million people; Europe has over 700 million."}, {"type": "check", "q": "Toronto sits on which continent?", "choices": ["North America", "Europe", "Asia"], "answer": 0, "explain": "Toronto, Canada is firmly in North America. Its nearest ocean is the Atlantic."}, {"type": "check", "q": "Which ocean touches Australia's east coast?", "choices": ["Pacific", "Indian", "Atlantic"], "answer": 0, "explain": "Australia's east coast — Sydney, Brisbane — faces the Pacific. The Indian Ocean is on the west."}]}}, {"id": "geo-2", "title": "Climate zones", "cards": [{"type": "text", "title": "Three bands run the weather", "body": "Earth has three main climate zones. The tropics wrap the equator — hot and wet all year. The temperate zones sit in the middle — that's where seasons happen. The polar zones cap the top and bottom — cold almost all the time. Your latitude decides your wardrobe."}, {"type": "text", "title": "Rain has favorite addresses", "body": "Tropical rainforests near the equator get rain nearly every afternoon. Deserts like the Sahara sit around 30 degrees north and south, where dry air sinks. Same planet, opposite weather — it's all about how air moves."}, {"type": "tip", "body": "Latitude is the cheat code: 0° is the equator (hot), 23.5° marks the tropics' edge, 66.5° starts the polar circles. If you know a place's latitude, you can guess its climate before you ever visit."}, {"type": "example", "body": "Compare Quito, Ecuador (on the equator, but high in the Andes) with Singapore (on the equator, at sea level). Both tropical by latitude — but Quito feels like spring year-round while Singapore is hot and steamy. Altitude rewrites the rules latitude sets."}, {"type": "check", "q": "Where do deserts like the Sahara mostly sit?", "choices": ["Around 30° north and south of the equator", "Right on the equator", "Near the poles"], "answer": 0, "explain": "Dry air sinks around 30° latitude, squeezing out moisture. That's why the Sahara, the Arabian desert, and Australia's outback all sit near that line."}], "flashcards": [{"type": "flash", "front": "What are Earth's three main climate zones?", "back": "Tropical (hot, near equator), temperate (seasons, mid-latitudes), polar (cold, near the poles)."}, {"type": "flash", "front": "Why is it hot at the equator?", "back": "The sun's rays hit most directly there, year-round."}, {"type": "flash", "front": "Where do most deserts form?", "back": "Around 30° north and south latitude, where dry air sinks."}, {"type": "flash", "front": "What can change a place's climate besides latitude?", "back": "Altitude — high places are cooler. Quito sits on the equator but feels like spring because it's 2,850 meters up."}], "checkpoint": {"pass": 70, "questions": [{"type": "check", "q": "Which zone gets all four seasons?", "choices": ["Temperate", "Tropical", "Polar"], "answer": 0, "explain": "The temperate zones, between the tropics and the polar circles, tilt in and out of the sun — that's what makes spring, summer, autumn, winter."}, {"type": "check", "q": "The tropics are hot because...?", "choices": ["The sun hits most directly there", "They're closest to the sun in space", "They have no atmosphere"], "answer": 0, "explain": "It's about angle, not distance. Near the equator the sun's rays strike nearly straight down all year."}, {"type": "check", "q": "Deserts cluster near 30° latitude because...?", "choices": ["Dry air sinks there", "It's farthest from the oceans", "Mountains block all wind"], "answer": 0, "explain": "Global air circulation sinks dry air around 30° north and south. Some deserts have other causes, but this is the big pattern."}, {"type": "check", "q": "Two cities on the equator can feel very different if...?", "choices": ["One is much higher in altitude", "One is near a river", "They're in different hemispheres"], "answer": 0, "explain": "Altitude cools things fast — about 6.5°C per kilometer up. That's why Quito feels springlike while Singapore swelters."}, {"type": "check", "q": "Polar zones are cold mainly because...?", "choices": ["Sunlight arrives at a shallow angle", "They're in permanent shadow", "Ice reflects all heat away"], "answer": 0, "explain": "Near the poles the sun stays low, so its energy spreads thin over a wide area. The ice reflecting heat back just doubles down on the cold."}]}}, {"id": "geo-3", "title": "Capitals of the world", "cards": [{"type": "text", "title": "Capitals aren't always the biggest", "body": "A capital is where the government sits — not necessarily the biggest city. Washington D.C. runs the US, but New York is far larger. Canberra runs Australia while Sydney gets the fame. Size and power live in different zip codes."}, {"type": "text", "title": "Some capitals moved on purpose", "body": "Brasília was built from scratch in the 1960s to pull Brazil's capital inland from Rio. Ottawa was picked as a compromise between Toronto and Montreal. Capitals are political choices, not popularity contests."}, {"type": "tip", "body": "Learn capitals in pairs with a hook: Paris–France (fashion), Tokyo–Japan (tech), Cairo–Egypt (pyramids), Ottawa–Canada (polite), Canberra–Australia (not Sydney! — that's the classic trap)."}, {"type": "example", "body": "Quiz yourself the fun way: name a country, then blurt its capital before three seconds pass. France — Paris. Japan — Tokyo. Egypt — Cairo. Speed beats staring at lists."}, {"type": "check", "q": "What's the capital of Australia?", "choices": ["Canberra", "Sydney", "Melbourne"], "answer": 0, "explain": "Canberra — the planned capital. Sydney is the famous one, which is exactly why this question traps people."}], "flashcards": [{"type": "flash", "front": "Capital of France?", "back": "Paris."}, {"type": "flash", "front": "Capital of Japan?", "back": "Tokyo."}, {"type": "flash", "front": "Capital of Canada?", "back": "Ottawa (not Toronto!)."}, {"type": "flash", "front": "Capital of Brazil?", "back": "Brasília (not Rio de Janeiro)."}], "checkpoint": {"pass": 70, "questions": [{"type": "check", "q": "Capital of Egypt?", "choices": ["Cairo", "Alexandria", "Giza"], "answer": 0, "explain": "Cairo — home to about 20 million people in its metro area. Alexandria is the famous port; Giza holds the pyramids but isn't the capital."}, {"type": "check", "q": "Which is NOT a capital?", "choices": ["Sydney", "Ottawa", "Paris"], "answer": 0, "explain": "Sydney is Australia's biggest city but Canberra is the capital. Ottawa and Paris are both real capitals."}, {"type": "check", "q": "Why was Brasília built?", "choices": ["To move Brazil's capital inland from Rio", "Because Rio sank", "As a backup during wartime"], "answer": 0, "explain": "Brazil built Brasília from nothing in the late 1950s and moved the capital there in 1960, to develop the interior."}, {"type": "check", "q": "Washington D.C. vs New York — which is the capital?", "choices": ["Washington D.C.", "New York", "Both share it"], "answer": 0, "explain": "D.C. holds the government; New York holds the population and the money. Capitals are about power, not size."}, {"type": "check", "q": "Capital of the United Kingdom?", "choices": ["London", "Manchester", "Edinburgh"], "answer": 0, "explain": "London. Edinburgh is Scotland's capital, Manchester is a major city — but the UK's seat of government is London."}]}}]}, {"id": "hindi", "title": "Hindi", "icon": "chat", "color": "#FF9933", "levels": [{"id": "hindi-1", "title": "Greetings & the script", "cards": [{"type": "text", "title": "Namaste opens every door", "body": "नमस्ते (namaste) is hello, goodbye, and good morning rolled into one. It comes from Sanskrit: 'I bow to the divine in you.' Use it with anyone, anywhere, and doors open."}, {"type": "text", "title": "Devanagari reads left to right", "body": "Hindi is written in Devanagari, which reads left to right like English. The big difference: every consonant carries a built-in 'a' sound. क is not 'k' — it's 'ka'. A small slash called a halant (्) kills the 'a' when you don't want it."}, {"type": "example", "body": "Meet the vowels: अ (a) आ (aa) इ (i) ई (ee) उ (u) ऊ (oo) ए (e) ऐ (ai) ओ (o) औ (au). These ten vowels combine with every consonant. क + ी becomes की (kee). Once you know ten vowels and the consonants, you can sound out almost any word."}, {"type": "tip", "body": "Don't memorize the whole script chart at once. Learn five letters a day and write real words with them — your hand remembers what your eyes forget."}, {"type": "check", "q": "What does नमस्ते (namaste) mean?", "choices": ["A greeting like hello", "Good night only", "Thank you"], "answer": 0, "explain": "Namaste works as hello, goodbye, and good morning — the all-purpose greeting. Good night is शुभ रात्रि (shubh raatri), thank you is धन्यवाद (dhanyavaad)."}], "flashcards": [{"type": "flash", "front": "नमस्ते (namaste)", "back": "Hello / goodbye — the universal Hindi greeting."}, {"type": "flash", "front": "धन्यवाद (dhanyavaad)", "back": "Thank you."}, {"type": "flash", "front": "हाँ (haan) / नहीं (nahin)", "back": "Yes / no."}, {"type": "flash", "front": "क (ka)", "back": "The consonant क carries a built-in 'a' sound — it's 'ka', not 'k'."}], "checkpoint": {"pass": 70, "questions": [{"q": "How is Devanagari read?", "choices": ["Left to right, like English", "Right to left", "Top to bottom"], "answer": 0, "explain": "Devanagari reads left to right, same direction as English. (Arabic and Urdu read right to left — a common mix-up.)"}, {"q": "What sound does the consonant क make on its own?", "choices": ["ka", "k", "kee"], "answer": 0, "explain": "Every Devanagari consonant carries an inherent 'a'. क is 'ka' until a halant or vowel mark changes it."}, {"q": "Someone says नमस्ते to you. You reply…", "choices": ["नमस्ते", "अलविदा", "धन्यवाद"], "answer": 0, "explain": "Namaste answers namaste. अलविदा (alvida) is a farewell, धन्यवाद is thank you — both fine words, wrong moment."}, {"q": "What does the halant mark (्) do?", "choices": ["Removes the consonant's built-in 'a' sound", "Makes the letter louder", "Marks the end of a sentence"], "answer": 0, "explain": "The halant silences the inherent 'a'. That's how क (ka) becomes क् (k) when you need a pure consonant."}, {"q": "Which of these means 'thank you'?", "choices": ["धन्यवाद", "नमस्ते", "हाँ"], "answer": 0, "explain": "धन्यवाद (dhanyavaad) is thank you. नमस्ते is hello, हाँ (haan) is yes."}]}}, {"id": "hindi-2", "title": "Verbs you'll use daily", "cards": [{"type": "text", "title": "Verbs end in -ना", "body": "Almost every Hindi infinitive ends in ना (naa): करना (karnaa, to do), जाना (jaanaa, to go), खाना (khaanaa, to eat), पीना (peenaa, to drink). Spot the ना ending and you've found the verb."}, {"type": "text", "title": "Present tense is beautifully regular", "body": "Drop the ना, add ता/ती/ते. मैं खाता हूँ (main khaataa hoon) = I eat (male speaker). मैं खाती हूँ (main khaatee hoon) = I eat (female speaker). The verb ending changes with the speaker's gender — the first real twist of Hindi."}, {"type": "example", "body": "वह जाता है (vah jaataa hai) — He goes.\nवह जाती है (vah jaatee hai) — She goes.\nहम खाते हैं (ham khaate hain) — We eat.\n\nSwap the ending, keep the root. जा (jaa) is the root of जाना; खा (khaa) is the root of खाना."}, {"type": "tip", "body": "Learn verbs in pairs with their opposites: आना (to come) / जाना (to go), खाना (to eat) / पीना (to drink). Opposites stick together in memory."}, {"type": "check", "q": "मैं पीता हूँ (main peetaa hoon) means…", "choices": ["I drink (male speaker)", "She drinks", "They drank"], "answer": 0, "explain": "पीता (peetaa) is the masculine present form of पीना, and हूँ marks 'I'. So: I drink, said by a man."}], "flashcards": [{"type": "flash", "front": "करना (karnaa)", "back": "To do."}, {"type": "flash", "front": "जाना (jaanaa)", "back": "To go."}, {"type": "flash", "front": "खाना (khaanaa)", "back": "To eat."}, {"type": "flash", "front": "मैं ___ हूँ (main ___ hoon)", "back": "The frame for 'I ___' in the present tense — drop the verb root in the middle."}], "checkpoint": {"pass": 70, "questions": [{"q": "How do you spot a Hindi infinitive?", "choices": ["It ends in ना (naa)", "It starts with मैं", "It has no vowels"], "answer": 0, "explain": "The ना ending is the infinitive marker: करना, जाना, खाना. It's the dictionary form of the verb."}, {"q": "वह खाती है (vah khaatee hai) — who is eating?", "choices": ["She", "He", "They"], "answer": 0, "explain": "The ती (tee) ending marks feminine. खाती = she eats. Masculine would be खाता (khaataa)."}, {"q": "What is the root of जाना (to go)?", "choices": ["जा (jaa)", "जान", "ना"], "answer": 0, "explain": "Drop the ना infinitive ending and जा remains. The root is what you build tenses on."}, {"q": "Which pair are opposites?", "choices": ["आना / जाना (come / go)", "खाना / पीना (eat / drink)", "Both pairs"], "answer": 2, "explain": "Both are opposites — come/go and eat/drink. Learning verbs in opposite pairs is the fastest way to double your vocabulary."}, {"q": "मैं जाता हूँ uses हूँ because…", "choices": ["the speaker is saying 'I'", "it's past tense", "it's a question"], "answer": 0, "explain": "हूँ (hoon) is the 'I' form of होना (to be). मैं (main) = I, so the sentence needs हूँ to agree."}]}}, {"id": "hindi-3", "title": "Everyday conversation", "cards": [{"type": "text", "title": "Introduce yourself in one line", "body": "मेरा नाम ___ है (meraa naam ___ hai) — My name is ___. और आप? (aur aap?) — And you? That's a whole introduction. आप (aap) is the respectful 'you'; तुम (tum) is for friends and kids."}, {"type": "text", "title": "Ask like a local", "body": "कितने का है? (kitne kaa hai?) — How much is it? कहाँ है…? (kahaan hai…?) — Where is…? Two questions that survive any market, station, or street in India."}, {"type": "example", "body": "A: आप कैसे हैं? (aap kaise hain?) — How are you?\nB: मैं ठीक हूँ, धन्यवाद। (main theek hoon, dhanyavaad.) — I'm fine, thank you.\nऔर आप? (aur aap?) — And you?\n\nMemorize this exchange whole. It's the most common conversation in Hindi."}, {"type": "tip", "body": "Hindi speakers love it when learners try. Even broken Hindi with a smile gets warmer responses than perfect English — effort is the whole game."}, {"type": "check", "q": "You're shopping. The price matters. You ask…", "choices": ["कितने का है? (kitne kaa hai?)", "मेरा नाम क्या है?", "कहाँ है बाज़ार?"], "answer": 0, "explain": "कितने का है means 'how much is it' — the market question. The others ask your name and where the market is."}], "flashcards": [{"type": "flash", "front": "मेरा नाम ___ है (meraa naam ___ hai)", "back": "My name is ___."}, {"type": "flash", "front": "आप कैसे हैं? (aap kaise hain?)", "back": "How are you? (respectful)"}, {"type": "flash", "front": "कितने का है? (kitne kaa hai?)", "back": "How much is it?"}, {"type": "flash", "front": "कहाँ है…? (kahaan hai…?)", "back": "Where is…? (add the place after)"}], "checkpoint": {"pass": 70, "questions": [{"q": "Why use आप (aap) instead of तुम (tum) with strangers?", "choices": ["आप is respectful; तुम is familiar", "तुम is more polite", "They mean different verbs"], "answer": 0, "explain": "आप is the respectful 'you' for strangers and elders. तुम is for friends, kids, and peers. Using आप with strangers is never wrong."}, {"q": "मेरा नाम अर्जुन है means…", "choices": ["My name is Arjun", "His name is Arjun", "I am Arjun's friend"], "answer": 0, "explain": "मेरा (meraa) = my, नाम (naam) = name, है (hai) = is. Word for word: 'my name Arjun is.'"}, {"q": "You want directions. Best opener?", "choices": ["कहाँ है…? (where is…?)", "कितने का है? (how much?)", "मैं ठीक हूँ (I'm fine)"], "answer": 0, "explain": "कहाँ है with the place name gets you directions. The price question is for shopping; 'I'm fine' answers a greeting."}, {"q": "Someone asks और आप? You…", "choices": ["answer about yourself — they asked 'and you?'", "say thank you", "repeat your name"], "answer": 0, "explain": "और आप? means 'and you?' — it's your turn to answer the question they just answered."}, {"q": "Which sentence is a complete greeting exchange?", "choices": ["नमस्ते! आप कैसे हैं?", "कितने का है धन्यवाद", "मेरा नाम कहाँ है"], "answer": 0, "explain": "नमस्ते (hello) + आप कैसे हैं (how are you) is the classic opener. The others mash unrelated phrases together."}]}}]}, {"id": "history", "title": "World History", "icon": "scroll", "color": "#8B5E3C", "levels": [{"id": "history-1", "title": "Ancient civilizations", "cards": [{"type": "text", "title": "Writing started in Mesopotamia", "body": "Around 3400 BCE, the Sumerians in Mesopotamia (modern Iraq) pressed reeds into clay to track grain and taxes. That bookkeeping became cuneiform, the first writing system. Cities, laws, and empires followed: writing let humans organize at a scale memory alone never could."}, {"type": "text", "title": "Egypt, Greece, Rome: the greatest-hits tour", "body": "Egypt raised the pyramids around 2560 BCE as tombs for pharaohs. Greece gave us democracy, philosophy, and the Olympics. Rome turned a republic into an empire spanning three continents, then split and fell in the west in 476 CE — the date that traditionally ends ancient history."}, {"type": "tip", "body": "Anchor the timeline with three dates. 3400 BCE: writing appears. 2560 BCE: the Great Pyramid. 476 CE: Rome falls in the west. Everything ancient slots between or around these pegs."}, {"type": "example", "body": "The Great Pyramid was built around 2560 BCE — about 4,500 years ago. Cleopatra lived closer in time to the Moon landing (1969) than to the pyramid's construction. Ancient history is far deeper than it feels."}, {"type": "check", "q": "Why is 476 CE a landmark date?", "choices": ["The western Roman Empire fell", "The pyramids were built", "Writing was invented"], "answer": 0, "explain": "476 CE marks the fall of Rome in the west and the conventional end of ancient history."}], "flashcards": [{"type": "flash", "front": "Where and when did writing first appear?", "back": "Mesopotamia (Sumer), around 3400 BCE."}, {"type": "flash", "front": "What were the Egyptian pyramids built as?", "back": "Tombs for pharaohs."}, {"type": "flash", "front": "Name two things ancient Greece gave the world.", "back": "Democracy and philosophy (also the Olympics, geometry, theater)."}, {"type": "flash", "front": "In what year did the western Roman Empire fall?", "back": "476 CE."}], "checkpoint": {"pass": 70, "questions": [{"q": "What drove the invention of cuneiform?", "choices": ["Tracking grain and taxes", "Writing poetry", "Sending love letters"], "answer": 0, "explain": "It started as accounting — reed marks in clay recording goods before it became literature."}, {"q": "The Great Pyramid was built roughly:", "choices": ["4,500 years ago", "1,000 years ago", "10,000 years ago"], "answer": 0, "explain": "Around 2560 BCE. It's far older than most people guess."}, {"q": "Which civilization is credited with democracy?", "choices": ["Greece", "Egypt", "Mesopotamia"], "answer": 0, "explain": "Athens developed demokratia — rule by the people — in the 5th century BCE."}, {"q": "What happened in 476 CE?", "choices": ["The western Roman Empire fell", "Julius Caesar was assassinated", "Rome was founded"], "answer": 0, "explain": "The deposition of the last western emperor is the traditional end of antiquity in Europe."}, {"q": "Why did writing change civilization?", "choices": ["It let humans organize beyond what memory allowed", "It made everyone a poet", "It replaced spoken language"], "answer": 0, "explain": "Laws, taxes, history, and empires all need records. Writing scaled organization past tribal memory."}]}}, {"id": "history-2", "title": "Middle ages", "cards": [{"type": "text", "title": "Rome falls, feudalism rises", "body": "After 476 CE, western Europe fragmented. With no empire to keep order, a system called feudalism took hold: kings granted land to lords, lords gave protection to knights and peasants, and everyone owed loyalty upward. It was messy, local, and lasted nearly a thousand years."}, {"type": "text", "title": "Crusades, plague, and parchment", "body": "From 1095, popes called crusades to retake the Holy Land — waves of religious war spanning two centuries. Then in 1347 the Black Death arrived, killing a third to half of Europe. But the same era produced universities, Gothic cathedrals, and the Magna Carta (1215), which first said a king is not above the law."}, {"type": "tip", "body": "The 'Dark Ages' weren't uniformly dark. While Europe fragmented, the Islamic Golden Age preserved and advanced Greek science, and China under the Song dynasty printed books and used gunpowder. History's spotlight just moves around."}, {"type": "example", "body": "A medieval peasant's year: spring planting, summer harvest, autumn slaughter and salting meat, winter mending tools by the fire. About 90% of people farmed. Your entire life was the 5 kilometers around your village, and news traveled at walking speed."}, {"type": "check", "q": "What did the Magna Carta (1215) establish?", "choices": ["Even the king is subject to law", "The pope rules England", "Feudalism is abolished"], "answer": 0, "explain": "English barons forced King John to accept legal limits — the seed of constitutional government."}], "flashcards": [{"type": "flash", "front": "What years mark the traditional Middle Ages?", "back": "Roughly 476 CE to 1500 CE."}, {"type": "flash", "front": "What was feudalism?", "back": "A system of land-for-loyalty: kings, lords, knights, and peasants bound by mutual obligations."}, {"type": "flash", "front": "When did the Black Death strike Europe?", "back": "1347–1352."}, {"type": "flash", "front": "What was the Magna Carta?", "back": "A 1215 charter limiting the English king's power — the idea that rulers obey the law."}], "checkpoint": {"pass": 70, "questions": [{"q": "What filled the power vacuum after Rome fell in the west?", "choices": ["Feudalism — local lords trading protection for loyalty", "Immediate democracy", "A single European empire"], "answer": 0, "explain": "With no central state, power went local: land, oaths, and armed horsemen."}, {"q": "What were the Crusades?", "choices": ["Religious wars to retake the Holy Land, from 1095", "Trade missions to China", "Peasant revolts against lords"], "answer": 0, "explain": "Pope Urban II called the first in 1095; the campaigns ran for about two centuries."}, {"q": "Roughly how much of Europe died in the Black Death?", "choices": ["A third to a half", "One in a hundred", "Almost everyone"], "answer": 0, "explain": "The 1347–1352 plague killed an estimated 30–50% of Europe's population."}, {"q": "Why does the Magna Carta matter today?", "choices": ["It planted the idea that rulers are bound by law", "It ended all wars", "It created parliament overnight"], "answer": 0, "explain": "Its principle — no one, not even a king, is above the law — echoes in constitutions worldwide."}, {"q": "Which statement about the 'Dark Ages' is most accurate?", "choices": ["Europe struggled while other regions advanced in science and culture", "Nothing happened anywhere for 1,000 years", "Everyone was illiterate"], "answer": 0, "explain": "The Islamic world and Song China made huge advances while Europe was fragmented."}]}}, {"id": "history-3", "title": "Modern era", "cards": [{"type": "text", "title": "The world gets bigger: 1500s", "body": "The Renaissance revived art and learning in Europe, then ships changed everything. Columbus reached the Americas in 1492, Magellan's crew circled the globe by 1522. The printing press (1440s) spread ideas faster than ever — the first information revolution."}, {"type": "text", "title": "Steam, steel, and world wars", "body": "Around 1760 the Industrial Revolution mechanized production: factories, railways, cities swelling with workers. The 20th century then brought two world wars (1914–18, 1939–45), the deadliest conflicts in history, followed by the Cold War standoff and decolonization across Africa and Asia."}, {"type": "tip", "body": "Don't memorize every date — learn the hinges. 1492 (Americas), 1760s (industrialization), 1914 (WWI), 1945 (WWII ends, UN founded), 1969 (Moon landing). Five pegs hold the whole modern timeline."}, {"type": "example", "body": "Apollo 11, July 1969: Neil Armstrong steps onto the Moon, 66 years after the Wright brothers' first flight. One human lifetime spanned from barely leaving the ground to standing on another world — the modern era compresses change like nothing before it."}, {"type": "check", "q": "Why is 1969 a hinge date?", "choices": ["Humans first walked on the Moon", "World War II ended", "The printing press was invented"], "answer": 0, "explain": "Apollo 11's landing capped a century of accelerating technology."}], "flashcards": [{"type": "flash", "front": "What year did Columbus reach the Americas?", "back": "1492."}, {"type": "flash", "front": "When did the Industrial Revolution begin?", "back": "Around 1760, in Britain."}, {"type": "flash", "front": "What years were the two world wars?", "back": "WWI: 1914–1918. WWII: 1939–1945."}, {"type": "flash", "front": "What happened in 1969?", "back": "Apollo 11 — humans first walked on the Moon."}], "checkpoint": {"pass": 70, "questions": [{"q": "What made the printing press revolutionary?", "choices": ["Ideas spread faster than ever before", "It printed money", "It replaced all handwriting instantly"], "answer": 0, "explain": "Gutenberg's press (1440s) made books cheap and plentiful — the first information revolution."}, {"q": "What drove the Industrial Revolution?", "choices": ["Mechanized production: factories, steam, railways", "A sudden interest in farming", "The discovery of electricity alone"], "answer": 0, "explain": "Machines replaced hand labor starting ~1760, reshaping work, cities, and daily life."}, {"q": "Which came first: WWI or the Moon landing?", "choices": ["WWI, by about 55 years", "The Moon landing", "They happened the same decade"], "answer": 0, "explain": "WWI was 1914–18; Apollo 11 landed in 1969."}, {"q": "What followed World War II geopolitically?", "choices": ["Cold War standoff and decolonization", "Immediate world peace", "The Roman Empire's return"], "answer": 0, "explain": "The US–Soviet rivalry froze global politics while empires dissolved across Africa and Asia."}, {"q": "Why is the Wright-to-Apollo span (1903–1969) significant?", "choices": ["It shows how fast modern technology compounds", "Flight was actually invented in 1969", "Nothing changed in between"], "answer": 0, "explain": "Sixty-six years from first powered flight to the Moon — the modern era's signature is accelerating change."}]}}]}, {"color": "#FFE600", "icon": "bolt", "id": "js", "levels": [{"cards": [{"body": "A variable is a labeled box that holds a value so you can use it later. let score = 0; creates a box named score, puts 0 inside it, and now you can read or change it anywhere in your code.", "title": "Variables are labeled boxes", "type": "text"}, {"body": "Use let when the value will change (a game score). Use const when it won't (a birth year, a tax rate). Make const your default and reach for let only when you need change — your future self will thank you.", "title": "let vs const", "type": "text"}, {"body": "let playerName = \"Zoe\";\nconst maxLives = 3;\nlet lives = maxLives;\n\nA changeable name, an unchangeable limit, and a counter that starts at the limit. Three lines, real program.", "type": "example"}, {"body": "Good names tell a story: score, playerName, isLoggedIn. Bad names hide it: x, data2, thing. You spend more time reading code than writing it, so name like a storyteller.", "type": "tip"}, {"answer": 0, "choices": ["Creates a variable named age holding 20", "Deletes a variable called age", "Checks whether age equals 20"], "explain": "let declares the variable, age names it, = 20 stores the value. (Checking equality would be age === 20, with three equals signs.)", "q": "What does let age = 20; do?", "type": "check"}], "checkpoint": {"pass": 70, "questions": [{"answer": 0, "choices": ["Store a value under a name for later use", "Run a block of code on demand", "Describe how a page looks"], "explain": "Variables are storage. Running code is functions; page styling is CSS.", "q": "Why do you create a variable?"}, {"answer": 0, "choices": ["Its value can never be reassigned", "It must be a number", "It works only inside loops"], "explain": "const locks the binding: one assignment, forever. (The value itself can still be a changeable object, but that's level 4 material.)", "q": "What is true about const total = 50;?"}, {"answer": 0, "choices": ["score", "2score", "my score"], "explain": "Names can use letters, digits, _ and $, but can't start with a digit or contain spaces.", "q": "Which is a legal variable name?"}, {"answer": 0, "choices": ["\"hello\"", "42", "true"], "explain": "Quotes make it a string. 42 is a number, true is a boolean.", "q": "Which of these values is a string?"}, {"answer": 0, "choices": ["let lives = 3; lives = 2;", "const lives = 3; lives = 2;", "let 3 = lives;"], "explain": "let allows reassignment, so lives can drop to 2. const would throw an error, and you can't assign to a number.", "q": "A player loses a life. Which code works?"}]}, "flashcards": [{"back": "A named container that stores a value so your code can use it later.", "front": "What is a variable?", "type": "flash"}, {"back": "let allows reassignment, const does not. Default to const.", "front": "What's the difference between let and const?", "type": "flash"}, {"back": "Letters, digits, _ and $. It can't start with a digit and can't contain spaces.", "front": "What characters can a variable name use?", "type": "flash"}, {"back": "Reassigning means giving an existing variable a new value, like score = 10; after let score = 0;", "front": "What does reassigning a variable mean?", "type": "flash"}], "id": "js-1", "title": "Variables"}, {"cards": [{"body": "A function is a reusable recipe: a named block of code you can run whenever you want. Instead of copying the same steps everywhere, you write them once and call the function by name.", "title": "Functions are reusable recipes", "type": "text"}, {"body": "function greet() { ... } declares the function — it just defines the recipe, nothing runs yet. greet(); calls it. The parentheses are the go button; without them, nothing happens.", "title": "Declare it, then call it", "type": "text"}, {"body": "function add(a, b) {\n  return a + b;\n}\n\nadd(2, 3); // 5\n\nadd takes two inputs, hands back their sum. Call it with any numbers and it just works.", "type": "example"}, {"body": "Parameters (a, b) are the inputs a function expects. return is the output it hands back — and it stops the function cold. No return statement? The caller gets undefined.", "type": "tip"}, {"answer": 0, "choices": ["Runs add with 2 and 3, giving back 5", "Creates a variable called add", "Compares 2 and 3"], "explain": "The parentheses call the function, 2 and 3 are the arguments, and return sends 5 back to the caller.", "q": "What does add(2, 3) do?", "type": "check"}], "checkpoint": {"pass": 70, "questions": [{"answer": 0, "choices": ["To reuse a block of code by name", "To store a single value", "To style a webpage"], "explain": "Functions package behavior for reuse. Storage is variables; styling is CSS.", "q": "Why write a function instead of repeating code?"}, {"answer": 0, "choices": ["bake();", "bake;", "call bake;"], "explain": "Parentheses execute the function. Without them you're just mentioning its name.", "q": "How do you run a function named bake?"}, {"answer": 0, "choices": ["Values passed in when calling", "Values sent back with return", "Variables declared inside"], "explain": "In add(2, 3), the 2 and 3 are arguments. Parameters are the matching names (a, b) in the definition.", "q": "What are arguments?"}, {"answer": 0, "choices": ["Sends a value back and stops the function", "Prints the value to the screen", "Saves the value for later"], "explain": "return hands a value to the caller and exits immediately. Printing is console.log's job.", "q": "What does return do inside a function?"}, {"answer": 0, "choices": ["undefined", "0", "An error"], "explain": "A function without return finishes and quietly hands back undefined.", "q": "function hi() { } — what does hi() give back?"}]}, "flashcards": [{"back": "Write function name() { ... } to declare it, then name(); to run it.", "front": "How do you declare and call a function?", "type": "flash"}, {"back": "The named inputs in a function's definition, like (a, b) in function add(a, b).", "front": "What are parameters?", "type": "flash"}, {"back": "It sends a value back to the caller and immediately stops the function.", "front": "What does return do?", "type": "flash"}, {"back": "The actual values passed at call time — 2 and 3 in add(2, 3).", "front": "What's the difference between a parameter and an argument?", "type": "flash"}], "id": "js-2", "title": "Functions"}, {"cards": [{"body": "An array is an ordered list inside one variable: let colors = [\"red\", \"green\", \"blue\"];. One name, many values, kept in the order you put them in.", "title": "Arrays are ordered lists", "type": "text"}, {"body": "Counting starts at zero. colors[0] is \"red\", colors[1] is \"green\", colors[2] is \"blue\". Nearly every off-by-one bug you'll ever meet lives right here — respect the zero.", "title": "Counting starts at zero", "type": "text"}, {"body": "let scores = [10, 20];\nscores.push(30);   // [10, 20, 30]\nscores.length;     // 3\n\npush sticks a value on the end; length tells you how many items there are. Two tools, endless uses.", "type": "example"}, {"body": "push() adds to the end, pop() removes from the end, and .length counts what's inside. If you only memorize three array tricks, make it these three.", "type": "tip"}, {"answer": 0, "choices": ["green", "red", "blue"], "explain": "Index 0 is red, so index 1 is green. The second item lives at position 1, not 2.", "q": "In [\"red\", \"green\", \"blue\"], what is at index 1?", "type": "check"}], "checkpoint": {"pass": 70, "questions": [{"answer": 0, "choices": ["let list = [1, 2, 3];", "let list = (1, 2, 3);", "let list = \"1, 2, 3\";"], "explain": "Square brackets build arrays. Parentheses group expressions; quotes make a string.", "q": "Which line correctly creates an array?"}, {"answer": 0, "choices": ["banana", "apple", "cherry"], "explain": "fruits[0] is apple, so fruits[1] is banana. Zero-based, always.", "q": "fruits = [\"apple\", \"banana\", \"cherry\"]. What is fruits[1]?"}, {"answer": 0, "choices": ["[1, 2, 3, 4]", "4", "It throws an error"], "explain": "push appends and returns the new length, but the array itself becomes [1, 2, 3, 4].", "q": "let a = [1, 2, 3]; a.push(4); What is a now?"}, {"answer": 0, "choices": ["3", "2", "0"], "explain": "length counts items: three strings in the array, so length is 3. (The last index is 2 — length and last index differ by one.)", "q": "What is [\"a\", \"b\", \"c\"].length?"}, {"answer": 0, "choices": ["undefined, because the index is out of range", "It throws an error", "The last item, as a guess"], "explain": "JavaScript doesn't crash on a bad index — it calmly hands you undefined. (Which is exactly why these bugs are sneaky.)", "q": "let a = [1, 2]; what is a[5]?"}]}, "flashcards": [{"back": "Square brackets with items separated by commas: let list = [1, 2, 3];", "front": "How do you create an array?", "type": "flash"}, {"back": "0. The first item is always at index 0.", "front": "What index holds the first item of an array?", "type": "flash"}, {"back": "It adds a value to the end of the array.", "front": "What does push() do?", "type": "flash"}, {"back": "The number of items in the array. (Not the last index — that's length minus one.)", "front": "What does .length tell you?", "type": "flash"}], "id": "js-3", "title": "Arrays"}], "title": "JavaScript"}, {"id": "math", "title": "Algebra", "icon": "calculator", "color": "#2B3A67", "levels": [{"id": "math-1", "title": "Variables & expressions", "cards": [{"type": "text", "title": "Letters that stand for numbers", "body": "A variable is a letter that stands for a number you don't know yet — usually x. An expression like 3x + 5 is a recipe: multiply x by 3, then add 5. The moment you learn x, you can compute the whole thing."}, {"type": "text", "title": "The parts have names", "body": "In 4x + 7, the 4 is the coefficient (it multiplies the variable), x is the variable, and 7 is the constant (it never changes). Knowing the names makes every later step easier to talk about."}, {"type": "tip", "body": "Like terms are twins: 3x and 5x can combine into 8x because the x matches. But 3x and 3x² are NOT like terms — different exponents, no combining. Match the letter AND the power."}, {"type": "example", "body": "Simplify 2x + 7 + 5x − 3: group the x's (2x + 5x = 7x) and the constants (7 − 3 = 4). Answer: 7x + 4. Two groups, two additions, done."}, {"type": "check", "q": "Which are like terms?", "choices": ["4x and 9x", "4x and 4x²", "4x and 4y"], "answer": 0, "explain": "Like terms need the same variable with the same exponent. Only 4x and 9x qualify."}], "flashcards": [{"type": "flash", "front": "What is a variable?", "back": "A letter (usually x) that stands for an unknown number."}, {"type": "flash", "front": "In 4x + 7, what is the coefficient?", "back": "4 — the number multiplying the variable."}, {"type": "flash", "front": "What are like terms?", "back": "Terms with the same variable raised to the same power, e.g. 3x and 5x."}, {"type": "flash", "front": "Simplify: 2x + 3 + 6x − 1", "back": "8x + 2 (combine 2x+6x and 3−1)."}], "checkpoint": {"pass": 70, "questions": [{"q": "What does the expression 5n − 2 mean in words?", "choices": ["Multiply n by 5, then subtract 2", "Add 5 and n, then subtract 2", "Multiply 5 by n minus 2, all times 5"], "answer": 0, "explain": "Read left to right following order of operations: 5n means 5 times n, then take away 2."}, {"q": "Simplify 7y + 2 − 3y + 8.", "choices": ["10y + 10", "4y + 10", "4y + 6"], "answer": 1, "explain": "Combine y's: 7y − 3y = 4y. Combine constants: 2 + 8 = 10."}, {"q": "Evaluate 2x + 5 when x = 3.", "choices": ["11", "16", "10"], "answer": 0, "explain": "Substitute: 2(3) + 5 = 6 + 5 = 11. Multiply before adding."}, {"q": "Why can't 4x² + 3x combine into one term?", "choices": ["Different coefficients", "Different exponents", "They actually can"], "answer": 1, "explain": "Like terms need matching variables AND exponents. x² and x are different powers."}, {"q": "A taxi charges $3 plus $2 per mile. Which expression gives the cost for m miles?", "choices": ["2m + 3", "3m + 2", "2(m + 3)"], "answer": 0, "explain": "The per-mile rate (2) multiplies the miles, then add the flat fee: 2m + 3."}]}}, {"id": "math-2", "title": "Solving equations", "cards": [{"type": "text", "title": "Undo to solve", "body": "An equation like x + 7 = 12 is a balanced scale. To find x, undo what's been done to it — using inverse operations. Addition undoes subtraction, multiplication undoes division. Whatever you do to one side, do to the other."}, {"type": "text", "title": "One step, then two", "body": "x + 5 = 11 → subtract 5 from both sides → x = 6. That's one step. For 2x + 3 = 11, undo in reverse order: subtract 3 first (2x = 8), then divide by 2 (x = 4). Peel the onion from the outside in."}, {"type": "tip", "body": "Always check your answer by plugging it back in. If x = 4, then 2(4) + 3 = 11. It balances — you're right. Thirty seconds of checking saves full marks."}, {"type": "example", "body": "Solve 3x − 8 = 10: add 8 to both sides → 3x = 18. Divide by 3 → x = 6. Check: 3(6) − 8 = 18 − 8 = 10. Balanced."}, {"type": "check", "q": "First step to solve x − 9 = 4?", "choices": ["Subtract 9 from both sides", "Add 9 to both sides", "Divide both sides by 9"], "answer": 1, "explain": "Undo the −9 with its inverse: add 9 to both sides, giving x = 13."}], "flashcards": [{"type": "flash", "front": "What is an inverse operation?", "back": "An operation that undoes another: addition/subtraction, multiplication/division."}, {"type": "flash", "front": "Solve: x + 9 = 20", "back": "x = 11 (subtract 9 from both sides)."}, {"type": "flash", "front": "Solve: 4x = 24", "back": "x = 6 (divide both sides by 4)."}, {"type": "flash", "front": "Why do both sides get the same operation?", "back": "An equation is a balanced scale — change one side only and it stops being equal."}], "checkpoint": {"pass": 70, "questions": [{"q": "Solve: x + 12 = 30.", "choices": ["x = 18", "x = 2.5", "x = 42"], "answer": 0, "explain": "Subtract 12 from both sides: 30 − 12 = 18."}, {"q": "Solve: 5x = 45.", "choices": ["x = 40", "x = 225", "x = 9"], "answer": 2, "explain": "Divide both sides by 5: 45 ÷ 5 = 9."}, {"q": "Solve: 2x + 6 = 20.", "choices": ["x = 13", "x = 7", "x = 4"], "answer": 1, "explain": "Subtract 6 → 2x = 14, then divide by 2 → x = 7."}, {"q": "Solve: x/3 − 2 = 5.", "choices": ["x = 9", "x = 21", "x = 1"], "answer": 1, "explain": "Add 2 → x/3 = 7, then multiply by 3 → x = 21."}, {"q": "Maya's answer is x = 5 for 3x + 1 = 16. How does she verify it?", "choices": ["Answers can't be verified", "Plug 5 back in: 3(5)+1 = 16", "Solve it a different way only"], "answer": 1, "explain": "Substitution is the gold standard: 3(5) + 1 = 16 balances, so x = 5 is correct."}]}}, {"id": "math-3", "title": "Graphing lines", "cards": [{"type": "text", "title": "The coordinate plane", "body": "Two number lines cross to make a grid: x runs left-right, y runs up-down. A point like (3, 2) means go 3 right, 2 up. The spot where they cross, (0, 0), is called the origin."}, {"type": "text", "title": "Slope: how steep?", "body": "Slope measures a line's steepness: rise over run. Go up 2 for every 3 right and the slope is 2/3. Positive slope climbs left-to-right; negative slope falls; zero slope is flat; undefined slope is vertical."}, {"type": "tip", "body": "y = mx + b is the cheat code: m is the slope, b is where the line crosses the y-axis. In y = 2x + 1, the line climbs 2 per step and crosses at (0, 1). Read a line without plotting a single point."}, {"type": "example", "body": "Graph y = −x + 4: it crosses the y-axis at 4 (b = 4) and falls 1 for every 1 right (m = −1). Plot (0, 4), then step down-right to (1, 3), (2, 2) — connect the dots."}, {"type": "check", "q": "In y = 3x − 2, what is the y-intercept?", "choices": ["2", "3", "−2"], "answer": 2, "explain": "The y-intercept is b, the constant term: −2. The line crosses the y-axis at (0, −2)."}], "flashcards": [{"type": "flash", "front": "What does the point (3, 2) mean?", "back": "Go 3 units right on x, then 2 units up on y."}, {"type": "flash", "front": "What is slope?", "back": "Rise over run — how steep a line is."}, {"type": "flash", "front": "In y = mx + b, what are m and b?", "back": "m is the slope; b is the y-intercept."}, {"type": "flash", "front": "What does a zero slope look like?", "back": "A flat horizontal line."}], "checkpoint": {"pass": 70, "questions": [{"q": "A line passes through (0, 5) and rises 2 for every 1 right. What's its equation?", "choices": ["y = 5x + 2", "y = x + 5", "y = 2x + 5"], "answer": 2, "explain": "Slope m = 2, y-intercept b = 5, so y = 2x + 5."}, {"q": "What is the slope of the line through (1, 2) and (4, 8)?", "choices": ["2", "1/2", "6"], "answer": 0, "explain": "Rise = 8 − 2 = 6, run = 4 − 1 = 3, slope = 6/3 = 2."}, {"q": "Which line is steeper: y = 4x + 1 or y = 2x + 9?", "choices": ["Same steepness", "y = 4x + 1", "y = 2x + 9"], "answer": 1, "explain": "Steepness comes from |m|. |4| > |2|, so the first line climbs faster."}, {"q": "The equation y = −3 describes which line?", "choices": ["Vertical line through x = −3", "A diagonal line", "Horizontal line through y = −3"], "answer": 2, "explain": "No x term means slope 0 — every point has y = −3, a flat horizontal line."}, {"q": "Two lines have the same slope but different intercepts. How do they relate?", "choices": ["Parallel — they never meet", "One is vertical", "They cross at the origin"], "answer": 0, "explain": "Same slope means same steepness; different intercepts mean they're offset — parallel lines."}]}}]}, {"id": "music", "title": "Music Theory", "icon": "music", "color": "#FF6B9D", "levels": [{"id": "music-1", "title": "Notes & rhythm", "cards": [{"type": "text", "title": "Meet the musical alphabet", "body": "Only seven letters: A, B, C, D, E, F, G — then they repeat. Middle C sits near the center of the piano, and every other note is measured from there. Seven letters run all of Western music."}, {"type": "text", "title": "Notes have length, not just pitch", "body": "A whole note holds for 4 beats, a half note for 2, a quarter note for 1, and an eighth note for half a beat. Rhythm is just pitch plus timing — the same note means different things depending on how long you hold it."}, {"type": "example", "body": "Play C D E F as quarter notes — one beat each — and you've played four even steps. Now play them as eighth notes (two per beat) and the same four notes feel twice as urgent. Same pitches, completely different energy."}, {"type": "tip", "body": "Count out loud until it clicks: say 1-2-3-4 under quarter notes, 1-and-2-and under eighth notes. Your mouth is the cheapest metronome ever made."}, {"type": "check", "q": "How many beats does a half note get?", "choices": ["2 beats", "4 beats", "1 beat"], "answer": 0, "explain": "Half of a whole (4 beats) is 2. Quarter = 1, half = 2, whole = 4 — the names are literally fractions of a whole note."}], "flashcards": [{"type": "flash", "front": "How many different note letters are there?", "back": "Seven: A, B, C, D, E, F, G. After G the alphabet wraps back to A, one octave higher."}, {"type": "flash", "front": "How long is a quarter note?", "back": "One beat. It's the default pulse — most music you hear counts in quarter notes."}, {"type": "flash", "front": "What does tempo mean?", "back": "The speed of the beat, measured in beats per minute (BPM). 120 BPM means two beats every second."}, {"type": "flash", "front": "What is an octave?", "back": "The distance from one note to the next note with the same letter — C to C, for example. It sounds like the 'same' note, higher."}], "checkpoint": {"pass": 70, "questions": [{"q": "After G, what comes next in the musical alphabet?", "choices": ["A", "H", "It ends at G"], "answer": 0, "explain": "The musical alphabet only uses A through G, then repeats. After G comes A, one octave up."}, {"q": "A whole note lasts 4 beats. How long is an eighth note?", "choices": ["Half a beat", "2 beats", "8 beats"], "answer": 0, "explain": "Eighth = 1/8 of a whole note = half a beat. Two eighth notes fit inside a single beat."}, {"q": "What does 100 BPM tell you?", "choices": ["100 beats happen every minute", "The song is 100 minutes long", "There are 100 notes total"], "answer": 0, "explain": "BPM = beats per minute. 100 BPM means a beat lands 100 times each minute — a relaxed walking pace."}, {"q": "Which lasts longer: a half note, or two quarter notes tied together?", "choices": ["They're exactly the same length", "The half note", "The two quarters"], "answer": 0, "explain": "Both total 2 beats. A tie just glues note lengths together — the math is identical."}, {"q": "Middle C is called 'middle' because…", "choices": ["It sits near the middle of the piano keyboard", "It's the middle of every song", "It's always played with the middle finger"], "answer": 0, "explain": "It's roughly at the center of a standard 88-key piano, and it works as the landmark other notes are measured from."}]}}, {"id": "music-2", "title": "Scales", "cards": [{"type": "text", "title": "A scale is a ladder of notes", "body": "A scale is a set of notes in ascending order, defined by the pattern of steps between them. Learn one pattern and you can build that scale starting from any note on the keyboard."}, {"type": "text", "title": "Whole steps and half steps", "body": "The smallest step on a piano is a half step — one key to its immediate neighbor, black or white. Two half steps make a whole step. Every scale is just a recipe of wholes and halves."}, {"type": "example", "body": "C major = all white keys: C D E F G A B C. The pattern is W-W-H-W-W-W-H. No sharps, no flats — that's why C major is where everyone starts."}, {"type": "tip", "body": "Sharps (#) raise a note one half step; flats (b) lower it one half step. The same piano key can have two names — C# and Db are the same pitch. Musicians call that an enharmonic."}, {"type": "check", "q": "The major pattern is W-W-H-W-W-W-H. Starting on G, what's the 7th note?", "choices": ["F#", "F", "G#"], "answer": 0, "explain": "Count it out: G(1) A(2) B(3) C(4) D(5) E(6) F#(7). The half step between E and F# forces the sharp — that's why G major has one sharp."}], "flashcards": [{"type": "flash", "front": "What is a scale?", "back": "An ordered set of notes built from a fixed pattern of whole and half steps."}, {"type": "flash", "front": "What is the major scale pattern?", "back": "W-W-H-W-W-W-H: whole, whole, half, whole, whole, whole, half."}, {"type": "flash", "front": "What does a sharp do?", "back": "Raises a note by one half step. A flat lowers it by one half step."}, {"type": "flash", "front": "How many sharps does C major have?", "back": "None. C major uses only white keys — the only major scale with no sharps or flats."}], "checkpoint": {"pass": 70, "questions": [{"q": "What is a half step?", "choices": ["One piano key to its immediate neighbor", "Skipping one key", "Two whole notes"], "answer": 0, "explain": "One key to its immediate neighbor — black or white — is a half step. It's the smallest interval in Western music."}, {"q": "In C D E F G A B C, where do the half steps fall?", "choices": ["Between E–F and B–C", "Between C–D and G–A", "There are no half steps"], "answer": 0, "explain": "Those pairs have no black key between them on the piano — that's exactly where the H steps of W-W-H-W-W-W-H land."}, {"q": "A minor scale sounds…", "choices": ["Darker than major", "Exactly like major", "Louder than major"], "answer": 0, "explain": "Same twelve notes, different pattern — the flattened 3rd gives minor its darker color. Happy vs. sad is the quickest way to hear the difference."}, {"q": "C# and Db are…", "choices": ["The same pitch with two names", "Two different pitches", "A major and minor pair"], "answer": 0, "explain": "One piano key, two spellings — an enharmonic. Which name you use depends on the key you're playing in."}, {"q": "How many distinct notes in a major scale (not counting the repeated top note)?", "choices": ["7", "8", "12"], "answer": 0, "explain": "Seven distinct notes, then the octave repeats the starting note — C D E F G A B, then C again."}]}}, {"id": "music-3", "title": "Chords", "cards": [{"type": "text", "title": "Chords are note stacks", "body": "Play three or more notes at once and you get a chord. The most common stack — the triad — is built from the 1st, 3rd, and 5th notes of a scale. Stack every other note and harmony appears."}, {"type": "text", "title": "Major vs. minor: it's the middle note", "body": "A major triad has a wide (major) 3rd; a minor triad has a narrow (minor) 3rd. C–E–G sounds bright; C–Eb–G sounds moody. One note moved a half step changes the entire feeling."}, {"type": "example", "body": "Build C major in 3 steps: 1) Take the C major scale: C D E F G A B. 2) Grab the 1st (C), 3rd (E), and 5th (G). 3) Play them together — that's a C major chord."}, {"type": "tip", "body": "Roman numerals name chords by position: I, IV, V. Thousands of pop songs are just I–V–vi–IV on repeat. Learn those four shapes and you can fake your way through most radio hits."}, {"type": "check", "q": "C minor is C–Eb–G. What changed from C major (C–E–G)?", "choices": ["The 3rd dropped a half step", "The 5th dropped a half step", "The root changed"], "answer": 0, "explain": "E to Eb is one half step down. That flattened 3rd is the entire difference between major and minor triads."}], "flashcards": [{"type": "flash", "front": "What notes make a triad?", "back": "The 1st, 3rd, and 5th notes of a scale, played together."}, {"type": "flash", "front": "What makes a chord minor instead of major?", "back": "The 3rd is lowered one half step — a minor 3rd instead of a major 3rd."}, {"type": "flash", "front": "What is a I–IV–V progression in C major?", "back": "The C, F, and G chords — the 1st, 4th, and 5th chords of the scale. The backbone of blues and rock."}, {"type": "flash", "front": "How many notes minimum for a chord?", "back": "Three. Two notes played together is just an interval."}], "checkpoint": {"pass": 70, "questions": [{"q": "Which scale degrees form a basic triad?", "choices": ["1st, 3rd, 5th", "1st, 2nd, 3rd", "1st, 4th, 5th"], "answer": 0, "explain": "Root, third, fifth — stack every other note and you get the triad. That's the recipe for every basic chord."}, {"q": "G–B–D is what kind of chord?", "choices": ["G major", "G minor", "G seventh"], "answer": 0, "explain": "G to B is a major 3rd (two whole steps) and G to D is a perfect 5th — the major triad recipe."}, {"q": "You flatten the 3rd of a major chord. What do you get?", "choices": ["A minor chord", "A bigger major chord", "A broken chord"], "answer": 0, "explain": "Lowering the 3rd by a half step converts major to minor. Same root, same 5th — new mood."}, {"q": "In I–V–vi–IV in C major, what is the vi chord?", "choices": ["A minor", "A major", "F major"], "answer": 0, "explain": "The 6th note of C major is A, and the vi chord is minor by default. I–V–vi–IV = C–G–Am–F."}, {"q": "Why do songwriters love the I–IV–V progression?", "choices": ["It creates tension and release that feels satisfying", "It's the only legal progression", "It uses no sharps"], "answer": 0, "explain": "The V chord pulls hard back to I — that tension-and-release is the engine of countless songs, from blues to pop-punk."}]}}]}, {"id": "nutrition", "title": "Nutrition", "icon": "apple", "color": "#58D68D", "levels": [{"id": "nutrition-1", "title": "Macros", "cards": [{"type": "text", "title": "The big three", "body": "Every food you eat is mostly some mix of three macronutrients: protein, carbohydrates, and fat. They each do different jobs, and your body needs all three. No single macro is the villain — balance is the whole game."}, {"type": "text", "title": "Protein: the builder", "body": "Protein repairs muscle, skin, hair, and nails, and it keeps you full longer than carbs. Aim for a palm-sized portion at each meal: chicken, fish, eggs, beans, lentils, tofu, Greek yogurt. Most adults do well around 1.2 to 2 grams per kilo of body weight daily."}, {"type": "text", "title": "Carbs: the fuel", "body": "Carbohydrates are your body's preferred energy source, especially for your brain. Whole versions — oats, rice, potatoes, fruit — come with fiber that slows digestion and steadies energy. Refined ones — soda, candy — spike and crash you."}, {"type": "text", "title": "Fat: not the enemy", "body": "Fat helps you absorb vitamins A, D, E, and K, protects organs, and makes food satisfying. Favor unsaturated sources: olive oil, nuts, avocado, fatty fish. Trans fats (partially hydrogenated oils) are the ones worth avoiding."}, {"type": "tip", "body": "The hand method, no scale needed: a palm of protein, a fist of vegetables, a cupped hand of carbs, a thumb of fats. It's rough, it's portable, and it beats guessing."}, {"type": "check", "q": "Which macro is mainly responsible for building and repairing muscle?", "choices": ["Protein", "Carbohydrates", "Fat"], "answer": 0, "explain": "Protein supplies the amino acids your body uses to build and repair tissue. Carbs fuel you and fats support hormones and vitamins, but building is protein's job."}], "flashcards": [{"type": "flash", "front": "What are the three macronutrients?", "back": "Protein, carbohydrates, and fat."}, {"type": "flash", "front": "Which macro keeps you fullest the longest?", "back": "Protein — it digests slowly and steadies hunger."}, {"type": "flash", "front": "Name a whole-carb and a refined-carb example.", "back": "Whole: oats or brown rice. Refined: soda or candy."}, {"type": "flash", "front": "Which fats are worth favoring?", "back": "Unsaturated: olive oil, nuts, avocado, fatty fish. Avoid trans fats."}], "checkpoint": {"pass": 70, "questions": [{"q": "Why does protein keep you full longer than carbs?", "choices": ["It digests more slowly", "It has zero calories", "It turns directly into muscle"], "answer": 0, "explain": "Protein's slow digestion and hormonal effects on satiety outlast quick-burning carbs."}, {"q": "Your brain's preferred fuel is...", "choices": ["Carbohydrates", "Protein", "Water"], "answer": 0, "explain": "The brain runs primarily on glucose from carbs. It can adapt to alternatives, but carbs are its first choice."}, {"q": "Which fat source is the best pick?", "choices": ["Olive oil", "Partially hydrogenated shortening", "Margarine sticks from the 90s"], "answer": 0, "explain": "Olive oil is rich in unsaturated fats. Partially hydrogenated oils contain trans fats linked to heart disease."}, {"q": "Using the hand method, a serving of vegetables is...", "choices": ["A fist", "A thumb", "A palm"], "answer": 0, "explain": "Fist of veg, palm of protein, cupped hand of carbs, thumb of fats — the whole system fits in your hands."}, {"q": "Refined carbs differ from whole carbs mainly in...", "choices": ["Fiber content and how fast they digest", "Color", "Price"], "answer": 0, "explain": "Refining strips fiber, so the carbs hit your bloodstream fast — spike, crash, hunger again."}]}}, {"id": "nutrition-2", "title": "Reading labels", "cards": [{"type": "text", "title": "The serving-size trap", "body": "The first thing on any label is the serving size — and it's often smaller than what you'd actually eat. A '200-calorie' snack pack with 2.5 servings is really 500 calories. Always multiply before you judge."}, {"type": "text", "title": "Sugar's many aliases", "body": "Ingredients list anything ending in -ose (fructose, dextrose), plus syrup, nectar, cane juice, and maltodextrin — all sugar wearing costumes. If three of the first five ingredients are sweeteners by different names, it's dessert."}, {"type": "text", "title": "% Daily Value, decoded", "body": "The %DV column tells you how much of a nutrient one serving provides against a 2,000-calorie day. Rule of thumb: 5% or less is low, 20% or more is high. Useful for spotting sodium and fiber at a glance."}, {"type": "tip", "body": "Ingredients are listed by weight, heaviest first. If sugar (by any name) is in the top three, the product is mostly sugar — no matter what the front of the box promises."}, {"type": "example", "body": "Compare two yogurts: Cup A lists 'strawberry, milk, sugar' with 12g sugar per 100g. Cup B lists 'milk, sugar, glucose syrup, strawberry flavor' with 18g sugar. Same front-of-box claims, very different insides. The label never lies; marketing does."}, {"type": "check", "q": "What's the first thing you should check on a nutrition label?", "choices": ["The serving size", "The brand name", "The prettiest number"], "answer": 0, "explain": "Every other number on the label is per serving. If the serving is unrealistically small, all the numbers mislead you until you multiply."}], "flashcards": [{"type": "flash", "front": "Why does serving size matter most?", "back": "All label numbers are per serving — multiply by what you'll actually eat."}, {"type": "flash", "front": "Name three hidden names for sugar.", "back": "Any three of: fructose, dextrose, syrup, nectar, cane juice, maltodextrin, anything ending in -ose."}, {"type": "flash", "front": "What does 20% DV mean?", "back": "One serving gives 20% of that nutrient for a 2,000-calorie day — that's high."}, {"type": "flash", "front": "How are ingredients ordered on a label?", "back": "By weight, heaviest first."}], "checkpoint": {"pass": 70, "questions": [{"q": "A bag says 150 calories, 3 servings per bag. You eat the whole bag. Calories?", "choices": ["450", "150", "300"], "answer": 0, "explain": "150 × 3 servings = 450. The front number is per serving, not per package."}, {"q": "'Evaporated cane juice' on an ingredient list is...", "choices": ["Sugar", "A vegetable", "A preservative"], "answer": 0, "explain": "It's sugar with a health-food costume. The -ose family and syrups are all added sugars."}, {"q": "A soup has 25% DV sodium per serving. That means...", "choices": ["It's high in sodium", "It's low in sodium", "Nothing — DV is meaningless"], "answer": 0, "explain": "20%+ DV is the 'high' threshold. One serving already covers a quarter of the day's sodium."}, {"q": "Sugar is the second ingredient listed. That tells you...", "choices": ["It's one of the heaviest ingredients by weight", "It's the second healthiest", "Nothing about quantity"], "answer": 0, "explain": "Ingredients descend by weight, so #2 means there's a lot of it in there."}, {"q": "Best quick check for fiber on a label?", "choices": ["%DV — 20%+ is high", "The brand's health claims", "The color of the box"], "answer": 0, "explain": "%DV gives you the fact; front-of-box claims give you the marketing."}]}}, {"id": "nutrition-3", "title": "Meal planning", "cards": [{"type": "text", "title": "The plate method", "body": "Forget counting: fill half your plate with vegetables, a quarter with protein, and a quarter with carbs. Add a thumb of healthy fats. It auto-balances macros without an app, a scale, or a spreadsheet."}, {"type": "text", "title": "Prep beats willpower", "body": "Decide once, eat well all week: cook a big batch of grains, roast a tray of vegetables, and prep two proteins on Sunday. Weeknight you becomes an assembler, not a chef. Hungry brains make bad food decisions; prepped food removes the decision."}, {"type": "tip", "body": "Shop the perimeter of the grocery store: produce, meat, dairy, bakery. The middle aisles are where the ultra-processed stuff lives. You don't have to avoid them entirely — just start outside and work in."}, {"type": "example", "body": "A sample day on the plate method: breakfast — Greek yogurt, berries, oats, handful of nuts. Lunch — big salad, grilled chicken, olive oil, a roll. Dinner — salmon, roasted broccoli, sweet potato. Snacks — apple, handful of almonds. Nothing counted, everything balanced."}, {"type": "text", "title": "The 80/20 reality", "body": "Eat well 80% of the time and the other 20% genuinely doesn't matter. The all-or-nothing mindset is what kills diets — one pizza doesn't ruin anything, but 'I already failed' thinking ruins everything."}, {"type": "check", "q": "On the plate method, how much of the plate is vegetables?", "choices": ["Half", "A quarter", "None — vegetables are optional"], "answer": 0, "explain": "Half the plate is vegetables. That single rule crowds out the less nutritious stuff without any counting."}], "flashcards": [{"type": "flash", "front": "What is the plate method?", "back": "Half veg, quarter protein, quarter carbs, plus a thumb of healthy fats."}, {"type": "flash", "front": "Why does meal prep work?", "back": "It removes decisions when you're hungry — you assemble instead of improvising."}, {"type": "flash", "front": "Where should you start grocery shopping?", "back": "The perimeter: produce, meat, dairy, bakery."}, {"type": "flash", "front": "What is the 80/20 rule of eating?", "back": "Eat well 80% of the time; the other 20% doesn't matter. Consistency beats perfection."}], "checkpoint": {"pass": 70, "questions": [{"q": "Why does the plate method work without counting calories?", "choices": ["Vegetables crowd out calorie-dense food automatically", "Vegetables have zero calories", "Counting is illegal"], "answer": 0, "explain": "Half a plate of veg physically limits room for denser foods while adding fiber and volume."}, {"q": "Biggest benefit of Sunday meal prep?", "choices": ["Fewer decisions when hungry", "It makes food taste better", "It saves refrigerator space"], "answer": 0, "explain": "Decision fatigue is the enemy. Prepped components turn weeknight cooking into assembly."}, {"q": "Someone eats perfectly all week then has pizza Friday. Verdict?", "choices": ["Totally fine — that's the 20%", "Diet ruined, start over Monday", "They must skip Saturday meals"], "answer": 0, "explain": "80/20 means one indulgent meal is part of the plan, not a failure. The all-or-nothing spiral is the real diet killer."}, {"q": "Best first step for a beginner meal planner?", "choices": ["Cook grains + roast veg + prep two proteins weekly", "Buy every supplement advertised", "Throw out all snacks immediately"], "answer": 0, "explain": "Three batch-cooked components cover most meals. Supplements and purges are distractions."}, {"q": "Shopping the perimeter helps because...", "choices": ["Whole foods live there; ultra-processed fills the middle aisles", "The lighting is better", "It's faster"], "answer": 0, "explain": "Produce, meat, dairy, and bakery ring the store. The center aisles are engineered snack territory."}]}}]}, {"id": "photo", "title": "Photography", "icon": "camera", "color": "#5D6D7E", "levels": [{"id": "photo-1", "title": "Composition", "cards": [{"type": "text", "title": "The rule of thirds", "body": "Imagine your frame split into a 3×3 grid. Place key subjects along the lines or at their intersections instead of dead center. Off-center instantly feels more dynamic and intentional."}, {"type": "text", "title": "Leading lines pull the eye", "body": "Roads, fences, rivers, shadows — any line that guides the viewer toward your subject adds depth and direction. Find a line in the scene, then put your subject where it ends."}, {"type": "example", "body": "A lone tree centered in the frame: fine, forgettable. The same tree on a third-line intersection, with a dirt road leading to it: suddenly it's a photograph. Nothing changed except placement."}, {"type": "tip", "body": "Turn on your camera's grid overlay — every phone has it in settings. Compose with the grid for a week and the thirds become instinct. Then you can break the rule on purpose."}, {"type": "check", "q": "Where should the subject go under the rule of thirds?", "choices": ["Along the grid lines or intersections", "Always dead center", "In the extreme corner"], "answer": 0, "explain": "The four intersection points are the power positions. Centering works for symmetry, but thirds create tension and balance."}], "flashcards": [{"type": "flash", "front": "What is the rule of thirds?", "back": "Divide the frame into a 3×3 grid; place subjects on the lines or intersections, not centered."}, {"type": "flash", "front": "What are leading lines?", "back": "Lines in the scene — roads, rails, shores — that guide the viewer's eye toward the subject."}, {"type": "flash", "front": "What is negative space?", "back": "Empty areas around the subject that give it room to breathe and add drama."}, {"type": "flash", "front": "Why shoot from a different angle?", "back": "Eye level is how everyone sees the world. Crouching low or climbing high makes ordinary subjects look extraordinary."}], "checkpoint": {"pass": 70, "questions": [{"q": "Your horizon sits dead center and the shot feels flat. Fix?", "choices": ["Move it to the upper or lower third", "Add more sky", "Zoom in tighter"], "answer": 0, "explain": "A centered horizon splits the image in two and kills energy. Give two-thirds of the frame to whichever half is more interesting."}, {"q": "What's the fastest way to add depth?", "choices": ["Include a foreground element or leading line", "Buy a longer lens", "Shoot only at noon"], "answer": 0, "explain": "Layers — foreground, subject, background — create depth no gear can fake. A branch in the corner beats a new lens."}, {"q": "Negative space is useful because…", "choices": ["It isolates the subject and adds mood", "It wastes frame space", "Cameras require it"], "answer": 0, "explain": "Emptiness is a compositional tool. A tiny subject in vast sky feels lonely; the same subject crammed edge-to-edge feels chaotic."}, {"q": "A fence runs diagonally toward a barn. The fence is a…", "choices": ["Leading line", "Distraction to clone out", "Rule-of-thirds violation"], "answer": 0, "explain": "Diagonal lines are the strongest guides — they pull the eye straight to wherever they converge."}, {"q": "When is centering the subject the right call?", "choices": ["For symmetry — reflections, architecture", "Never, it's always wrong", "Only for selfies"], "answer": 0, "explain": "Rules serve the photo, not the reverse. Perfect symmetry — a reflection, a doorway — begs to be centered."}]}}, {"id": "photo-2", "title": "Light", "cards": [{"type": "text", "title": "Golden hour is cheat mode", "body": "The hour after sunrise and before sunset gives warm, soft, directional light. Long shadows, glowing skin tones, dramatic skies — the same scene looks expensive, for free."}, {"type": "text", "title": "Midday sun is harsh", "body": "Overhead light at noon carves hard shadows and makes people squint. If you must shoot midday, find open shade — building shadows, big trees — for soft, even light."}, {"type": "example", "body": "Same portrait, two times of day. Noon: raccoon-eye shadows under the brows. 6pm golden hour: warm glow, soft shadows, catchlights in the eyes. The camera didn't change — the sun's angle did."}, {"type": "tip", "body": "Backlight on purpose: put the sun behind your subject for a glowing rim around hair and shoulders. Tap your phone screen on their face so the camera exposes for them, not the sky."}, {"type": "check", "q": "It's noon, harsh sun, no choice. Best move?", "choices": ["Move the subject into open shade", "Shoot directly into the sun", "Use the flash on full blast"], "answer": 0, "explain": "Open shade turns the whole sky into a giant softbox — even, flattering light with no hard shadows."}], "flashcards": [{"type": "flash", "front": "When is golden hour?", "back": "Roughly the first hour after sunrise and the last hour before sunset — warm, soft, low-angled light."}, {"type": "flash", "front": "Why avoid midday sun for portraits?", "back": "Overhead light carves harsh shadows under eyes and noses, and makes people squint."}, {"type": "flash", "front": "What is backlighting?", "back": "Light coming from behind the subject, creating a glowing rim — expose for the subject's face."}, {"type": "flash", "front": "What does 'soft light' mean?", "back": "Diffused light with gentle shadow transitions — from shade, clouds, or large nearby surfaces."}], "checkpoint": {"pass": 70, "questions": [{"q": "You want dreamy warm portraits. When do you shoot?", "choices": ["Golden hour", "High noon", "Midnight"], "answer": 0, "explain": "Low sun means warm color, soft shadows, and flattering direction. It's the most forgiving light that exists."}, {"q": "Clouds roll in and the light goes flat and soft. This is…", "choices": ["Great for even, shadowless light", "A ruined shoot", "Only good for black and white"], "answer": 0, "explain": "Overcast skies are nature's softbox. Colors get richer, shadows vanish — ideal for flowers, faces, and details."}, {"q": "Your subject's face is dark against a bright sunset. Fix?", "choices": ["Tap to expose for the face, or add fill light", "Give up and shoot the sunset alone", "Turn the subject around"], "answer": 0, "explain": "Expose for what matters. Tapping the face tells the camera to prioritize it; a reflector or fill flash lifts the shadows."}, {"q": "Side light is prized because it…", "choices": ["Reveals texture and shape through shadows", "Eliminates all shadows", "Only works indoors"], "answer": 0, "explain": "Light raking across a surface shows every ripple and grain. Front light flattens; side light sculpts."}, {"q": "Blue hour is…", "choices": ["The twilight after sunset with deep blue skies", "A camera white-balance error", "The hour when flash is mandatory"], "answer": 0, "explain": "Those 20–30 minutes after sunset: the sky goes cobalt, city lights pop on — prime time for skylines."}]}}, {"id": "photo-3", "title": "Camera settings", "cards": [{"type": "text", "title": "The exposure triangle", "body": "Three settings control brightness: aperture (the lens opening), shutter speed (how long it stays open), and ISO (sensor sensitivity). Change one and the others must compensate — it's a three-way seesaw."}, {"type": "text", "title": "Aperture = depth of field", "body": "Small f-number (f/1.8) means a wide opening and blurry backgrounds — perfect for portraits. Big f-number (f/11) means a narrow opening and everything sharp — what landscapes want. The numbers feel backwards until they click."}, {"type": "example", "body": "Portrait at f/1.8: the subject's eyes are razor sharp, the background melted into creamy blur. Same scene at f/11: the fence three meters back is sharp too. One dial, two completely different photos."}, {"type": "tip", "body": "Shutter speed freezes or blurs motion: 1/500s freezes a runner, 1/30s turns a waterfall to silk. Rule of thumb: stay faster than 1/60s handheld, or your own shake blurs everything."}, {"type": "check", "q": "You want a blurry background behind your subject. Which aperture?", "choices": ["f/1.8", "f/11", "f/16"], "answer": 0, "explain": "Small f-number = wide aperture = shallow depth of field. f/1.8 melts backgrounds; f/11 and f/16 keep nearly everything sharp."}], "flashcards": [{"type": "flash", "front": "What are the three exposure settings?", "back": "Aperture (lens opening), shutter speed (time open), ISO (sensor sensitivity)."}, {"type": "flash", "front": "What does a small f-number like f/1.8 do?", "back": "Opens the aperture wide: more light, shallow depth of field, blurry backgrounds."}, {"type": "flash", "front": "What shutter speed freezes action?", "back": "Fast ones — 1/500s or quicker. Slow speeds like 1/30s blur motion instead."}, {"type": "flash", "front": "What is ISO noise?", "back": "Grainy speckles that appear at high ISO. Raise ISO only when you need the brightness."}], "checkpoint": {"pass": 70, "questions": [{"q": "Your landscape has a soft foreground and background. Fix?", "choices": ["Use a smaller aperture like f/11", "Use f/1.8", "Raise ISO to max"], "answer": 0, "explain": "A narrow aperture (big f-number) deepens the sharp zone from near to far — exactly what landscapes want."}, {"q": "Indoor photo too dark at f/2.8, 1/60s, ISO 400. Brighten without blur?", "choices": ["Raise ISO and accept some noise", "Slow the shutter to 1 second handheld", "Close the aperture to f/8"], "answer": 0, "explain": "1/60s is already the handheld floor and f/2.8 is wide open — ISO is the only dial left. Noise beats a black or blurry frame."}, {"q": "What does ISO 3200 vs ISO 100 mean?", "choices": ["32x more sensitive, but much noisier", "32x sharper", "No practical difference"], "answer": 0, "explain": "Each ISO doubling is one stop more sensitivity. 100 to 3200 is five stops (32x) — bright in the dark, grainy everywhere."}, {"q": "You want silky waterfall blur. Settings?", "choices": ["Slow shutter (1/15s or slower) + tripod", "Fastest shutter + widest aperture", "Maximum ISO"], "answer": 0, "explain": "Long exposures smear motion into silk — but any handshake smears everything too, so the tripod is non-negotiable."}, {"q": "Aperture, shutter, and ISO are linked because…", "choices": ["They all control exposure — change one, compensate with another", "Cameras force you to use all three", "They're the same setting with three names"], "answer": 0, "explain": "It's a triangle: widen the aperture and you must quicken the shutter or drop ISO to hold the same brightness. Every exposure is a three-way trade."}]}}]}, {"id": "physics", "title": "Physics", "icon": "atom", "color": "#2EC4B6", "levels": [{"id": "physics-1", "title": "Motion", "cards": [{"type": "text", "title": "Speed is how fast, velocity is how fast where", "body": "Speed is distance over time: 100 meters in 10 seconds is 10 m/s. Velocity is speed with a direction attached: 10 m/s north. Two cars can share a speed but have opposite velocities, and physics treats them as completely different motions."}, {"type": "text", "title": "Acceleration is the real main character", "body": "Acceleration is change in velocity over time. Speeding up, slowing down, and turning all count, because turning changes direction. A car cruising at steady 60 km/h in a straight line has zero acceleration; the moment it turns, it is accelerating."}, {"type": "tip", "body": "Units are the cheat code. Meters per second (m/s) for speed, meters per second squared (m/s²) for acceleration. If your answer's units are wrong, the number is wrong — checking units catches most mistakes before they happen."}, {"type": "example", "body": "A cyclist covers 300 meters in 25 seconds.\nSpeed = distance ÷ time = 300 ÷ 25 = 12 m/s.\n\nThat's about 43 km/h — fast for a bike, which is exactly why the number is worth a second look. Sanity-checking answers against the real world is a physics superpower."}, {"type": "check", "q": "A car drives 60 km/h north, then 60 km/h south. What changed?", "choices": ["Its velocity, not its speed", "Its speed, not its velocity", "Nothing at all"], "answer": 0, "explain": "Speed stayed 60 km/h, but direction flipped, so velocity changed. Velocity always includes direction."}], "flashcards": [{"type": "flash", "front": "What is the formula for speed?", "back": "Speed = distance ÷ time."}, {"type": "flash", "front": "What is the difference between speed and velocity?", "back": "Velocity is speed plus direction."}, {"type": "flash", "front": "What are the units of acceleration?", "back": "Meters per second squared (m/s²)."}, {"type": "flash", "front": "Give one example of acceleration that isn't speeding up.", "back": "Slowing down, or turning at constant speed — both change velocity."}], "checkpoint": {"pass": 70, "questions": [{"q": "A runner covers 200 m in 40 s. What is the speed?", "choices": ["5 m/s", "8 m/s", "40 m/s"], "answer": 0, "explain": "200 ÷ 40 = 5 m/s. Divide distance by time."}, {"q": "Which of these is accelerating?", "choices": ["A car turning a corner at steady speed", "A car parked at a light", "A car cruising straight at constant speed"], "answer": 0, "explain": "Turning changes direction, and direction is part of velocity. Changing velocity is acceleration."}, {"q": "Why does velocity include direction?", "choices": ["Because motion in opposite directions is physically different", "To make the math harder", "It doesn't — direction is optional"], "answer": 0, "explain": "60 km/h north vs 60 km/h south are different motions with different effects, like momentum."}, {"q": "A ball's velocity changes from 0 to 20 m/s in 4 s. Acceleration?", "choices": ["5 m/s²", "4 m/s²", "80 m/s²"], "answer": 0, "explain": "(20 − 0) ÷ 4 = 5 m/s². Change in velocity over time."}, {"q": "Your answer comes out in m/s but the question asked for acceleration. What's wrong?", "choices": ["The calculation — acceleration needs m/s²", "Nothing, the units are fine", "The question is unanswerable"], "answer": 0, "explain": "Acceleration is velocity change over time, so its units are m/s². Wrong units mean a wrong setup."}]}}, {"id": "physics-2", "title": "Forces", "cards": [{"type": "text", "title": "Objects are lazy: Newton's first law", "body": "An object keeps doing what it's doing unless a force interferes. A puck slides across ice nearly forever because friction is tiny; it stops on carpet because friction is huge. This laziness has a name: inertia, and mass measures how much of it an object has."}, {"type": "text", "title": "F = ma: the most famous equation in physics", "body": "Force equals mass times acceleration. Push twice as hard, get twice the acceleration. Double the mass, halve the acceleration for the same push. And Newton's third law: every push gets pushed back — the rocket pushes exhaust down, the exhaust pushes the rocket up."}, {"type": "tip", "body": "Draw the arrows. A free-body diagram is just the object with every force as an arrow: gravity down, the table pushing up, friction opposing motion. Once the arrows are on paper, F = ma turns into simple addition instead of a word puzzle."}, {"type": "example", "body": "You push a 2 kg box and it accelerates at 3 m/s².\nF = m × a = 2 × 3 = 6 newtons.\n\nSix newtons is about the weight of an apple in your hand — small forces move small masses impressively fast, which is why the numbers deserve a reality check."}, {"type": "check", "q": "A rocket fires exhaust downward and rises. Which law is this?", "choices": ["Newton's third law", "Newton's first law", "Conservation of energy"], "answer": 0, "explain": "Third law: every action has an equal, opposite reaction. Exhaust goes down, rocket goes up."}], "flashcards": [{"type": "flash", "front": "State Newton's first law in one sentence.", "back": "Objects keep their motion unless a net force acts on them."}, {"type": "flash", "front": "What does F = ma mean?", "back": "Force equals mass times acceleration."}, {"type": "flash", "front": "State Newton's third law.", "back": "Every action has an equal and opposite reaction."}, {"type": "flash", "front": "What is inertia?", "back": "An object's resistance to changes in motion; measured by mass."}], "checkpoint": {"pass": 70, "questions": [{"q": "A 4 kg cart accelerates at 2 m/s². What force is pushing it?", "choices": ["8 N", "2 N", "6 N"], "answer": 0, "explain": "F = 4 × 2 = 8 newtons."}, {"q": "Why does a hockey puck glide so far on ice?", "choices": ["Friction is tiny, so almost no force stops it", "Ice pushes it forward", "The puck has no mass"], "answer": 0, "explain": "First law: with barely any friction, the puck keeps its velocity."}, {"q": "You push a wall and it pushes back. You don't move because:", "choices": ["The forces balance — net force on you is zero", "The wall is being polite", "Friction doesn't exist indoors"], "answer": 0, "explain": "The wall's push cancels yours. No net force, no acceleration — that's the third law in action."}, {"q": "Two boxes get the same push. The heavier one accelerates less because:", "choices": ["Greater mass means more inertia (F = ma)", "Heavier objects ignore forces", "Friction only affects heavy things"], "answer": 0, "explain": "For the same force, acceleration = F/m. More mass, less acceleration."}, {"q": "What is the net force on a book sitting still on a table?", "choices": ["Zero — gravity and the table's push cancel", "Equal to its weight", "Impossible to know"], "answer": 0, "explain": "Gravity pulls down, the table pushes up equally. Balanced forces, zero net, zero acceleration."}]}}, {"id": "physics-3", "title": "Energy", "cards": [{"type": "text", "title": "Moving things carry energy", "body": "Kinetic energy is the energy of motion: KE = ½mv². Notice the v² — doubling your speed quadruples the energy, which is why a 100 km/h crash is four times as violent as a 50 km/h one, not twice. Speed is expensive."}, {"type": "text", "title": "Height is stored energy", "body": "Lift something and you store gravitational potential energy: PE = mgh (mass × gravity × height). Drop it and the stored energy converts to motion. A roller coaster is just this trade running back and forth, which is why the first hill is always the tallest."}, {"type": "tip", "body": "Energy never appears or vanishes, it only changes form. This conservation law solves problems that forces can't touch: a pendulum's speed at the bottom follows directly from the height it fell, no stopwatch needed. When stuck, ask: where did the energy go?"}, {"type": "example", "body": "A 2 kg ball sits on a 5 m shelf. Take g = 10 m/s².\nPE = m × g × h = 2 × 10 × 5 = 100 joules.\n\nKnock it off and all 100 J become motion (ignoring air). Conservation of energy just predicted the landing speed without tracking a single force."}, {"type": "check", "q": "Why is a 100 km/h crash four times worse than 50 km/h?", "choices": ["Kinetic energy grows with v²", "Cars get heavier at speed", "Brakes fail above 80 km/h"], "answer": 0, "explain": "KE = ½mv². Double the v, quadruple the energy."}], "flashcards": [{"type": "flash", "front": "What is the formula for kinetic energy?", "back": "KE = ½mv²."}, {"type": "flash", "front": "What is the formula for gravitational potential energy?", "back": "PE = mgh."}, {"type": "flash", "front": "State the conservation of energy.", "back": "Energy can't be created or destroyed, only transformed."}, {"type": "flash", "front": "What are the units of energy?", "back": "Joules (J)."}], "checkpoint": {"pass": 70, "questions": [{"q": "A 1 kg ball moves at 4 m/s. Its kinetic energy?", "choices": ["8 J", "4 J", "16 J"], "answer": 0, "explain": "½ × 1 × 4² = ½ × 16 = 8 joules."}, {"q": "Where does a roller coaster move fastest?", "choices": ["At the lowest point", "At the top of the first hill", "Speed is constant throughout"], "answer": 0, "explain": "Potential energy is lowest at the bottom, so kinetic energy — and speed — is highest there."}, {"q": "You lift a box to a shelf. Where did your effort go?", "choices": ["Into gravitational potential energy", "It vanished as heat only", "Nowhere — lifting is free"], "answer": 0, "explain": "Work becomes stored PE = mgh. Drop the box and it converts back to motion."}, {"q": "What is power?", "choices": ["How fast work gets done (work ÷ time)", "The same thing as energy", "Force times mass"], "answer": 0, "explain": "Power = work/time, in watts. Energy is the amount; power is the rate."}, {"q": "A pendulum swings but each swing is slightly lower. Why?", "choices": ["Friction and air resistance steal energy as heat", "Energy is being destroyed", "Gravity weakens over time"], "answer": 0, "explain": "Energy is conserved overall — some just leaks into heat and sound instead of motion."}]}}]}, {"id": "psych", "title": "Psychology", "icon": "brain", "color": "#A569BD", "levels": [{"id": "psych-1", "title": "How memory works", "cards": [{"type": "text", "title": "Memory has three doors", "body": "Psychologists split memory into three stages. Sensory memory catches everything for a split second, short-term memory holds a handful of items for under a minute, and long-term memory stores things for years. Most of what you experience never makes it past the first door — and that's fine, it keeps you sane."}, {"type": "text", "title": "Short-term memory is tiny", "body": "Your short-term memory holds about 7 items, give or take 2 — a phone number, a grocery list, a stranger's name. It fades in 15 to 30 seconds unless you do something with it. This is why you walk into a room and forget why: the item dropped before it got stored anywhere."}, {"type": "example", "body": "Read this number: 8472916. Look away and try to repeat it backwards. Most people lose it after 4-5 digits. Now try chunking it: 847-29-16. Grouping turns 7 items into 3 chunks, and suddenly it fits. Phone numbers use this trick on purpose."}, {"type": "tip", "body": "Getting something into long-term memory needs three things: attention (you actually noticed it), meaning (it connects to something you know), and repetition spaced over time. Highlighting a page gives you none of the three — that's why it feels productive and isn't."}, {"type": "check", "q": "Why do you forget why you walked into a room?", "choices": ["The item faded from short-term memory before it was stored", "Your brain deleted it on purpose to save space", "You never actually wanted to go there"], "answer": 0, "explain": "Short-term memory fades in 15-30 seconds unless the item gets attention and encoding. Walk too slowly, get distracted once, and it's gone before it reaches long-term storage."}], "flashcards": [{"type": "flash", "front": "What are the three stages of memory?", "back": "Sensory memory, short-term memory, and long-term memory."}, {"type": "flash", "front": "Roughly how many items does short-term memory hold?", "back": "About 7, give or take 2."}, {"type": "flash", "front": "What is chunking?", "back": "Grouping items into fewer, bigger units so more fits in short-term memory (like 847-29-16 instead of 8472916)."}, {"type": "flash", "front": "What three things move a memory into long-term storage?", "back": "Attention, meaning (connection to what you know), and spaced repetition."}], "checkpoint": {"pass": 70, "questions": [{"q": "Which memory stage holds information for years?", "choices": ["Sensory memory", "Long-term memory", "Short-term memory"], "answer": 1, "explain": "Sensory memory lasts a fraction of a second, short-term under a minute. Long-term memory is the archive — years to a lifetime."}, {"q": "How long does an unrehearsed item last in short-term memory?", "choices": ["15 to 30 seconds", "2 to 3 hours", "Exactly one day"], "answer": 0, "explain": "Without rehearsal it decays in 15-30 seconds. That's the window you have to do something with it — repeat it, write it down, or connect it to something."}, {"q": "You remember 847-29-16 more easily than 8472916. What are you using?", "choices": ["Chunking", "Repression", "Priming"], "answer": 0, "explain": "Chunking groups items into fewer units, and memory counts chunks, not digits. Seven digits becomes three chunks — inside the limit."}, {"q": "Which study habit actually builds long-term memory?", "choices": ["Re-reading the chapter the night before", "Testing yourself with spaced recall", "Highlighting every key sentence"], "answer": 1, "explain": "Spaced retrieval forces your brain to reconstruct the memory, which is what strengthens it. Re-reading and highlighting feel fluent but barely register."}, {"q": "Why does paying attention matter for memory?", "choices": ["Attention is the gate: unattended info never gets encoded", "Attention slows forgetting to zero", "It doesn't matter, memory is automatic"], "answer": 0, "explain": "Encoding requires attention. Information you never truly noticed never reaches short-term memory, let alone long-term storage."}]}}, {"id": "psych-2", "title": "Cognitive biases", "cards": [{"type": "text", "title": "Your brain takes shortcuts", "body": "Your brain makes thousands of decisions a day, so it uses mental shortcuts called heuristics. They're fast and usually right — but they misfire in predictable ways. Those predictable misfires are called cognitive biases, and everyone has them, including the experts warning you about them."}, {"type": "text", "title": "Confirmation bias", "body": "Confirmation bias is our habit of noticing and trusting information that agrees with what we already believe, while ignoring what doesn't. Two people can read the same news story and both walk away convinced it proved their point. The bias isn't in the story — it's in the reader."}, {"type": "example", "body": "Anchoring: a store lists a jacket at $400, then marks it down to $160. You feel like you saved $240 — even if the jacket was never worth $400. The first number you saw became the anchor, and every judgment after it drifted toward it."}, {"type": "tip", "body": "You can't delete your biases, but you can build speed bumps: ask 'what would change my mind?', seek out the strongest opposing argument, and distrust decisions that feel too fast and too comfortable at the same time."}, {"type": "check", "q": "You only read news from sources that agree with you. Which bias is that?", "choices": ["Confirmation bias", "Anchoring", "Survivorship bias"], "answer": 0, "explain": "Confirmation bias favors information that confirms existing beliefs and filters out the rest. Anchoring is about first numbers; survivorship bias is about only seeing the winners."}], "flashcards": [{"type": "flash", "front": "What is a cognitive bias?", "back": "A predictable pattern where mental shortcuts (heuristics) misfire and distort judgment."}, {"type": "flash", "front": "What is confirmation bias?", "back": "Favoring information that agrees with what you already believe, while ignoring what doesn't."}, {"type": "flash", "front": "What is anchoring?", "back": "Over-relying on the first piece of information seen — like a $400 'original price' making $160 feel like a steal."}, {"type": "flash", "front": "Can you get rid of your biases?", "back": "No, but you can build speed bumps: seek opposing views and ask what would change your mind."}], "checkpoint": {"pass": 70, "questions": [{"q": "What is a heuristic?", "choices": ["A fast mental shortcut the brain uses to decide quickly", "A type of memory failure", "A conscious logical proof"], "answer": 0, "explain": "Heuristics are quick rules of thumb. They save time and usually work — cognitive biases are the cases where they predictably don't."}, {"q": "A negotiator opens with an absurdly high price. What are they exploiting?", "choices": ["Anchoring", "Confirmation bias", "Hindsight bias"], "answer": 0, "explain": "The first number anchors the negotiation — every counteroffer gets pulled toward it, even when everyone knows the opener was ridiculous."}, {"q": "After an election, everyone claims they 'knew it all along.' That's:", "choices": ["Hindsight bias", "Anchoring", "Availability heuristic"], "answer": 0, "explain": "Hindsight bias makes past events feel more predictable than they were. Nobody actually knew — memory rewrites the uncertainty away."}, {"q": "You fear plane crashes more than car crashes despite the statistics. That's the:", "choices": ["Availability heuristic", "Confirmation bias", "Anchoring"], "answer": 0, "explain": "The availability heuristic judges probability by how easily examples come to mind. Plane crashes are vivid and newsworthy; car crashes are routine and forgettable."}, {"q": "What's the most reliable defense against your own biases?", "choices": ["Deliberately seek the strongest opposing argument", "Trust your gut — it's usually right", "Make decisions as fast as possible"], "answer": 0, "explain": "You can't think your way out of a bias from inside it. Steel-manning the other side is the external check that actually works."}]}}, {"id": "psych-3", "title": "Motivation", "cards": [{"type": "text", "title": "Two kinds of fuel", "body": "Motivation comes in two flavors. Intrinsic motivation is doing something because it's interesting or satisfying — playing guitar because you love the sound. Extrinsic motivation is doing it for a reward or to avoid punishment — practicing because your teacher checks. Both work, but they don't work the same way."}, {"type": "text", "title": "Rewards can backfire", "body": "Here's the twist: paying people for something they already enjoy can kill the enjoyment. Psychologists call it the overjustification effect. Once the reward becomes the reason, the activity feels like work — and when the reward stops, the behavior stops with it."}, {"type": "example", "body": "In a classic study, kids who loved drawing were paid for each drawing. They drew more while the payments lasted — then drew less than before once the payments stopped. The kids who were never paid just kept drawing. The reward rewrote their reason."}, {"type": "tip", "body": "To stay motivated on long goals: make progress visible (checklists, streaks), shrink the next step until starting feels trivial, and protect the intrinsic part — do at least some of it just because you like it, with no reward attached."}, {"type": "check", "q": "What is the overjustification effect?", "choices": ["External rewards can reduce enjoyment of an activity you already liked", "Too much motivation causes burnout", "Rewards always increase long-term motivation"], "answer": 0, "explain": "When a reward becomes the reason for doing something, the intrinsic interest fades. Remove the reward and the behavior often drops below where it started."}], "flashcards": [{"type": "flash", "front": "Intrinsic vs extrinsic motivation?", "back": "Intrinsic: doing it because it's interesting. Extrinsic: doing it for a reward or to avoid punishment."}, {"type": "flash", "front": "What is the overjustification effect?", "back": "When external rewards reduce the enjoyment of something you already liked doing."}, {"type": "flash", "front": "Name three things that sustain motivation on long goals.", "back": "Visible progress, tiny next steps, and protecting the intrinsic enjoyment."}, {"type": "flash", "front": "Why do streaks and checklists help?", "back": "They make progress visible, which feeds motivation without replacing the intrinsic reason."}], "checkpoint": {"pass": 70, "questions": [{"q": "Reading novels for fun, then getting paid per book and losing interest — that's:", "choices": ["The overjustification effect", "Confirmation bias", "Operant extinction"], "answer": 0, "explain": "The payment reframed reading as work. Intrinsic interest got crowded out, so when payments stopped, reading stopped too."}, {"q": "Which is an intrinsic motivator?", "choices": ["Curiosity about how things work", "A cash bonus for finishing", "Fear of being fired"], "answer": 0, "explain": "Curiosity comes from inside — the activity is its own reward. Bonuses and fear are extrinsic: reasons imposed from outside."}, {"q": "What's the best first move on a goal you've been avoiding?", "choices": ["Shrink the next step until starting feels trivial", "Wait until you feel motivated", "Set a bigger, scarier deadline"], "answer": 0, "explain": "Motivation usually follows action, not the other way around. A 2-minute first step gets you moving, and motion creates momentum."}, {"q": "A student studies only to avoid failing. That's primarily:", "choices": ["Extrinsic motivation", "Intrinsic motivation", "No motivation at all"], "answer": 0, "explain": "Avoiding punishment is extrinsic — the reason comes from outside the activity itself. It works, but it's fragile and stressful."}, {"q": "Why does visible progress (streaks, checklists) boost motivation?", "choices": ["It proves effort is paying off, feeding the desire to continue", "It replaces the need for any real goal", "It tricks the brain permanently"], "answer": 0, "explain": "Humans are wired to continue things that show progress. A growing streak is evidence your effort matters — that's fuel."}]}}]}, {"id": "python", "title": "Python", "icon": "code", "color": "#4D96FF", "levels": [{"id": "python-1", "title": "Variables & types", "cards": [{"type": "text", "title": "Variables are labeled boxes", "body": "A variable stores a value under a name so you can use it later: score = 0 creates a box called score holding 0. Python figures out the type by itself — no declarations needed."}, {"type": "text", "title": "Know your four basic types", "body": "int is a whole number (42), float has a decimal (3.14), str is text in quotes (\"hello\"), bool is True or False. Mixing them up causes most beginner errors, so learn to spot each one."}, {"type": "tip", "body": "Stuck on what something is? type() tells you: type(\"7\") says <class 'str'> — quotes make it text, not a number, even though it looks numeric."}, {"type": "example", "body": "name = \"Zoe\"\nage = 20\nis_student = True\n\nA string, an integer, and a boolean, each in a labeled box. Later you can do print(\"Hi, \" + name) and Python fills in Zoe."}, {"type": "check", "q": "What is the type of \"7\" in Python?", "choices": ["str (string)", "int (integer)", "It has no type"], "answer": 0, "explain": "Quotes always mean string in Python. \"7\" is text that happens to look like a number — 7 without quotes is the integer."}], "flashcards": [{"type": "flash", "front": "What is a variable?", "back": "A named box that stores a value for your code to use later."}, {"type": "flash", "front": "Name the four basic types.", "back": "int, float, str, bool."}, {"type": "flash", "front": "What does type() do?", "back": "Reports the type of a value, e.g. type(3.5) is float."}, {"type": "flash", "front": "Why is \"7\" not a number?", "back": "Quotes make it a string. Python sees text, not a numeric value."}], "checkpoint": {"pass": 70, "questions": [{"q": "What does score = 0 do?", "choices": ["Stores 0 in a variable named score", "Checks whether score equals 0", "Deletes the variable score"], "answer": 0, "explain": "A single = assigns. (Checking equality uses ==, with two signs.)"}, {"q": "Which of these is a float?", "choices": ["3.14", "42", "\"3.14\""], "answer": 0, "explain": "The decimal point makes it a float. 42 is an int, and quotes would make it a string."}, {"q": "x = \"10\" then x + 5. What happens?", "choices": ["\"105\"", "TypeError — can't add str and int", "15"], "answer": 1, "explain": "Python refuses to mix text and numbers with +. Convert first: int(\"10\") + 5 gives 15."}, {"q": "Which is a valid variable name?", "choices": ["2nd_place", "my-score", "player_score"], "answer": 2, "explain": "Names use letters, digits, and underscores, and can't start with a digit. Hyphens are subtraction, not allowed."}, {"q": "is_ready = False. What type is is_ready?", "choices": ["bool", "str", "int"], "answer": 0, "explain": "True and False (capital first letter) are booleans — Python's yes/no type."}]}}, {"id": "python-2", "title": "Loops & conditionals", "cards": [{"type": "text", "title": "if makes decisions", "body": "if score > 10: runs its block only when the condition is true. Add elif for more cases and else as the fallback. The colon and the indented block underneath are what make it Python."}, {"type": "text", "title": "for repeats the work", "body": "for i in range(5): runs the block five times with i taking 0, 1, 2, 3, 4. range(n) counts from 0 up to — but not including — n. Loops turn five lines of repetition into two."}, {"type": "tip", "body": "Indentation is not style in Python — it is syntax. The indented block under if or for is the code that belongs to it. One stray space and the program means something else."}, {"type": "example", "body": "for n in range(1, 6):\n    if n % 2 == 0:\n        print(n, \"is even\")\n\nPrints 2, 3... no — prints 2 is even and 4 is even. The loop counts 1-5, the if filters evens. Two ideas, one tiny program."}, {"type": "check", "q": "How many times does for i in range(3): run its block?", "choices": ["Until you stop it", "3 times (i = 0, 1, 2)", "4 times (i = 0, 1, 2, 3)"], "answer": 1, "explain": "range(3) produces 0, 1, 2 — three values, stopping before 3."}], "flashcards": [{"type": "flash", "front": "What does if do?", "back": "Runs a block of code only when its condition is True."}, {"type": "flash", "front": "What values does range(5) produce?", "back": "0, 1, 2, 3, 4 — it stops before 5."}, {"type": "flash", "front": "Why does indentation matter in Python?", "back": "It defines which lines belong to an if/for block — it is syntax, not decoration."}, {"type": "flash", "front": "What does a while loop do?", "back": "Repeats its block as long as its condition stays True."}], "checkpoint": {"pass": 70, "questions": [{"q": "x = 7. Which branch runs? if x > 10: ... elif x > 5: ... else: ...", "choices": ["The elif branch", "The if branch", "The else branch"], "answer": 0, "explain": "7 is not > 10, so the if fails; 7 is > 5, so the elif catches it. Python takes the first true branch."}, {"q": "What prints? for c in \"ab\": print(c)", "choices": ["Nothing — strings can't loop", "a then b, on separate lines", "ab on one line"], "answer": 1, "explain": "Strings are sequences, so for walks each character: a, then b."}, {"q": "Fix the bug: if temperature > 30 print(\"hot\")", "choices": ["Change > to ==", "Add a colon: if temperature > 30:", "Add parentheses: if (temperature) > 30"], "answer": 1, "explain": "Every if needs a colon before its indented block. Without it, Python throws a syntax error."}, {"q": "How do you loop exactly 10 times?", "choices": ["for i in range(1, 10):", "while i < 9:", "for i in range(10):"], "answer": 2, "explain": "range(10) gives 0-9: exactly ten values. range(1, 10) gives only nine."}, {"q": "while True: with no break inside does what?", "choices": ["Loops forever", "Runs once", "Throws an error immediately"], "answer": 0, "explain": "True never becomes False, so the loop never exits. Always give a while loop a way out."}]}}, {"id": "python-3", "title": "Functions", "cards": [{"type": "text", "title": "def packages the work", "body": "def greet(): defines a reusable block; greet() runs it. Writing the def just stores the recipe — nothing happens until you call it with the parentheses."}, {"type": "text", "title": "Inputs in, outputs out", "body": "Parameters are the inputs a function expects: def add(a, b):. return hands a value back to the caller and stops the function immediately. No return? The caller gets None."}, {"type": "tip", "body": "Name functions like actions: calculate_total, send_email, is_valid. If you can't name it as a verb, you probably don't know what it does yet."}, {"type": "example", "body": "def add(a, b):\n    return a + b\n\nresult = add(2, 3)  # result is 5\n\nDefine once, call anywhere. add(10, 20) works just as well — the function doesn't care which numbers you hand it."}, {"type": "check", "q": "What does a function with no return statement give back?", "choices": ["None", "0", "An error"], "answer": 0, "explain": "Falling off the end of a function quietly returns None — Python's 'nothing here' value."}], "flashcards": [{"type": "flash", "front": "How do you define and call a function?", "back": "def name(): to define, name() to call."}, {"type": "flash", "front": "Parameter vs argument?", "back": "Parameter is the name in the definition (a, b); argument is the value passed at call time (2, 3)."}, {"type": "flash", "front": "What does return do?", "back": "Sends a value back to the caller and exits the function immediately."}, {"type": "flash", "front": "What is None?", "back": "Python's 'no value' — what a function returns when it has no return statement."}], "checkpoint": {"pass": 70, "questions": [{"q": "What does greet() do if greet was defined with def greet():?", "choices": ["Creates the function", "Nothing — needs arguments", "Runs the function's code"], "answer": 2, "explain": "The parentheses are the go button. def only defines; calling executes."}, {"q": "def double(n): return n * 2 — what is double(4)?", "choices": ["8", "n * 2", "44"], "answer": 0, "explain": "n becomes 4, 4 * 2 is 8, and return hands 8 back."}, {"q": "Why does this fail? def 2fast(): ...", "choices": ["def needs parentheses", "Functions can't be that short", "Function names can't start with a digit"], "answer": 2, "explain": "Names follow the same rules as variables: letters, digits, underscores, never starting with a digit."}, {"q": "Inside a function: x = 1; x = x + 1; return x. Result?", "choices": ["An error", "2", "1"], "answer": 1, "explain": "x starts at 1, becomes 2, and return sends 2 back. Assignment updates the box."}, {"q": "When should you write a function?", "choices": ["When you need the same logic in more than one place", "For every single line of code", "Only in large programs"], "answer": 0, "explain": "Functions exist to kill repetition. Two or more uses of the same steps is the signal to package them."}]}}]}, {"id": "spanish", "title": "Spanish", "icon": "chat", "color": "#E63946", "levels": [{"id": "spanish-1", "title": "Greetings & basics", "cards": [{"type": "text", "title": "Hola is just the beginning", "body": "Spanish greets by time of day: buenos días (good morning), buenas tardes (good afternoon), buenas noches (good evening/night). Hola works anytime, but matching the hour sounds instantly more natural."}, {"type": "text", "title": "The four magic words", "body": "Por favor (please), gracias (thank you), perdón (sorry/excuse me), and de nada (you're welcome) will carry you through almost any interaction. Learn these four before anything else and doors open."}, {"type": "tip", "body": "The Spanish r: tap the tip of your tongue once against the ridge behind your teeth, like the 'tt' in 'butter' said fast. Pero (but) uses one tap; perro (dog) rolls it longer."}, {"type": "example", "body": "— ¡Hola! ¿Cómo estás? (Hi! How are you?)\n— Muy bien, gracias. ¿Y tú? (Very well, thanks. And you?)\n— ¡Buenos días! (Good morning!)\n\nThree lines, one friendly exchange. Note the upside-down ¿ at the start of questions — it warns you a question is coming."}, {"type": "check", "q": "Someone greets you at 9 AM. Most natural reply?", "choices": ["¡Adiós!", "¡Buenos días!", "¡Buenas noches!"], "answer": 1, "explain": "Buenos días covers the morning. Buenas noches is for night, and adiós means goodbye — the opposite of a greeting."}], "flashcards": [{"type": "flash", "front": "How do you say 'hello'?", "back": "¡Hola!"}, {"type": "flash", "front": "How do you say 'thank you'?", "back": "Gracias."}, {"type": "flash", "front": "How do you say 'please'?", "back": "Por favor."}, {"type": "flash", "front": "How do you say 'goodbye'?", "back": "Adiós."}], "checkpoint": {"pass": 70, "questions": [{"q": "It's 3 PM. You walk into a shop. You say…", "choices": ["¡Buenas tardes!", "¡Buenos días!", "¡Buenas noches!"], "answer": 0, "explain": "Tardes covers afternoon until evening. Días is morning, noches is night."}, {"q": "Someone holds the door for you. You say…", "choices": ["¡Perdón!", "¡Gracias!", "¡Por favor!"], "answer": 1, "explain": "Gracias thanks them. Por favor asks for something; perdón apologizes."}, {"q": "You bump into someone. You say…", "choices": ["¡Perdón!", "¡De nada!", "¡Hola!"], "answer": 0, "explain": "Perdón excuses you. De nada answers a thank-you; hola just greets."}, {"q": "A friend thanks you for help. You reply…", "choices": ["¡Por favor!", "¡Adiós!", "¡De nada!"], "answer": 2, "explain": "De nada means 'you're welcome' — literally 'of nothing.'"}, {"q": "What does the upside-down ¿ do?", "choices": ["Makes the sentence louder", "Marks formal speech", "Warns you a question is starting"], "answer": 2, "explain": "Spanish puts ¿ at the start so you read the whole sentence with question intonation from the beginning."}]}}, {"id": "spanish-2", "title": "Common verbs", "cards": [{"type": "text", "title": "Two verbs for 'to be': ser vs estar", "body": "Ser is for permanent traits: soy alto (I am tall). Estar is for states and locations: estoy cansado (I am tired), estoy en casa (I am at home). Mix them up and 'estoy aburrido' (I'm bored) becomes 'soy aburrido' (I'm a boring person)."}, {"type": "text", "title": "The big three you'll use daily", "body": "Tener (to have), hacer (to do/make), ir (to go). Spanish says tengo hambre (I have hunger) instead of 'I am hungry', and voy a la tienda (I go to the store). These three unlock half of everyday speech."}, {"type": "tip", "body": "Regular -ar verbs: drop the -ar, add -o, -as, -a, -amos, -an. Hablar → hablo, hablas, habla, hablamos, hablan. Learn the pattern once and hundreds of verbs follow it."}, {"type": "example", "body": "Hablar (to speak):\nyo hablo — I speak\ntú hablas — you speak\nél/ella habla — he/she speaks\n\nSame endings work for comprar (to buy), estudiar (to study), trabajar (to work). One pattern, endless verbs."}, {"type": "check", "q": "You're hungry. What do you say?", "choices": ["Estoy hambre", "Tengo hambre", "Soy hambre"], "answer": 1, "explain": "Spanish uses tener for hunger: literally 'I have hunger.' Soy/estoy don't pair with hambre."}], "flashcards": [{"type": "flash", "front": "Ser vs estar — what's the difference?", "back": "Ser = permanent traits (soy alto). Estar = states and locations (estoy cansado)."}, {"type": "flash", "front": "How do you say 'I am hungry'?", "back": "Tengo hambre — Spanish uses 'to have' for hunger."}, {"type": "flash", "front": "Conjugate hablar for 'yo'.", "back": "Hablo. Drop -ar, add -o."}, {"type": "flash", "front": "What does 'ir' mean and give one form.", "back": "To go. Voy = I go."}], "checkpoint": {"pass": 70, "questions": [{"q": "'Soy aburrido' vs 'estoy aburrido' — what's the difference?", "choices": ["One is past tense", "I am a boring person vs I am bored", "They mean the same thing"], "answer": 1, "explain": "Ser makes it a trait (boring person); estar makes it a state (bored right now). The verb changes the meaning."}, {"q": "How do you say 'we speak'?", "choices": ["Hablan", "Hablamos", "Hablo"], "answer": 1, "explain": "The -amos ending marks 'we' for -ar verbs: hablamos."}, {"q": "Which verb means 'to have'?", "choices": ["Tener", "Hacer", "Ir"], "answer": 0, "explain": "Tener = to have, hacer = to do/make, ir = to go."}, {"q": "Complete: Ella ___ en Madrid. (She is in Madrid.)", "choices": ["tiene", "está", "es"], "answer": 1, "explain": "Locations always use estar. Es would describe what she is like, not where she is."}, {"q": "What does 'voy' mean?", "choices": ["I do", "I go", "I have"], "answer": 1, "explain": "Voy is 'I go' from ir — one of the most-used words in the language."}]}}, {"id": "spanish-3", "title": "Everyday phrases", "cards": [{"type": "text", "title": "Getting what you need", "body": "¿Dónde está…? (where is…?), ¿Cuánto cuesta? (how much?), la cuenta, por favor (the bill, please). Three phrases handle shops, restaurants, and getting un-lost."}, {"type": "text", "title": "Small talk that works", "body": "¿Cómo estás? (how are you?), me llamo… (my name is…), ¿hablas inglés? (do you speak English?). People appreciate the effort even when you switch to English after."}, {"type": "tip", "body": "Tú is for friends and peers; usted is formal (strangers, elders, officials). When in doubt with someone older or in a formal setting, usted is the safe choice."}, {"type": "example", "body": "At a restaurant:\n— ¿Una mesa para dos, por favor? (A table for two, please?)\n— ¿Qué recomienda? (What do you recommend?)\n— La cuenta, por favor. (The bill, please.)\n\nPolite, complete, and you never touched English."}, {"type": "check", "q": "Dinner's done. How do you ask for the bill?", "choices": ["¿Cuánto es?", "La cuenta, por favor", "¿Dónde está?"], "answer": 1, "explain": "La cuenta, por favor is the standard phrase. ¿Cuánto es asks the price of something specific."}], "flashcards": [{"type": "flash", "front": "How do you ask 'where is…?'", "back": "¿Dónde está…?"}, {"type": "flash", "front": "How do you ask for the bill?", "back": "La cuenta, por favor."}, {"type": "flash", "front": "How do you introduce yourself?", "back": "Me llamo… (my name is…)."}, {"type": "flash", "front": "How do you ask 'how much is it?'", "back": "¿Cuánto cuesta?"}], "checkpoint": {"pass": 70, "questions": [{"q": "You're lost and need the station. You ask…", "choices": ["¿Cuánto cuesta?", "¿Cómo estás?", "¿Dónde está la estación?"], "answer": 2, "explain": "¿Dónde está…? asks for locations. The others ask prices or make small talk."}, {"q": "You want to know the price of a shirt. You say…", "choices": ["¿Dónde está?", "¿Cuánto cuesta?", "La cuenta, por favor"], "answer": 1, "explain": "¿Cuánto cuesta? = how much does it cost. La cuenta is the restaurant bill."}, {"q": "Meeting someone your age at a party, you use…", "choices": ["vosotros", "tú", "usted"], "answer": 1, "explain": "Tú is for peers and friends. Usted is formal; vosotros is 'you all' (Spain)."}, {"q": "'Me llamo Ana' means…", "choices": ["I call Ana", "Ana calls me", "My name is Ana"], "answer": 2, "explain": "Me llamo is literally 'I call myself' — the standard way to introduce yourself."}, {"q": "A shopkeeper says '¿Algo más?' You hear…", "choices": ["How much?", "Where from?", "Anything else?"], "answer": 2, "explain": "¿Algo más? = anything else? — the classic follow-up after your first request."}]}}]}, {"id": "speak", "title": "Public Speaking", "icon": "mic", "color": "#2980B9", "levels": [{"id": "speak-1", "title": "Beating nerves", "cards": [{"type": "text", "title": "Nerves mean you care", "body": "Shaky hands, dry mouth, racing heart before speaking — that's adrenaline, the same chemical athletes use to perform. It means your body is gearing up, not breaking down. Every experienced speaker still feels it; they've just learned to surf it."}, {"type": "text", "title": "Box breathing, 60 seconds", "body": "Breathe in 4 counts, hold 4, out 4, hold 4. Repeat three or four rounds before you go on. Slow exhales directly dial down your nervous system — it's the fastest physiological calm-down switch you own, and nobody can see you doing it."}, {"type": "tip", "body": "Reframe the feeling: tell yourself 'I'm excited' instead of 'I'm nervous.' Studies show this tiny relabeling improves performance, because excitement and anxiety feel identical in the body — only the story differs."}, {"type": "example", "body": "You're waiting to present in class. Instead of scrolling your phone (which spikes anxiety), you do two rounds of box breathing backstage, roll your shoulders, and whisper your first sentence once. By the time your name is called, the adrenaline has a job instead of a panic."}, {"type": "text", "title": "Preparation is the real cure", "body": "Most stage fright is fear of blanking. The antidote is over-preparing your opening 60 seconds — know it cold. A strong start floods you with confidence, and confidence carries the rest. Winging it is what creates the horror stories."}, {"type": "check", "q": "What's the fastest way to calm your body before speaking?", "choices": ["Slow breathing with long exhales", "Drinking three espressos", "Telling yourself to 'just relax'"], "answer": 0, "explain": "Slow exhales activate the parasympathetic nervous system — a real physiological brake. Caffeine adds fuel to the fire, and 'just relax' is not a technique."}], "flashcards": [{"type": "flash", "front": "What is box breathing?", "back": "In 4 counts, hold 4, out 4, hold 4 — repeat to calm nerves fast."}, {"type": "flash", "front": "Why does 'I'm excited' work better than 'I'm nervous'?", "back": "Excitement and anxiety feel identical physically; relabeling turns the same energy positive."}, {"type": "flash", "front": "What's the best cure for fear of blanking?", "back": "Over-prepare the opening 60 seconds until it's automatic."}, {"type": "flash", "front": "Why do nerves actually happen?", "back": "Adrenaline — your body's performance fuel, not a malfunction."}], "checkpoint": {"pass": 70, "questions": [{"q": "Why do experienced speakers still get nervous?", "choices": ["Adrenaline fires for everyone; they just manage it", "They never actually get nervous", "They forgot their training"], "answer": 0, "explain": "The physiology doesn't vanish with experience. Pros feel the same rush and channel it instead of fighting it."}, {"q": "Box breathing works mainly through...", "choices": ["Long, slow exhales calming the nervous system", "Holding your breath as long as possible", "Breathing as fast as you can"], "answer": 0, "explain": "Extended exhales stimulate the vagus nerve and dial down fight-or-flight. Speed-breathing does the opposite."}, {"q": "Best use of the 5 minutes before you speak?", "choices": ["Breathing exercises and rehearsing your opener", "Scrolling social media", "Memorizing the entire talk word-for-word"], "answer": 0, "explain": "Calm the body, lock in the start. Phones spike anxiety; full-script memorization creates brittle, robotic delivery."}, {"q": "Reframing anxiety as excitement helps because...", "choices": ["The bodily sensations are identical — only the label changes", "Excitement eliminates adrenaline", "Audiences prefer excited speakers"], "answer": 0, "explain": "Same racing heart, different story. 'I'm excited' gives the arousal a positive direction instead of a threat narrative."}, {"q": "The single biggest reducer of stage fright is...", "choices": ["Knowing your opening cold", "Wearing lucky clothes", "Picturing the audience naked"], "answer": 0, "explain": "Blanking on the start is the core fear. An automatic opening buys you 60 seconds of confidence to settle in."}]}}, {"id": "speak-2", "title": "Structure", "cards": [{"type": "text", "title": "Hook, body, close", "body": "Every good talk has three parts: a hook that earns attention in the first 30 seconds, a body that delivers 2-3 clear points, and a close that tells people what to do or remember. Audiences forgive weak middles; they never forgive weak openings or endings."}, {"type": "text", "title": "The rule of three", "body": "People remember things in threes: three reasons, three stories, three steps. Two feels thin, four gets forgotten. 'Life, liberty, and the pursuit of happiness' stuck for 250 years because three is the brain's favorite number."}, {"type": "tip", "body": "Stories beat statistics. One vivid 30-second story about a real person lands harder than five slides of numbers. Data convinces the mind; stories move the feet."}, {"type": "example", "body": "A 3-minute class presentation: Hook — 'Last year, our school threw away 2 tons of food.' Body — three points: where it goes, what it costs, one fix that works. Close — 'Sign the compost petition on your way out.' Thirty seconds, three points, one ask."}, {"type": "text", "title": "Signpost as you go", "body": "Tell them where you are: 'First... Second... Finally...' It sounds simple because it is — and audiences relax when they can see the map. Mystery structure only creates anxiety, not suspense."}, {"type": "check", "q": "What should the first 30 seconds of a talk do?", "choices": ["Hook attention with something vivid", "List your credentials", "Apologize for being nervous"], "answer": 0, "explain": "Attention is earned immediately or lost. Credentials can wait, and apologies just spotlight the nerves you're trying to hide."}], "flashcards": [{"type": "flash", "front": "What are the three parts of a talk?", "back": "Hook (first 30s), body (2-3 points), close (one takeaway or ask)."}, {"type": "flash", "front": "Why does the rule of three work?", "back": "Three items are the most the brain comfortably holds — memorable without overload."}, {"type": "flash", "front": "Stories vs statistics: which persuades more?", "back": "Stories — data convinces minds, stories move people to act."}, {"type": "flash", "front": "What does signposting do for an audience?", "back": "Shows them the map ('first, second, finally') so they relax and follow."}], "checkpoint": {"pass": 70, "questions": [{"q": "Why open with a hook instead of background?", "choices": ["Attention is won or lost in the first 30 seconds", "Background is more important", "Hooks are unprofessional"], "answer": 0, "explain": "You get one shot at attention. Background can come after they're listening."}, {"q": "A talk with five main points will likely...", "choices": ["Lose the audience — three is the memorable max", "Be twice as persuasive", "Take exactly five minutes"], "answer": 0, "explain": "Working memory caps out. Five points blur together; three stick."}, {"q": "Best way to make data persuasive?", "choices": ["Wrap it in a short human story", "Add more decimal places", "Read the spreadsheet aloud"], "answer": 0, "explain": "Stories give numbers meaning and emotion. Raw data rarely moves anyone."}, {"q": "Signposting ('first, second, finally') helps because...", "choices": ["Audiences relax when they see the structure", "It fills time", "It sounds academic"], "answer": 0, "explain": "A visible map reduces listener anxiety and makes points easier to track and recall."}, {"q": "The close of a talk should...", "choices": ["Give one clear takeaway or call to action", "Introduce a brand-new topic", "Summarize every detail"], "answer": 0, "explain": "Endings are remembered. One sharp takeaway beats a comprehensive recap nobody retains."}]}}, {"id": "speak-3", "title": "Delivery", "cards": [{"type": "text", "title": "Pace and the power of pause", "body": "Most beginners sprint. Slow down to about 130 words per minute and pause after key lines — silence feels eternal to you and thoughtful to them. A two-second pause after your main point lets it land instead of evaporating."}, {"type": "text", "title": "Eyes, not slides", "body": "Talk to people, not your deck. Sweep the room, hold eye contact with one person per thought, then move on. If slides exist, they illustrate — you narrate. Reading slides aloud is the fastest way to lose a room."}, {"type": "tip", "body": "Record yourself on your phone, once. You'll instantly hear the 'ums,' the rushing, the flat tone — things no amount of thinking reveals. One recording fixes more than ten pep talks."}, {"type": "example", "body": "Deliver this line two ways: 'Our team cut wait times (pause two beats) by half.' The pause before 'by half' makes the number hit like a drum. Same words, no pause: 'our team cut wait times by half' — and the achievement slides right past everyone."}, {"type": "text", "title": "Gestures from the heart", "body": "Keep gestures above the waist and open — palms visible. Stillness is fine too; fidgeting (pen-clicking, pocket-jingling) is what distracts. Let your hands punctuate, not perform."}, {"type": "check", "q": "Why pause after an important point?", "choices": ["It gives the audience time to absorb it", "It shows you forgot your place", "It makes the talk longer"], "answer": 0, "explain": "Silence after a key line signals weight and lets the idea land. Rushing past it tells the audience it wasn't important."}], "flashcards": [{"type": "flash", "front": "What speaking pace should you aim for?", "back": "About 130 words per minute — slower than conversation."}, {"type": "flash", "front": "How do you use eye contact well?", "back": "One person per thought, then move on — sweep the room."}, {"type": "flash", "front": "What's the fastest way to improve delivery?", "back": "Record yourself once and listen for ums, rushing, and flat tone."}, {"type": "flash", "front": "Where should gestures live?", "back": "Above the waist, open palms — punctuating, not performing."}], "checkpoint": {"pass": 70, "questions": [{"q": "Beginners usually speak...", "choices": ["Too fast — slowing to ~130 wpm helps", "Too slowly", "At exactly the right pace"], "answer": 0, "explain": "Nerves accelerate delivery. Consciously slowing down is the most common and most fixable delivery flaw."}, {"q": "A pause after your main point works because...", "choices": ["Silence signals importance and lets it land", "The audience needs a nap", "It covers forgetting"], "answer": 0, "explain": "Strategic silence is punctuation. It frames the point as worth sitting with."}, {"q": "Slides should...", "choices": ["Illustrate while you narrate", "Contain your full script", "Be as text-heavy as possible"], "answer": 0, "explain": "You're the talk; slides are the backdrop. Reading them aloud duplicates and bores."}, {"q": "One phone recording helps more than pep talks because...", "choices": ["You hear your actual ums, pace, and tone", "Phones have good microphones", "It's fun"], "answer": 0, "explain": "Self-perception lies; recordings don't. One listen reveals every habit to fix."}, {"q": "Fidgeting hurts a talk because...", "choices": ["It distracts from your message", "It shows high energy", "Audiences don't notice"], "answer": 0, "explain": "Pen-clicking and pocket-jingling pull attention to the noise instead of the words. Stillness beats static."}]}}]}, {"color": "#FF6B9D", "icon": "spark", "id": "study", "levels": [{"cards": [{"body": "Your memory fades on a schedule — fast at first, then slower. Psychologists call it the forgetting curve. Spaced repetition beats it by reviewing each fact right before you'd lose it, which flattens the curve a little more every time.", "title": "Your brain deletes on a schedule", "type": "text"}, {"body": "Cramming stuffs facts in for tomorrow's test and dumps them by next week. Spacing the exact same reviews across several days builds memories that actually survive. Same effort, wildly different results.", "title": "Cramming is a scam", "type": "text"}, {"body": "Day 1: learn it. Day 2: review it (feels hard). Day 4: review it (easier now). Day 8: review it (easy). Every successful recall stretches the next gap a little further.", "type": "example"}, {"body": "Miss a flashcard? You'll see it again soon. Nail it three times running? It gets pushed weeks out. The schedule follows your actual memory, not a calendar someone else printed.", "type": "tip"}, {"answer": 0, "choices": ["It builds memories that last", "It's faster in a single sitting", "Tests only check short-term memory"], "explain": "Spacing triggers the brain's long-term storage machinery. Cramming only parks facts in short-term memory, which empties within days.", "q": "Why space out reviews instead of cramming?", "type": "check"}], "checkpoint": {"pass": 70, "questions": [{"answer": 0, "choices": ["Fast at first, then more slowly", "At a steady, even pace", "Only after a full month"], "explain": "That's the forgetting curve: a steep early drop that levels off. Spaced reviews interrupt the drop.", "q": "How does forgetting actually behave over time?"}, {"answer": 0, "choices": ["Reviewing just before you'd forget it", "Studying everything the night before", "Reading the chapter one more time"], "explain": "A well-timed review, when recall takes effort but succeeds, is what strengthens the memory. Effortless re-reading barely registers.", "q": "Which review timing strengthens memory most?"}, {"answer": 1, "choices": ["See it again tomorrow", "Push it weeks into the future", "Remove it from the deck"], "explain": "A miss means the memory is weak, so the interval shrinks. Easy wins earn longer gaps; struggles earn shorter ones.", "q": "You blank on a flashcard. What should the schedule do?"}, {"answer": 0, "choices": ["Because the gaps force real recall from memory", "Because you spend more total hours", "Because writing notes is involved"], "explain": "The magic isn't more hours — it's that each spaced session forces your brain to reconstruct the memory, which is the workout that builds it.", "q": "Why does spacing beat one long study session?"}, {"answer": 0, "choices": ["An app using spaced repetition, a little daily", "One giant cram session the night before", "Skimming notes once a week"], "explain": "Small, well-timed, effortful recalls compound. Everything else is either too rare or too passive.", "q": "Which habit actually builds lasting knowledge?"}]}, "flashcards": [{"back": "The pattern of memory fading quickly at first, then more slowly over time.", "front": "What is the forgetting curve?", "type": "flash"}, {"back": "Scheduling each review just before you'd forget, so every recall strengthens the memory.", "front": "What is spaced repetition?", "type": "flash"}, {"back": "It only loads short-term memory, which empties within days without spaced recalls.", "front": "Why does cramming fail in the long run?", "type": "flash"}, {"back": "Shorten the interval and see it again soon, until recalling it feels easy.", "front": "You keep missing the same card. What now?", "type": "flash"}], "id": "study-1", "title": "Spaced repetition"}, {"cards": [{"body": "Focus is a muscle, and you train it in sprints. The Pomodoro technique: 25 minutes of single-task work, 5 minutes fully off. After four rounds, take a longer break. Knowing focus ends makes starting it far less painful.", "title": "Focus is a muscle: train it in sprints", "type": "text"}, {"body": "Re-reading feels productive and mostly isn't. Active recall — closing the book and dragging the answer out of your own head — builds far stronger memory per minute. Effort is the feature, not the bug.", "title": "Test yourself, don't re-read", "type": "text"}, {"body": "Try the Feynman check: explain the idea out loud as if teaching a bright 10-year-old. No jargon allowed. Every place you stumble is a precise map of what you don't actually know yet.", "type": "example"}, {"body": "Cornell method: notes on the right, key questions on the left, a two-line summary at the bottom. If your notes could have been photocopied from the source, you were transcribing, not learning.", "type": "tip"}, {"answer": 0, "choices": ["Testing yourself from memory", "Re-reading the chapter twice", "Highlighting key sentences"], "explain": "Retrieval practice forces reconstruction, which wires the memory in. Re-reading and highlighting feel fluent but leave almost no trace.", "q": "Which builds stronger memory per minute?", "type": "check"}], "checkpoint": {"pass": 70, "questions": [{"answer": 0, "choices": ["25 minutes of focus, 5 minutes off", "25 hours of nonstop work", "5 minutes of focus, 25 off"], "explain": "The classic Pomodoro is 25 on, 5 off — short enough to start, long enough to matter. Four rounds, then a longer break.", "q": "What is one Pomodoro?"}, {"answer": 0, "choices": ["Closing the book and recalling the answer", "Reading the highlighted parts again", "Copying notes neatly"], "explain": "Active recall means retrieving from memory with no cues. The struggle to remember is literally the learning happening.", "q": "What counts as active recall?"}, {"answer": 0, "choices": ["Exactly what you don't understand yet", "Nothing — it means you're done", "That you need neater handwriting"], "explain": "The Feynman technique turns explanation gaps into a study plan: wherever you can't say it simply, go re-learn that part.", "q": "You try explaining a concept simply and get stuck. What did you just find?"}, {"answer": 0, "choices": ["Questions and cues on the left, summary at the bottom", "A full transcript of the lecture", "Only doodles in the margins"], "explain": "Cornell notes split the page: notes right, questions left, summary bottom. The questions column becomes your self-quiz later.", "q": "What makes Cornell notes different from plain notes?"}, {"answer": 0, "choices": ["Put the phone away and single-task", "Play music with lyrics and multitask", "Study in bed to stay relaxed"], "explain": "Focus sprints need one task and zero pings. Lyrics compete with language processing, and beds cue sleep, not study.", "q": "Which setup makes a Pomodoro actually work?"}]}, "flashcards": [{"back": "25 minutes of single-task focus followed by a 5-minute break.", "front": "What is a Pomodoro?", "type": "flash"}, {"back": "Forcing answers out of your own memory instead of re-reading the source.", "front": "What is active recall?", "type": "flash"}, {"back": "Learning by explaining an idea in simple terms; where you stumble shows what you don't know.", "front": "What is the Feynman technique?", "type": "flash"}, {"back": "Key questions and cues — they become your self-quiz later.", "front": "In Cornell notes, what goes in the left column?", "type": "flash"}], "id": "study-2", "title": "Focus & notes"}], "title": "Study Skills"}, {"color": "#7C3AED", "icon": "globe", "id": "web", "levels": [{"cards": [{"body": "Every website lives on a computer called a server. Your browser asks the server for the page, the server sends it back, and your browser draws it on your screen. That request-and-response dance is the entire web.", "title": "The web in 30 seconds", "type": "text"}, {"body": "A server is just a regular computer that stays on all the time, waiting for requests. When you type a URL and hit enter, your browser sends a request across the internet, and the server replies with files: text, images, and code.", "title": "Servers never sleep", "type": "text"}, {"body": "Request goes out, response comes back. Every click, every form you submit, every page you load follows this rhythm. Once you see it, the web stops feeling like magic.", "type": "tip"}, {"body": "This very lesson did it: your browser asked a server for this page, the server sent back text and code, and your browser turned it into the screen you're reading right now. You just completed a round trip.", "type": "example"}, {"answer": 0, "choices": ["Waits for requests and sends back files", "Draws pages on your screen", "Writes the code for websites"], "explain": "The server's job is simple: sit there, wait for a browser to ask for something, and send the files back. Your browser does all the drawing.", "q": "What does a web server do?", "type": "check"}], "checkpoint": {"pass": 70, "questions": [{"answer": 0, "choices": ["It sends a request to a server", "It draws the page immediately", "It downloads an app"], "explain": "Nothing appears until the browser asks. The request always comes first, then the server responds, then the page renders.", "q": "Your browser wants to show you a website. What happens first?"}, {"answer": 0, "choices": ["On a server", "Inside your browser", "On your Wi-Fi router"], "explain": "Websites live on servers. Your browser just borrows a copy for a little while to show you.", "q": "Where does a website actually live?"}, {"answer": 0, "choices": ["Turns the code into a visible page", "Forwards it to another server", "Deletes it after reading"], "explain": "The browser's whole job is rendering: translating HTML, CSS, and code into the page you see and click.", "q": "What does your browser do with the server's response?"}, {"answer": 0, "choices": ["Clicking a link to load a new page", "Reading text already on your screen", "Closing a browser tab"], "explain": "Clicking a link asks the server for something new — that's a request. Reading what's already loaded needs no trip to the server.", "q": "Which of these counts as a request?"}, {"answer": 0, "choices": ["The page won't load", "The page loads from memory forever", "Your browser builds the page itself"], "explain": "No server, no response, no page. Your browser can't invent a website it was never sent.", "q": "The server is down. What happens when you visit the site?"}]}, "flashcards": [{"back": "An always-on computer that stores websites and sends them to browsers when asked.", "front": "What is a server?", "type": "flash"}, {"back": "The app you browse with (Chrome, Safari, Firefox). It requests pages and turns code into what you see.", "front": "What is a browser?", "type": "flash"}, {"back": "A message your browser sends to a server, asking for a page or a file.", "front": "What is a request?", "type": "flash"}, {"back": "The server's reply: the files your browser needs to display the page.", "front": "What is a response?", "type": "flash"}], "id": "web-1", "title": "How the web works"}, {"cards": [{"body": "HTML (HyperText Markup Language) is the skeleton of every webpage. It describes what is on the page: headings, paragraphs, images, links, buttons. No HTML, no page — everything else is decoration.", "title": "HTML gives pages bones", "type": "text"}, {"body": "HTML is written in tags. <p> opens a paragraph and </p> closes it. Most tags come in pairs that wrap content like bookends, telling the browser exactly what each chunk of text is.", "title": "Tags are the building blocks", "type": "text"}, {"body": "<h1>My first page</h1>\n<p>Hello, world. This is a paragraph.</p>\n<a href=\"https://example.com\">A link</a>\n\nA big heading, a paragraph, and a clickable link — three tags, one tiny webpage.", "type": "example"}, {"body": "Read tags out loud until they stick: <h1> is heading one, the biggest. <p> is paragraph. <a> is anchor, a link. <img> is image. Five tags cover most of the web you see.", "type": "tip"}, {"answer": 0, "choices": ["Shows Hi as a paragraph of text", "Turns Hi into a clickable link", "Makes Hi a big heading"], "explain": "<p> means paragraph. The browser renders whatever sits between <p> and </p> as a block of text.", "q": "What does <p>Hi</p> do?", "type": "check"}], "checkpoint": {"pass": 70, "questions": [{"answer": 0, "choices": ["Describe the structure and content", "Make things colorful and pretty", "Store the site's files"], "explain": "HTML handles structure and meaning. Looks are CSS's department; storage is the server's.", "q": "What is HTML's job on a webpage?"}, {"answer": 0, "choices": ["<h1> is a top-level heading, <p> is a paragraph", "They do the same thing", "<p> is bigger than <h1>"], "explain": "Headings announce sections and rank by importance (<h1> biggest). Paragraphs are plain blocks of text.", "q": "How is <h1> different from <p>?"}, {"answer": 0, "choices": ["It closes the tag that <p> opened", "It deletes the paragraph", "It makes the text bold"], "explain": "The slash marks a closing tag. Whatever sits between <p> and </p> is the paragraph.", "q": "What does the slash in </p> mean?"}, {"answer": 0, "choices": ["<a href=\"https://example.com\">Click here</a>", "<p>Click here</p>", "<h1>Click here</h1>"], "explain": "Only the anchor tag <a> with an href makes a clickable link. The others just display text.", "q": "You want the words Click here to open example.com. Which tag?"}, {"answer": 0, "choices": ["<img>", "<link>", "<photo>"], "explain": "<img> is the image tag (there is no <photo> tag, and <link> is for stylesheets, not pictures).", "q": "Which tag would you use to put a photo on a page?"}]}, "flashcards": [{"back": "HyperText Markup Language.", "front": "What does HTML stand for?", "type": "flash"}, {"back": "A marker like <p> that tells the browser what kind of content follows it.", "front": "What is a tag?", "type": "flash"}, {"back": "<h1>. Headings run <h1> (biggest) down to <h6> (smallest).", "front": "Which tag makes the biggest heading?", "type": "flash"}, {"back": "<a>, with the address in the href attribute: <a href=\"...\">.", "front": "Which tag creates a link, and where does the address go?", "type": "flash"}], "id": "web-2", "title": "HTML: the skeleton"}, {"cards": [{"body": "If HTML is the skeleton, CSS is the clothes, the haircut, and the attitude. It controls colors, fonts, spacing, and layout. Same HTML with different CSS can look like a completely different website.", "title": "CSS is the wardrobe", "type": "text"}, {"body": "A CSS rule points at HTML with a selector. In p { color: red; }, the p selects every paragraph and the rule turns their text red. Selector picks the target, declaration changes it.", "title": "Selectors pick their targets", "type": "text"}, {"body": "p {\n  color: blue;\n  font-size: 20px;\n}\n\nEvery paragraph on the page becomes blue and 20 pixels tall. One rule, whole page restyled.", "type": "example"}, {"body": "A URL is an address for the web. https:// is the protocol (how to get there), example.com is the domain (which building), and /about is the path (which room). Every part has a job.", "title": "URLs are street addresses", "type": "text"}, {"body": "Read a URL left to right: https://shop.example.com/shoes means a secure connection, to example.com, the shop section, the shoes page. You'll never get lost in a link again.", "type": "tip"}, {"answer": 0, "choices": ["Changes how the page looks", "Stores the website's files", "Sends requests to servers"], "explain": "CSS is purely about presentation: colors, fonts, spacing, layout. Content comes from HTML, files live on servers.", "q": "What does CSS do?", "type": "check"}], "checkpoint": {"pass": 70, "questions": [{"answer": 0, "choices": ["How it looks: colors, fonts, layout", "The text content on the page", "Where the site is hosted"], "explain": "CSS only touches presentation. The words and structure (HTML) and the hosting (server) are untouched.", "q": "A page's HTML stays the same but you swap its CSS. What changes?"}, {"answer": 0, "choices": ["Sets the text color to red", "Paints the whole screen red", "Deletes everything red"], "explain": "Declarations live inside the curly braces and change one property — here, the text color of whatever the selector picked.", "q": "What does the declaration color: red do?"}, {"answer": 0, "choices": ["The path: a specific page on the site", "The domain name", "The protocol"], "explain": "Everything after the domain is the path — it points to a specific page or resource on that site.", "q": "In https://news.example.com/today, what is /today?"}, {"answer": 0, "choices": ["It encrypts the connection so others can't snoop", "It makes pages load ten times faster", "It only works on phones"], "explain": "The s stands for secure: https encrypts traffic between you and the server, which matters for logins and payments.", "q": "Why does https matter instead of plain http?"}, {"answer": 0, "choices": ["The selector", "The declaration", "The curly braces"], "explain": "The selector (like p or .title) picks the targets. The declaration block says what to change about them.", "q": "Which part of a CSS rule chooses the elements to style?"}]}, "flashcards": [{"back": "Cascading Style Sheets.", "front": "What does CSS stand for?", "type": "flash"}, {"back": "The selector — it picks which HTML elements the rule applies to.", "front": "In p { color: red; }, what is p?", "type": "flash"}, {"back": "A secure, encrypted connection between your browser and the server.", "front": "What does https:// at the start of a URL mean?", "type": "flash"}, {"back": "The domain — the human-readable address of the website.", "front": "In https://example.com/about, what is example.com?", "type": "flash"}], "id": "web-3", "title": "CSS & URLs"}], "title": "Web Basics"}, {"id": "writing", "title": "Creative Writing", "icon": "pen", "color": "#2C3E50", "levels": [{"id": "writing-1", "title": "Story structure", "cards": [{"type": "text", "title": "Every story is a promise and a payoff", "body": "Act one makes a promise (this is what the story is about). Act two complicates it (everything gets harder). Act three pays it off (the promise kept or broken). Readers forgive slow middles if the promise was juicy and the payoff lands."}, {"type": "text", "title": "Start as late as possible", "body": "Open on the day everything changes, not the morning routine. 'The morning the letter arrived' beats three pages of alarm clocks. Backstory is seasoning — the story starts when trouble does."}, {"type": "example", "body": "Weak opening: 'Mara woke at seven, brushed her teeth, and ate toast. She was twenty-six and worked at a bank.'\nStrong opening: 'The bank fired Mara on a Tuesday, which was inconvenient, because the robbery was scheduled for Wednesday.'\n\nSame character, same facts — one starts at the trouble."}, {"type": "tip", "body": "Outline on one page: promise (act one), worst moment (act two), payoff (act three). If you can't fit it on one page, you don't know the story yet."}, {"type": "check", "q": "Where should a story begin?", "choices": ["On the day everything changes", "With the character's full biography", "At the most peaceful moment"], "answer": 0, "explain": "Start at the trouble. Backstory can arrive later in drips — the opening's job is to make a promise the reader wants kept."}], "flashcards": [{"type": "flash", "front": "Three-act structure", "back": "Setup (promise) → confrontation (complications) → resolution (payoff)."}, {"type": "flash", "front": "Inciting incident", "back": "The event that shatters normal life and launches the story."}, {"type": "flash", "front": "Climax", "back": "The peak confrontation where the promise pays off — everything after is falling action."}, {"type": "flash", "front": "Hook", "back": "The opening line or scene engineered to make the reader need the next one."}], "checkpoint": {"pass": 70, "questions": [{"q": "What does act one mainly do?", "choices": ["Makes a promise about what the story is", "Resolves every conflict", "Shows the final battle"], "answer": 0, "explain": "Act one sets up character, world, and the story question. Resolution is act three's job."}, {"q": "Why 'start as late as possible'?", "choices": ["Readers come for the trouble, not the routine", "Mornings are boring to everyone", "Short stories must be short"], "answer": 0, "explain": "Open where the change happens. Everything before that is throat-clearing the reader skips."}, {"q": "The inciting incident is…", "choices": ["what breaks normal life and starts the plot", "the final showdown", "a flashback to childhood"], "answer": 0, "explain": "It's the disruption — the letter, the firing, the stranger at the door — that makes the story necessary."}, {"q": "A strong hook does what?", "choices": ["Makes the reader need the next line", "Summarizes the whole plot", "Introduces every character"], "answer": 0, "explain": "The hook's only job is momentum. Summaries and full casts can wait; curiosity can't."}, {"q": "Which opening is stronger?", "choices": ["'The bank fired Mara on a Tuesday…'", "'Mara woke at seven and ate toast…'", "'Mara was twenty-six…'"], "answer": 0, "explain": "Trouble on line one beats biography. The firing promises conflict; the toast promises breakfast."}]}}, {"id": "writing-2", "title": "Character & dialogue", "cards": [{"type": "text", "title": "Give every character a want and a need", "body": "The want is what they chase (the promotion, the girl, revenge). The need is what they must learn (humility, courage, letting go). Plot is the want in motion; theme is the need learned. Flat characters have wants without needs."}, {"type": "text", "title": "Dialogue is not conversation", "body": "Real talk is full of ums and weather. Story dialogue is conversation with the boring parts removed and the conflict turned up. Every line should reveal character, advance plot, or both — ideally while the characters avoid saying what they actually mean."}, {"type": "example", "body": "Flat: 'I am angry at you because you lied,' she said angrily.\nAlive: 'Funny,' she said, not looking up from her coffee. 'That's exactly what you told the police.'\n\nSubtext — the meaning underneath the words — is what makes dialogue feel human."}, {"type": "tip", "body": "Read dialogue out loud. If you stumble, so will the reader. If it sounds like nobody you've ever met, rewrite it until it sounds like somebody."}, {"type": "check", "q": "What makes dialogue feel real?", "choices": ["Subtext — meaning underneath the words", "Perfect grammar in every line", "Long speeches explaining feelings"], "answer": 0, "explain": "People dodge, deflect, and imply. Dialogue with subtext feels human; on-the-nose speeches feel like lectures."}], "flashcards": [{"type": "flash", "front": "Want vs. need", "back": "Want: the external goal. Need: the internal lesson. Great arcs deliver both."}, {"type": "flash", "front": "Subtext", "back": "What a line really means beneath its literal words."}, {"type": "flash", "front": "Dialogue tag", "back": "'She said' — invisible is good; flashy tags ('he ejaculated') distract."}, {"type": "flash", "front": "Voice", "back": "A character's distinct way of speaking — word choice, rhythm, what they never say."}], "checkpoint": {"pass": 70, "questions": [{"q": "A character wants revenge but needs forgiveness. The need is…", "choices": ["what they must learn internally", "the villain's plan", "the setting"], "answer": 0, "explain": "Want drives plot, need drives theme. The gap between them is where character growth lives."}, {"q": "Best dialogue tag most of the time?", "choices": ["said", "exclaimed", "interrogated"], "answer": 0, "explain": "'Said' is invisible — readers skip right over it. Fancy tags draw attention to themselves instead of the line."}, {"q": "Two characters discuss weather for a page. Fix it by…", "choices": ["cutting it or loading it with subtext", "adding more weather detail", "making it longer"], "answer": 0, "explain": "Small talk only earns its place when it's really about something else — tension, avoidance, longing."}, {"q": "Distinct character voice comes from…", "choices": ["word choice, rhythm, and what they never say", "fancy vocabulary everywhere", "speaking in riddles"], "answer": 0, "explain": "Voice is pattern: the words they reach for, their cadence, their silences. Consistency beats cleverness."}, {"q": "A character who never changes is…", "choices": ["flat (unless that's the point)", "always bad writing", "impossible to write"], "answer": 0, "explain": "Static characters work as foils or forces of nature — but your protagonist should arc from want to need."}]}}, {"id": "writing-3", "title": "Show, don't tell", "cards": [{"type": "text", "title": "Telling hands over conclusions; showing hands over evidence", "body": "'She was nervous' tells. 'She rearranged the sugar packets into a perfect grid, then started over' shows — and lets the reader feel clever for noticing. Readers trust what they deduce more than what they're told."}, {"type": "text", "title": "Trade adjectives for verbs", "body": "Adjectives describe; verbs do. 'He ran quickly' is fine. 'He sprinted' is better. 'He took the stairs three at a time' is best — now we see the hurry instead of being told about it. Strong verbs carry scenes; adverbs ride along."}, {"type": "example", "body": "Telling: 'The house was creepy.'\nShowing: 'The porch light had been on so long the moths were just gray smudges on the bulb. Nobody had swept the steps since spring.'\n\nSpecific, sensory detail does the haunting for you."}, {"type": "tip", "body": "When you catch yourself writing an emotion word (sad, angry, nervous), stop and ask: what would a camera see? Write that instead."}, {"type": "check", "q": "'She was exhausted' is telling. Showing would be…", "choices": ["'She fell asleep with her shoes on, keys still in her hand'", "'She was very, very tired'", "'Exhaustion filled her completely'"], "answer": 0, "explain": "The camera sees shoes, keys, sleep — evidence the reader assembles into 'exhausted' on their own."}], "flashcards": [{"type": "flash", "front": "Showing", "back": "Presenting sensory evidence so readers infer the meaning themselves."}, {"type": "flash", "front": "Telling", "back": "Handing readers conclusions directly ('he was sad')."}, {"type": "flash", "front": "Strong verb", "back": "A verb that carries the action alone — sprinted, not ran quickly."}, {"type": "flash", "front": "Sensory detail", "back": "Concrete sights, sounds, smells, textures that make a scene real."}], "checkpoint": {"pass": 70, "questions": [{"q": "Why does showing beat telling?", "choices": ["Readers trust what they deduce themselves", "It's always shorter", "Adjectives are banned"], "answer": 0, "explain": "A conclusion the reader reaches feels true. One they're handed feels like homework."}, {"q": "Which verb is strongest?", "choices": ["sprinted", "ran quickly", "moved fast"], "answer": 0, "explain": "Sprinted needs no adverb. The verb does all the work — that's what 'strong' means here."}, {"q": "'The room was messy' becomes showing by…", "choices": ["listing specific sensory details", "adding 'very' before messy", "explaining why mess is bad"], "answer": 0, "explain": "Unmade bed, cold pizza, three mugs — specifics let the reader conclude 'messy' without being told."}, {"q": "The camera test asks…", "choices": ["what would a camera see right now?", "is this scene too long?", "who is the protagonist?"], "answer": 0, "explain": "If a camera couldn't capture it, it's probably telling. Rewrite until the lens can see it."}, {"q": "Adverbs are…", "choices": ["backup singers — useful, but the verb should star", "forbidden in good writing", "more important than verbs"], "answer": 0, "explain": "Adverbs aren't evil, but a strong verb beats verb-plus-adverb nearly every time."}]}}]}];